const lessons = [
{num:1,time:"00:01:30,000 --> 00:01:35,019",arabic:"هَذَا دُكَّانٌ لِلْإِكْرَاءِ؟ هَذَا الدُّكَّانُ لِلْإِكْرَاءِ",segs:[{ar:"هَذَا دُكَّانٌ لِلْإِكْرَاءِ؟",uz:"bu ijaraga beriladigan do'konmi?"},{ar:"هَذَا الدُّكَّانُ لِلْإِكْرَاءِ",uz:"bu do'kon ijaraga beriladi"}],full_uz:"Bu ijaraga beriladigan do'konmi? Bu do'kon ijaraga beriladi.",note:null},
{num:2,time:"00:01:40,780 --> 00:01:48,299",arabic:"مَنْ يَكْتَرِي دُكَّانِي؟ دُكَّانٌ لِلْإِكْرَاءِ؟ هَذَا الدُّكَّانُ لِلْإِكْرَاءِ",segs:[{ar:"مَنْ يَكْتَرِي دُكَّانِي؟",uz:"do'konimni kim ijaraga oladi?"},{ar:"دُكَّانٌ لِلْإِكْرَاءِ؟",uz:"ijaraga beriladigan do'konmi?"},{ar:"هَذَا الدُّكَّانُ لِلْإِكْرَاءِ",uz:"bu do'kon ijaraga beriladi"}],full_uz:"Do'konimni kim ijaraga oladi? Ijaraga beriladigan do'konmi? Bu do'kon ijaraga beriladi.",note:null},
{num:3,time:"00:02:00,000 --> 00:02:02,400",arabic:"دُكَّانٌ لِلْإِكْرَاءِ",segs:null,full_uz:"Ijaraga beriladigan do'kon.",note:null},
{num:4,time:"00:02:02,400 --> 00:02:06,439",arabic:"هَذَا الدُّكَّانُ لِلْإِكْرَاءِ",segs:null,full_uz:"Bu do'kon ijaraga beriladi.",note:null},
{num:5,time:"00:02:23,500 --> 00:02:27,000",arabic:"مَنْ يَكْتَرِي دُكَّانِي؟",segs:null,full_uz:"Do'konimni kim ijaraga oladi?",note:null},
{num:6,time:"00:02:29,560 --> 00:02:38,879",arabic:"مِسْكِينٌ أَحْمَدُ بْنُ حَنْبَلٍ مُنْذُ أَيَّامٍ وَهُوَ يُنَادِي عَلَى دُكَّانِ أَبِيهِ",segs:[{ar:"مِسْكِينٌ أَحْمَدُ بْنُ حَنْبَلٍ",uz:"bechora Ahmad ibn Hanbal"},{ar:"مُنْذُ أَيَّامٍ وَهُوَ يُنَادِي عَلَى دُكَّانِ أَبِيهِ",uz:"bir necha kundan beri otasining do'konini e'lon qilib yuribdi"}],full_uz:"Bechora Ahmad ibn Hanbal bir necha kundan beri otasining do'konini ijaraga berish uchun e'lon qilib yuribdi.",note:null},
{num:7,time:"00:02:38,879 --> 00:02:41,180",arabic:"لَعَلَّهُ يَجِدُ مُسْتَأْجِرًا لَهَا",segs:null,full_uz:"Balki unga ijarachi topar.",note:"مُسْتَأْجِرٌ — ijarachi."},
{num:8,time:"00:02:41,180 --> 00:02:47,180",arabic:"وَمَاذَا تُرِيدُهُ أَنْ يَفْعَلَ يَا أَبَا سَرْحَانَ وَلَا يُوجَدُ مُعِينٌ لَهُمْ إِلَّا هَذِهِ الدُّكَّانُ",segs:[{ar:"وَمَاذَا تُرِيدُهُ أَنْ يَفْعَلَ يَا أَبَا سَرْحَانَ",uz:"uni nima qilishini istaysan, ey Abu Sarhon?"},{ar:"وَلَا يُوجَدُ مُعِينٌ لَهُمْ إِلَّا هَذَا الدُّكَّانُ",uz:"ularga bu do'kondan boshqa yordam beradigan narsa yo'q"}],full_uz:"Uni nima qilishini istaysan, ey Abu Sarhon? Ularga bu do'kondan boshqa yordam beradigan narsa yo'q.",note:null},
{num:9,time:"00:02:47,180 --> 00:02:55,580",arabic:"كَانَ اللَّهُ فِي عَوْنِهِ وَاللَّهِ إِنَّ حَالَهُ وَحَالَ أُمِّهِ لَتُفْطِرُ الْقَلْبَ يَا أَبَا دَلَامَةَ",segs:[{ar:"كَانَ اللَّهُ فِي عَوْنِهِ",uz:"Alloh unga yordamchi bo'lsin"},{ar:"وَاللَّهِ إِنَّ حَالَهُ وَحَالَ أُمِّهِ لَتُفْطِرُ الْقَلْبَ",uz:"Allohga qasamki, uning va onasining ahvoli yurakni ezadi"},{ar:"يَا أَبَا دَلَامَةَ",uz:"ey Abu Daloma"}],full_uz:"Alloh unga yordamchi bo'lsin. Allohga qasamki, uning va onasining ahvoli yurakni ezadi, ey Abu Daloma.",note:null},
{num:10,time:"00:02:55,580 --> 00:03:02,600",arabic:"صَدَقْتَ يَا أَبَا سَرْحَانَ لَقَدْ عَلِمْتُ أَنَّ عَمَّهُ إِسْحَاقَ بْنَ حَنْبَلٍ حَاوَلَ مَدَّ الْعَوْنِ لَهُمْ",segs:[{ar:"صَدَقْتَ يَا أَبَا سَرْحَانَ",uz:"to'g'ri aytding, ey Abu Sarhon"},{ar:"لَقَدْ عَلِمْتُ أَنَّ عَمَّهُ إِسْحَاقَ بْنَ حَنْبَلٍ حَاوَلَ مَدَّ الْعَوْنِ لَهُمْ",uz:"men bildimki, uning amakisi Ishoq ibn Hanbal ularga yordam berishga harakat qilgan"}],full_uz:"To'g'ri aytding, ey Abu Sarhon. Men bildimki, uning amakisi Ishoq ibn Hanbal ularga yordam berishga harakat qilgan.",note:null},
{num:11,time:"00:03:02,600 --> 00:03:07,980",arabic:"فَأَبَتْ عَلَى أَحْمَدَ عِزَّةُ نَفْسِهِ أَنْ يَقْبَلَ الْمُسَاعَدَةَ حَتَّى مِنْ عَمِّهِ",segs:[{ar:"فَأَبَتْ عَلَى أَحْمَدَ عِزَّةُ نَفْسِهِ",uz:"Ahmadning oriyati bunga yo'l qo'ymadi"},{ar:"أَنْ يَقْبَلَ الْمُسَاعَدَةَ حَتَّى مِنْ عَمِّهِ",uz:"hatto amakisidan ham yordam olishga"}],full_uz:"Ahmadning oriyati hatto amakisidan ham yordam olishga yo'l qo'ymadi.",note:"عِزَّةُ النَّفْسِ — oriyat, o'z qadrini saqlash."},
{num:12,time:"00:03:07,980 --> 00:03:14,780",arabic:"هَكَذَا رَبَّتْهُ صَفِيَّةُ الشَّيْبَانِيَّةُ أُمُّهُ عَلَى عِزَّةِ النَّفْسِ وَالتَّرَفُّعِ عَنِ الِافْتِقَارِ إِذَا غَيَّرَ اللَّهُ",segs:[{ar:"هَكَذَا رَبَّتْهُ صَفِيَّةُ الشَّيْبَانِيَّةُ أُمُّهُ",uz:"onasi Safiya ash-Shayboniya uni shunday tarbiyalagan"},{ar:"عَلَى عِزَّةِ النَّفْسِ وَالتَّرَفُّعِ عَنِ الِافْتِقَارِ",uz:"oriyatli bo'lish va muhtojlikdan o'zini yuksak tutishga"}],full_uz:"Onasi Safiya ash-Shayboniya uni oriyatli bo'lish va muhtojlikdan o'zini yuksak tutishga shunday tarbiyalagan.",note:"التَّرَفُّعُ عَنِ الِافْتِقَارِ — muhtojlikdan o'zini yuksak tutish."},
{num:13,time:"00:03:14,780 --> 00:03:23,380",arabic:"لَقَدْ أَخْبَرَتْنِي زَوْجَتِي أُمُّ سَرْحَانَ أَنَّ أُمَّ أَحْمَدَ صَفِيَّةَ هِيَ مَنْ رَفَضَتْ قَبُولَ الْمُسَاعَدَةِ مِنْ عَمِّهِ إِسْحَاقَ بْنِ حَنْبَلٍ",segs:[{ar:"لَقَدْ أَخْبَرَتْنِي زَوْجَتِي أُمُّ سَرْحَانَ",uz:"xotinim Ummu Sarhon menga aytdiki"},{ar:"أَنَّ أُمَّ أَحْمَدَ صَفِيَّةَ هِيَ مَنْ رَفَضَتْ قَبُولَ الْمُسَاعَدَةِ",uz:"Ahmadning onasi Safiya yordamni qabul qilishdan bosh tortgan"},{ar:"مِنْ عَمِّهِ إِسْحَاقَ بْنِ حَنْبَلٍ",uz:"uning amakisi Ishoq ibn Hanbaldan"}],full_uz:"Xotinim Ummu Sarhon menga aytdiki, Ahmadning onasi Safiya uning amakisi Ishoq ibn Hanbaldan yordam olishni rad etgan.",note:null},
{num:14,time:"00:03:23,380 --> 00:03:25,160",arabic:"إِبَاءً وَعِزَّةَ نَفْسٍ",segs:null,full_uz:"Oriyat va o'z qadrini saqlash tufayli.",note:"إِبَاءٌ — bosh tortish, oriyat."},
{num:15,time:"00:03:25,159 --> 00:03:31,159",arabic:"مَنْ يَكْتَرِي دُكَّانِي؟",segs:null,full_uz:"Do'konimni kim ijaraga oladi?",note:null},
{num:16,time:"00:03:34,539 --> 00:03:58,539",arabic:"لَقَدْ تَأَخَّرَ الرَّدُّ كَثِيرًا وَالْوَقْتُ يُدَاهِمُ وَلَا يَنْتَظِرُ",segs:[{ar:"لَقَدْ تَأَخَّرَ الرَّدُّ كَثِيرًا",uz:"javob juda kechikdi"},{ar:"وَالْوَقْتُ يُدَاهِمُ وَلَا يَنْتَظِرُ",uz:"va vaqt oz qolmoqda, u kutmaydi"}],full_uz:"Javob juda kechikdi, vaqt esa oz qolmoqda va kutmaydi.",note:null},
{num:17,time:"00:03:58,539 --> 00:04:01,560",arabic:"كَلَّا يَجِبُ أَنْ يَكُونَ الرَّدُّ بَيْنَ أَيْدِينَا الْآنَ",segs:[{ar:"كَلَّا",uz:"yo'q"},{ar:"يَجِبُ أَنْ يَكُونَ الرَّدُّ بَيْنَ أَيْدِينَا الْآنَ",uz:"javob hozir bizning qo'limizda bo'lishi kerak"}],full_uz:"Yo'q, javob hozir bizning qo'limizda bo'lishi kerak.",note:null},
{num:18,time:"00:04:01,560 --> 00:04:05,039",arabic:"سَيَأْتِي الرَّدُّ إِنْ شَاءَ اللَّهُ يَا سَيِّدِي",segs:[{ar:"سَيَأْتِي الرَّدُّ إِنْ شَاءَ اللَّهُ",uz:"javob keladi, inshaalloh"},{ar:"يَا سَيِّدِي",uz:"ey janob"}],full_uz:"Javob keladi, inshaalloh, ey janob.",note:null},
{num:19,time:"00:04:05,039 --> 00:04:09,719",arabic:"كُلُّ لَحْظَةٍ تَمُرُّ يُحَدِّقُ الْخَطَرُ بِنَا أَكْثَرَ يَا مَسْعُودُ",segs:[{ar:"كُلُّ لَحْظَةٍ تَمُرُّ يُحَدِّقُ الْخَطَرُ بِنَا أَكْثَرَ",uz:"har o'tgan lahzada xavf bizni yanada ko'proq qurshamoqda"},{ar:"يَا مَسْعُودُ",uz:"ey Mas'ud"}],full_uz:"Har o'tgan lahzada xavf bizni yanada ko'proq qurshamoqda, ey Mas'ud.",note:null},
{num:20,time:"00:04:09,719 --> 00:04:12,819",arabic:"إِنَّ عُيُونَ هَارُونَ الرَّشِيدِ فِي كُلِّ مَكَانٍ",segs:null,full_uz:"Horisun ar-Rashidning josuslari har joyda.",note:"عُيُونٌ — josuslar, kuzatuvchilar."},
{num:21,time:"00:04:12,819 --> 00:04:14,960",arabic:"إِنْ عَلِمَ هَارُونُ بِالْأَمْرِ",segs:null,full_uz:"Agar Horun bu ishdan xabar topsa.",note:null},
{num:22,time:"00:04:14,960 --> 00:04:18,420",arabic:"طَارَتْ رِقَابُنَا أَسْرَعَ مِنْ طَيَرَانِ تِلْكَ الْحَمَامَةِ",segs:[{ar:"طَارَتْ رِقَابُنَا",uz:"boshlarimiz uchadi"},{ar:"أَسْرَعَ مِنْ طَيَرَانِ تِلْكَ الْحَمَامَةِ",uz:"o'sha kaptarning uchishidan ham tezroq"}],full_uz:"Boshlarimiz o'sha kaptarning uchishidan ham tezroq uchadi.",note:null},
{num:23,time:"00:04:18,420 --> 00:04:20,579",arabic:"الَّتِي نَنْتَظِرُ رَسُولَهَا بِفَارِغِ الصَّبْرِ",segs:null,full_uz:"Biz uning xabarchisini sabrsizlik bilan kutyapmiz.",note:"بِفَارِغِ الصَّبْرِ — katta sabrsizlik bilan, sabrsizlikdan."},
{num:24,time:"00:04:20,579 --> 00:04:25,699",arabic:"إِنْ لَمْ تَصِلْنَا الْأَوَامِرُ فَقَدْ ضَاعَ كُلُّ شَيْءٍ",segs:[{ar:"إِنْ لَمْ تَصِلْنَا الْأَوَامِرُ",uz:"agar buyruqlar bizga yetib kelmasa"},{ar:"فَقَدْ ضَاعَ كُلُّ شَيْءٍ",uz:"hamma narsa barbod bo'ladi"}],full_uz:"Agar buyruqlar bizga yetib kelmasa, hamma narsa barbod bo'ladi.",note:null},
{num:25,time:"00:05:01,560 --> 00:05:07,079",arabic:"سَحْقًا لِهَذَا الْفَتَى الْمَأْفُونِ",segs:[{ar:"سَحْقًا لِهَذَا الْفَتَى",uz:"bu tentak bolaga la'nat bo'lsin"},{ar:"الْمَأْفُونِ",uz:"telbalikka yaqin, ahmoq"}],full_uz:"Bu tentak bolaga la'nat bo'lsin.",note:"مَأْفُونٌ — ahmoq, esi past."},
{num:26,time:"00:05:07,079 --> 00:05:10,060",arabic:"كَيْفَ يَسْرِقُ حَمَامَةَ زَاجِرٍ",segs:null,full_uz:"Qanday qilib u xabarchi kaptarni o'g'irlaydi?",note:null},
{num:27,time:"00:05:10,060 --> 00:05:12,560",arabic:"أَلَا يَعْلَمُ أَنَّ ذَلِكَ مَحْظُورٌ",segs:null,full_uz:"U buning taqiqlanganini bilmaydimi?",note:"مَحْظُورٌ — taqiqlangan."},
{num:28,time:"00:05:14,560 --> 00:05:19,240",arabic:"هَذِهِ لِهَذِهِ",segs:null,full_uz:"Bu buniki.",note:null},
{num:29,time:"00:05:19,240 --> 00:05:21,860",arabic:"رَاحَ هُنَا يَا عَامِرُ",segs:[{ar:"رَاحَ هُنَا",uz:"bu yerga qo'yildi"},{ar:"يَا عَامِرُ",uz:"ey Omir"}],full_uz:"Bu yerga qo'yildi, ey Omir.",note:null},
{num:30,time:"00:05:27,920 --> 00:05:30,199",arabic:"بَقِيَتْ هَذِهِ",segs:null,full_uz:"Bu qoldi.",note:null},
{num:31,time:"00:05:30,199 --> 00:05:32,300",arabic:"أَيُّهَا الْكَسُولُ الْأَحْمَقُ",segs:null,full_uz:"Ey dangasa ahmoq.",note:null},
{num:32,time:"00:05:32,759 --> 00:05:33,240",arabic:"اِنْهَضْ",segs:null,full_uz:"Tur.",note:null},
{num:33,time:"00:05:33,240 --> 00:05:36,639",arabic:"قُلْتُ لَكَ غَيْرَ مَرَّةٍ اِجْلِسْ فِي إِحْدَى زَوَايَا السُّوقِ",segs:[{ar:"قُلْتُ لَكَ غَيْرَ مَرَّةٍ",uz:"senga bir necha marta aytdim"},{ar:"اِجْلِسْ فِي إِحْدَى زَوَايَا السُّوقِ",uz:"bozorning bir burchagiga o'tir"}],full_uz:"Senga bir necha marta aytdim: bozorning bir burchagiga o'tir.",note:null},
{num:34,time:"00:05:36,639 --> 00:05:39,379",arabic:"لِتُصْلِحَ نِعَالًا لِلْمَرَّةِ هُنَاكَ",segs:null,full_uz:"U yerda oyoq kiyimlarni tuzatish uchun.",note:null},
{num:35,time:"00:05:39,379 --> 00:05:40,199",arabic:"اِنْهَضْ",segs:null,full_uz:"Tur.",note:null},
{num:36,time:"00:05:41,279 --> 00:05:42,379",arabic:"اِنْهَضْ",segs:null,full_uz:"Tur.",note:null},
{num:37,time:"00:05:42,379 --> 00:05:48,300",arabic:"أُمِّي لَمْ أَتْرُكْ مَكَانًا إِلَّا وَطَرَدَنِي مِنْهُ صَاحِبُ الشُّرْطَةِ",segs:[{ar:"أُمِّي",uz:"onajon"},{ar:"لَمْ أَتْرُكْ مَكَانًا إِلَّا وَطَرَدَنِي مِنْهُ صَاحِبُ الشُّرْطَةِ",uz:"biror joy qoldirmadim, ammo politsiya xodimi meni u yerdan haydab yubordi"}],full_uz:"Onajon, biror joy qoldirmadim, ammo politsiya xodimi meni u yerdan haydab yubordi.",note:null},
{num:38,time:"00:05:48,300 --> 00:05:49,519",arabic:"مَاذَا أَفْعَلُ؟",segs:null,full_uz:"Nima qilay?",note:null},
{num:39,time:"00:05:49,519 --> 00:05:53,199",arabic:"وَهَلْ خَلَتْ بَغْدَادُ مِنَ الْأَمَاكِنِ الَّتِي يُمْكِنُكَ الْعَمَلُ فِيهَا؟",segs:[{ar:"وَهَلْ خَلَتْ بَغْدَادُ مِنَ الْأَمَاكِنِ",uz:"Bag'dodda joylar qolmadimi"},{ar:"الَّتِي يُمْكِنُكَ الْعَمَلُ فِيهَا؟",uz:"sen ishlashing mumkin bo'lgan?"}],full_uz:"Bag'dodda sen ishlashing mumkin bo'lgan joylar qolmadimi?",note:null},
{num:40,time:"00:05:54,439 --> 00:05:57,000",arabic:"أُمِّي وَأَيْنَ سَأَجِدُ هَذَا الْمَكَانَ يَا أُمِّي؟",segs:[{ar:"أُمِّي وَأَيْنَ سَأَجِدُ هَذَا الْمَكَانَ",uz:"onajon, men bu joyni qayerdan topaman"},{ar:"يَا أُمِّي؟",uz:"ey onajon?"}],full_uz:"Onajon, men bu joyni qayerdan topaman, ey onajon?",note:null},
{num:41,time:"00:05:57,000 --> 00:05:59,719",arabic:"كُلَّمَا جَلَسْتُ قُرْبَ السُّوقِ جَاءَ رِجَالُ الشُّرْطَةِ وَطَرَدُونِي",segs:[{ar:"كُلَّمَا جَلَسْتُ قُرْبَ السُّوقِ",uz:"har safar bozor yaqinida o'tirsam"},{ar:"جَاءَ رِجَالُ الشُّرْطَةِ وَطَرَدُونِي",uz:"politsiya xodimlari kelib meni haydashadi"}],full_uz:"Har safar bozor yaqinida o'tirsam, politsiya xodimlari kelib meni haydashadi.",note:null},
{num:42,time:"00:05:59,720 --> 00:06:04,140",arabic:"وَفِي الْمَرَّةِ الْأَخِيرَةِ يَا أُمِّي كَانُوا يَقْبِضُونَ عَلَيَّ وَيَزُجُّونَ بِي فِي السِّجْنِ",segs:[{ar:"وَفِي الْمَرَّةِ الْأَخِيرَةِ يَا أُمِّي",uz:"oxirgi safar esa, onajon"},{ar:"كَانُوا يَقْبِضُونَ عَلَيَّ وَيَزُجُّونَ بِي فِي السِّجْنِ",uz:"ular meni qo'lga olib, qamoqqa tashlamoqchi bo'lishdi"}],full_uz:"Oxirgi safar esa, onajon, ular meni qo'lga olib, qamoqqa tashlamoqchi bo'lishdi.",note:"يَزُجُّونَ بِي — meni qamoqqa tashlaydilar."},
{num:43,time:"00:06:04,140 --> 00:06:11,060",arabic:"دَوْمًا لَا أَجِدُ مِنْكَ إِلَّا التَّذْمُرَ وَالْحُجَجَ الَّتِي تُسَوِّغُ بِهَا كَسَلَكَ وَعَجْزَكَ",segs:[{ar:"دَوْمًا لَا أَجِدُ مِنْكَ إِلَّا التَّذَمُّرَ وَالْحُجَجَ",uz:"sendan doimo faqat nolish va bahonalarni eshitaman"},{ar:"الَّتِي تُسَوِّغُ بِهَا كَسَلَكَ وَعَجْزَكَ",uz:"ular bilan dangasaliging va ojizligingni oqlaysan"}],full_uz:"Sendan doimo faqat nolish va dangasaliging hamda ojizligingni oqlaydigan bahonalarni eshitaman.",note:"التَّذَمُّرُ — nolish."},
{num:44,time:"00:06:11,060 --> 00:06:18,400",arabic:"آهْ يَا أُمِّي آهْ لَوْ كَانَ لَدَيْنَا دُكَّانٌ فِي قَلْبِ السُّوقِ لَكَانَ حَالُنَا غَيْرَ هَذَا الْحَالِ",segs:[{ar:"آهْ يَا أُمِّي آهْ",uz:"oh, onajon, oh"},{ar:"لَوْ كَانَ لَدَيْنَا دُكَّانٌ فِي قَلْبِ السُّوقِ",uz:"agar bozorning o'rtasida do'konimiz bo'lganida edi"},{ar:"لَكَانَ حَالُنَا غَيْرَ هَذَا الْحَالِ",uz:"ahvolimiz bunday bo'lmagan bo'lardi"}],full_uz:"Oh, onajon, agar bozorning o'rtasida do'konimiz bo'lganida edi, ahvolimiz bunday bo'lmagan bo'lardi.",note:null},
{num:45,time:"00:06:18,400 --> 00:06:27,720",arabic:"أُمِّي مَا بِكِ يَا أُمِّي أُمِّي إِلَى أَيْنَ تَذْهَبِينَ أُمِّي مَا بِكِ؟",segs:[{ar:"أُمِّي مَا بِكِ يَا أُمِّي",uz:"onajon, sizga nima bo'ldi?"},{ar:"أُمِّي إِلَى أَيْنَ تَذْهَبِينَ",uz:"onajon, qayerga ketyapsiz?"},{ar:"أُمِّي مَا بِكِ؟",uz:"onajon, sizga nima bo'ldi?"}],full_uz:"Onajon, sizga nima bo'ldi? Onajon, qayerga ketyapsiz? Onajon, sizga nima bo'ldi?",note:null},
{num:46,time:"00:06:27,720 --> 00:06:29,720",arabic:"مَا بِهَا أُمِّي عَامِرُ",segs:[{ar:"مَا بِهَا أُمِّي",uz:"onamga nima bo'ldi?"},{ar:"عَامِرُ",uz:"Omir"}],full_uz:"Onamga nima bo'ldi, Omir?",note:null},
{num:47,time:"00:06:30,720 --> 00:06:31,720",arabic:"أُمِّي",segs:null,full_uz:"Onajon.",note:null},
{num:48,time:"00:06:34,720 --> 00:06:35,720",arabic:"أَيْنَ كُنَّا",segs:null,full_uz:"Qayerda edik?",note:null},
{num:49,time:"00:06:35,720 --> 00:06:40,720",arabic:"كُنَّا",segs:null,full_uz:"Biz edik.",note:null},
{num:50,time:"00:06:47,720 --> 00:06:48,720",arabic:"آهٍ مِنْكَ يَا أُمَّ عَامِرٍ",segs:null,full_uz:"Oh, sendan, ey Ummi Omir.",note:null},
{num:51,time:"00:06:49,720 --> 00:06:50,720",arabic:"سَأَضْطَرُّ لِلْبَدْءِ مِنْ جَدِيدٍ",segs:null,full_uz:"Hammasini boshidan boshlashga majbur bo'laman.",note:"اِضْطَرَّ — majbur bo'lmoq."},
{num:52,time:"00:06:51,720 --> 00:06:52,720",arabic:"هَذَا لِهَذِهِ",segs:null,full_uz:"Bu buniki.",note:null},
{num:53,time:"00:06:53,720 --> 00:06:55,720",arabic:"لَسْتُ أَدْرِي يَا أَحْمَدُ مَا سَبَبُ عِنَادِكَ هَذَا",segs:[{ar:"لَسْتُ أَدْرِي يَا أَحْمَدُ",uz:"bilmayman, ey Ahmad"},{ar:"مَا سَبَبُ عِنَادِكَ هَذَا",uz:"bu qaysarligingning sababi nima"}],full_uz:"Bilmayman, ey Ahmad, bu qaysarligingning sababi nima.",note:"عِنَادٌ — qaysarlik."},
{num:54,time:"00:06:55,720 --> 00:07:11,000",arabic:"مَا سَبَبُ عِنَادِكَ هَذَا؟ أَنَا عَمُّكَ، اعْتَبِرْنِي فِي مَقَامِ أَخِيكَ الْأَكْبَرِ، لَسْتُ رَجُلًا غَرِيبًا حَتَّى تَرْفُضَ مُسَاعَدَتِي لَكَ، إِنْ كَانَ ذَلِكَ يُضِيقُكَ فَاعْتَبِرْ مَا أُقَدِّمُهُ لَكَ دَيْنًا، تَرُدُّهُ لِي حِينَ يَفْتَحُ اللَّهُ لَكَ، لَكِنَّنِي أَرْغَبُ",segs:[{ar:"مَا سَبَبُ عِنَادِكَ هَذَا؟",uz:"bu qaysarligingning sababi nima?"},{ar:"أَنَا عَمُّكَ، اعْتَبِرْنِي فِي مَقَامِ أَخِيكَ الْأَكْبَرِ",uz:"men amakingman, meni katta akang o'rnida deb bil"},{ar:"لَسْتُ رَجُلًا غَرِيبًا حَتَّى تَرْفُضَ مُسَاعَدَتِي لَكَ",uz:"men senga begona odam emasmanki, yordamimni rad etsang"},{ar:"إِنْ كَانَ ذَلِكَ يُضِيقُكَ فَاعْتَبِرْ مَا أُقَدِّمُهُ لَكَ دَيْنًا",uz:"agar bu seni noqulay ahvolga solsa, men berayotgan narsani qarz deb bil"},{ar:"تَرُدُّهُ لِي حِينَ يَفْتَحُ اللَّهُ لَكَ",uz:"Alloh senga yo'l ochganda uni menga qaytararsan"},{ar:"لَكِنَّنِي أَرْغَبُ",uz:"lekin men istayman"}],full_uz:"Bu qaysarligingning sababi nima? Men amakingman, meni katta akang o'rnida deb bil. Men senga begona odam emasmanki, yordamimni rad etsang. Agar bu seni noqulay ahvolga solsa, men berayotgan narsani qarz deb bil. Alloh senga yo'l ochganda uni menga qaytararsan. Lekin men istayman.",note:null},
{num:55,time:"00:07:11,000 --> 00:07:17,140",arabic:"شَكَرَ اللَّهُ صَنِيعَكَ يَا عَمَّهُ، وَقَدْ تَحَدَّثْنَا فِي هَذَا الْأَمْرِ غَيْرَ مَرَّةٍ، وَأَنْتَ تَعْرِفُ رَأْيِي فِيهِ",segs:[{ar:"شَكَرَ اللَّهُ صَنِيعَكَ يَا عَمَّهُ",uz:"Alloh qilgan yaxshiliging uchun seni mukofotlasin, amaki"},{ar:"وَقَدْ تَحَدَّثْنَا فِي هَذَا الْأَمْرِ غَيْرَ مَرَّةٍ",uz:"bu masala haqida bir necha bor gaplashganmiz"},{ar:"وَأَنْتَ تَعْرِفُ رَأْيِي فِيهِ",uz:"sen bu boradagi fikrimni bilasan"}],full_uz:"Alloh qilgan yaxshiliging uchun seni mukofotlasin, amaki. Bu masala haqida bir necha bor gaplashganmiz va sen bu boradagi fikrimni bilasan.",note:null},
{num:56,time:"00:07:17,139 --> 00:07:21,959",arabic:"أَحْمَدُ، إِلَى مَتَى سَتَبْقَى عَلَى هَذِهِ الْحَالِ أَنْتَ وَأُمُّكَ؟",segs:[{ar:"إِلَى مَتَى سَتَبْقَى عَلَى هَذِهِ الْحَالِ",uz:"qachongacha shu holatda qolasiz"},{ar:"أَنْتَ وَأُمُّكَ؟",uz:"sen va onang?"}],full_uz:"Sen va onang qachongacha shu holatda qolasiz?",note:null},
{num:57,time:"00:07:21,959 --> 00:07:27,039",arabic:"هَا أَنْتَ ذَا مُنْذُ أَيَّامٍ تُنَادِي عَلَى دُكَّانِ أَبِيكَ لَعَلَّكَ تَجِدُ مَنْ يَكْتَرِيهِ دُونَ فَائِدَةٍ",segs:[{ar:"هَا أَنْتَ ذَا مُنْذُ أَيَّامٍ تُنَادِي عَلَى دُكَّانِ أَبِيكَ",uz:"mana bir necha kundan beri otangning do'konini ijaraga berishga chaqirib yuribsan"},{ar:"لَعَلَّكَ تَجِدُ مَنْ يَكْتَرِيهِ دُونَ فَائِدَةٍ",uz:"balki uni ijaraga oladigan odam toparsan, ammo foydasiz"}],full_uz:"Mana bir necha kundan beri otangning do'konini ijaraga berishga chaqirib yuribsan, ammo foydasi bo'lmayapti.",note:null},
{num:58,time:"00:07:27,039 --> 00:07:30,939",arabic:"إِنَّ مَعَ الْعُسْرِ يُسْرًا يَا عَمَّاهُ، إِنَّ مَعَ الْعُسْرِ يُسْرًا",segs:[{ar:"إِنَّ مَعَ الْعُسْرِ يُسْرًا",uz:"albatta, qiyinchilik bilan birga yengillik bor"},{ar:"يَا عَمَّاهُ",uz:"ey amaki"},{ar:"إِنَّ مَعَ الْعُسْرِ يُسْرًا",uz:"albatta, qiyinchilik bilan birga yengillik bor"}],full_uz:"Albatta, qiyinchilik bilan birga yengillik bor, ey amaki. Albatta, qiyinchilik bilan birga yengillik bor.",note:null},
{num:59,time:"00:07:30,939 --> 00:07:36,240",arabic:"وَإِنَّمَا جِدْ مُسْتَأْجِرًا لِلدُّكَّانِ، ضَرَبْتُ فِي الْأَرْضِ بَحْثًا عَنِ الْعَمَلِ",segs:[{ar:"وَإِنَّمَا جِدْ مُسْتَأْجِرًا لِلدُّكَّانِ",uz:"sen esa do'konga ijarachi topishga harakat qil"},{ar:"ضَرَبْتُ فِي الْأَرْضِ بَحْثًا عَنِ الْعَمَلِ",uz:"men esa ish izlab yurt bo'ylab kezdim"}],full_uz:"Sen do'konga ijarachi topishga harakat qil, men esa ish izlab yurt bo'ylab kezdim.",note:null},
{num:60,time:"00:07:40,959 --> 00:07:44,519",arabic:"لَكِنْ عِدْنِي أَلَّا تَنْسَى إِنْ ضَاقَتْ بِكَ السُّبُلُ",segs:[{ar:"لَكِنْ عِدْنِي",uz:"lekin menga va'da ber"},{ar:"أَلَّا تَنْسَى إِنْ ضَاقَتْ بِكَ السُّبُلُ",uz:"yo'llaring torayib qolsa, meni unutmaslikka"}],full_uz:"Lekin yo'llaring torayib qolsa, meni unutmaslikka va'da ber.",note:null},
{num:61,time:"00:07:44,519 --> 00:07:49,000",arabic:"أَنَّ لَكَ عَمًّا يَحْفَظُهُ الدَّاخِرُ وَيَصِلُ رَحِيمَهُ مِنْ بَعْدِهِ",segs:[{ar:"أَنَّ لَكَ عَمًّا",uz:"sening amaking borligini"},{ar:"يَحْفَظُهُ الدَّاخِرُ وَيَصِلُ رَحِيمَهُ مِنْ بَعْدِهِ",uz:"u qarindoshligini asraydi va undan keyin ham qarindoshlik rishtalarini davom ettiradi"}],full_uz:"Sening amaking borligini unutma: u qarindoshligini asraydi va qarindoshlik rishtalarini davom ettiradi.",note:null},
{num:62,time:"00:07:49,000 --> 00:07:51,079",arabic:"جَزَاكَ اللَّهُ خَيْرًا",segs:null,full_uz:"Alloh seni yaxshilik bilan mukofotlasin.",note:null},
{num:63,time:"00:07:51,079 --> 00:07:53,219",arabic:"أَنْتَ أَوْلَى بِي وَأَنَا أَوْلَى بِكَ",segs:[{ar:"أَنْتَ أَوْلَى بِي",uz:"sen menga haqlisan"},{ar:"وَأَنَا أَوْلَى بِكَ",uz:"men ham senga haqliman"}],full_uz:"Sen menga, men esa senga haqliman.",note:null},
{num:64,time:"00:07:53,219 --> 00:07:56,979",arabic:"وَلَكِنِّي رَاضٍ بِعَطَاءِ رَبِّي مُتَوَكِّلٌ عَلَيْهِ",segs:[{ar:"وَلَكِنِّي رَاضٍ بِعَطَاءِ رَبِّي",uz:"lekin men Robbimning berganiga roziman"},{ar:"مُتَوَكِّلٌ عَلَيْهِ",uz:"Unga tavakkal qilgan holda"}],full_uz:"Lekin men Robbimning berganiga roziman va Unga tavakkal qilaman.",note:null},
{num:65,time:"00:07:56,979 --> 00:07:58,219",arabic:"لَا إِلٰهَ إِلَّا اللَّهُ",segs:null,full_uz:"Allohdan o'zga iloh yo'q.",note:null},
{num:66,time:"00:07:58,219 --> 00:08:00,679",arabic:"أَحْمَدُ إِنْ طَرَأَ جَدِيدٌ فَأَخْبِرْنِي",segs:[{ar:"إِنْ طَرَأَ جَدِيدٌ",uz:"agar yangi biror narsa yuz bersa"},{ar:"فَأَخْبِرْنِي",uz:"menga xabar ber"}],full_uz:"Agar yangi biror narsa yuz bersa, menga xabar ber.",note:null},
{num:67,time:"00:08:00,679 --> 00:08:02,519",arabic:"السَّلَامُ عَلَيْكَ",segs:null,full_uz:"Senga salom bo'lsin.",note:null},
{num:68,time:"00:08:02,519 --> 00:08:04,299",arabic:"وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:null,full_uz:"Senga ham salom va Allohning rahmati bo'lsin.",note:null},
{num:69,time:"00:08:15,719 --> 00:08:18,379",arabic:"يَا اللَّهُ",segs:null,full_uz:"Ey Alloh.",note:null},
{num:70,time:"00:08:23,039 --> 00:08:27,339",arabic:"مَا وَرَاءَكَ أَيُّهَا الْآخَرُ؟",segs:[{ar:"مَا وَرَاءَكَ",uz:"ortingda nima bor?"},{ar:"أَيُّهَا الْآخَرُ؟",uz:"ey sen?"}],full_uz:"Ortingda nima bor, ey sen?",note:null},
{num:71,time:"00:08:27,339 --> 00:08:28,399",arabic:"دَعْكَ مِمَّا وَرَائِي",segs:null,full_uz:"Ortimdagi narsani qo'ya qol.",note:null},
{num:72,time:"00:08:28,399 --> 00:08:30,360",arabic:"وَانْظُرْ مَا جِئْتُكَ بِهِ",segs:null,full_uz:"Qara, men senga nima olib keldim.",note:null},
{num:73,time:"00:08:30,360 --> 00:08:32,899",arabic:"وَيْحًا، مِنْ أَيْنَ جِئْتَ بِهَا؟",segs:[{ar:"وَيْحًا",uz:"voy, bechora"},{ar:"مِنْ أَيْنَ جِئْتَ بِهَا؟",uz:"uni qayerdan topding?"}],full_uz:"Voy, uni qayerdan topding?",note:"وَيْحًا — achinish yoki hayrat ifodasi."},
{num:74,time:"00:08:32,899 --> 00:08:33,699",arabic:"اِصْطَدْتُهَا فِي السُّوقِ",segs:null,full_uz:"Uni bozorda tutdim.",note:"اِصْطَادَ — ovlamoq, tutmoq."},
{num:75,time:"00:08:33,699 --> 00:08:36,620",arabic:"حَاوَلَ الْحَرَسُ الْإِمْسَاكَ بِهِ",segs:null,full_uz:"Qo'riqchilar uni ushlashga harakat qilishdi.",note:null},
{num:76,time:"00:08:36,620 --> 00:08:38,779",arabic:"وَلَكِنَّنِي ضَلَّلْتُهُمْ فِي الطَّرِيقِ",segs:null,full_uz:"Lekin men ularni yo'lda chalg'itdim.",note:"ضَلَّلَ — chalg'itmoq."},
{num:77,time:"00:08:38,779 --> 00:08:39,860",arabic:"أَحْسَنْتَ الصَّنْعَةَ",segs:null,full_uz:"Ishni yaxshi qilibsan.",note:null},
{num:78,time:"00:08:39,860 --> 00:08:41,559",arabic:"هَيَّا اذْهَبْ وَأَشْعِلِ النَّارَ",segs:[{ar:"هَيَّا اذْهَبْ",uz:"qani, bor"},{ar:"وَأَشْعِلِ النَّارَ",uz:"va olov yoq"}],full_uz:"Qani, bor va olov yoq.",note:null},
{num:79,time:"00:08:41,559 --> 00:08:42,959",arabic:"رَيْثَمَا أُجَهِّزُهَا",segs:null,full_uz:"Men uni tayyorlagunimcha.",note:"رَيْثَمَا — ...guncha, ... vaqtida."},
{num:80,time:"00:08:42,959 --> 00:08:45,120",arabic:"هَيَّا فَإِنَّنِي أَتَضَوَّرُ جُوعًا",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"فَإِنَّنِي أَتَضَوَّرُ جُوعًا",uz:"chunki ochlikdan qiynalyapman"}],full_uz:"Qani, chunki ochlikdan qiynalyapman.",note:"أَتَضَوَّرُ جُوعًا — ochlikdan qattiq qiynalmoq."},
{num:81,time:"00:08:45,399 --> 00:09:00,740",arabic:"لَوْ أَنَّهُمْ يُرْسِلُونَ الرَّسَائِلَ مَعَ الشِّيَاهِ بَدَلَ الْحَمَامِ",segs:[{ar:"لَوْ أَنَّهُمْ يُرْسِلُونَ الرَّسَائِلَ مَعَ الشِّيَاهِ",uz:"agar ular xatlarni kaptarlar o'rniga qo'ylar bilan yuborishganida"},{ar:"بَدَلَ الْحَمَامِ",uz:"kaptarlar o'rniga"}],full_uz:"Agar ular xatlarni kaptarlar o'rniga qo'ylar bilan yuborishganida edi.",note:null},
{num:82,time:"00:09:00,740 --> 00:09:02,319",arabic:"لَأَتَيْتُكَ بِشَاةٍ",segs:null,full_uz:"Men senga bir qo'y olib kelardim.",note:null},
{num:83,time:"00:09:48,620 --> 00:09:50,799",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:null,full_uz:"Sizga ham salom, Allohning rahmati va barakotlari bo'lsin.",note:null},
{num:84,time:"00:09:50,799 --> 00:09:52,959",arabic:"مَا اسْمُكَ يَا فَتَى؟",segs:null,full_uz:"Ey bola, isming nima?",note:null},
{num:85,time:"00:09:52,959 --> 00:09:55,360",arabic:"أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ الشَّيْبَانِيُّ",segs:null,full_uz:"Ahmad ibn Muhammad ibn Hanbal ash-Shayboniy.",note:null},
{num:86,time:"00:09:55,360 --> 00:09:57,039",arabic:"لِمَنْ هَذَا الدُّكَّانُ؟",segs:null,full_uz:"Bu do'kon kimniki?",note:null},
{num:87,time:"00:09:57,039 --> 00:09:57,379",arabic:"لِأَبِي",segs:null,full_uz:"Otamniki.",note:null},
{num:88,time:"00:09:57,379 --> 00:09:59,579",arabic:"أَيْنَ هُوَ؟ أُرِيدُ أَنْ أَرَاهُ الْآنَ",segs:[{ar:"أَيْنَ هُوَ؟",uz:"u qayerda?"},{ar:"أُرِيدُ أَنْ أَرَاهُ الْآنَ",uz:"uni hozir ko'rishni istayman"}],full_uz:"U qayerda? Uni hozir ko'rishni istayman.",note:null},
{num:89,time:"00:09:59,579 --> 00:10:01,860",arabic:"أَبِي تَوَفَّاهُ اللَّهُ مُنْذُ كُنْتُ صَغِيرًا",segs:null,full_uz:"Otam men kichikligimda vafot etgan.",note:null},
{num:90,time:"00:10:01,860 --> 00:10:05,519",arabic:"تَغَمَّدَهُ اللَّهُ بِرَحْمَتِهِ وَبَارَكَ اللَّهُ فِيكَ يَا وَلَدِي",segs:[{ar:"تَغَمَّدَهُ اللَّهُ بِرَحْمَتِهِ",uz:"Alloh uni O'z rahmatiga olsin"},{ar:"وَبَارَكَ اللَّهُ فِيكَ يَا وَلَدِي",uz:"Alloh seni barakali qilsin, bolam"}],full_uz:"Alloh uni O'z rahmatiga olsin va seni barakali qilsin, bolam.",note:null},
{num:91,time:"00:10:05,519 --> 00:10:08,759",arabic:"خَيْرًا يَا خَالَةُ، أَلَكِ مِنْ حَاجَةٍ أَقْضِيهَا؟",segs:[{ar:"خَيْرًا يَا خَالَةُ",uz:"yaxshi, xola"},{ar:"أَلَكِ مِنْ حَاجَةٍ أَقْضِيهَا؟",uz:"sizga bajarib berishim kerak bo'lgan biror ehtiyojingiz bormi?"}],full_uz:"Yaxshi, xola. Sizga bajarib berishim kerak bo'lgan biror ehtiyojingiz bormi?",note:null},
{num:92,time:"00:10:08,759 --> 00:10:11,639",arabic:"مَنْ يُرَاعِي شَأْنَ هَذَا الدُّكَّانِ؟",segs:null,full_uz:"Bu do'kon ishlariga kim qaraydi?",note:"رَاعَى شَأْنَ — ishini boshqarmoq, holidan xabar olmoq."},
{num:93,time:"00:10:11,639 --> 00:10:13,419",arabic:"أُمِّي وَمَنْ يُخَاطِبُكَ يَا خَالِدُ",segs:[{ar:"أُمِّي",uz:"onajon"},{ar:"وَمَنْ يُخَاطِبُكَ يَا خَالِدُ",uz:"senga kim gapiryapti, ey Xolid?"}],full_uz:"Onajon, senga kim gapiryapti, ey Xolid?",note:null},
{num:94,time:"00:10:13,419 --> 00:10:16,740",arabic:"حَسَنًا، أُرِيدُ مُقَابَلَةَ أُمِّكَ",segs:[{ar:"حَسَنًا",uz:"xo'p"},{ar:"أُرِيدُ مُقَابَلَةَ أُمِّكَ",uz:"onang bilan uchrashishni istayman"}],full_uz:"Xo'p, onang bilan uchrashishni istayman.",note:null},
{num:95,time:"00:10:16,740 --> 00:10:19,759",arabic:"حَسَنًا يَا خَالِدُ، حَسَنًا",segs:[{ar:"حَسَنًا يَا خَالِدُ",uz:"xo'p, ey Xolid"},{ar:"حَسَنًا",uz:"xo'p"}],full_uz:"Xo'p, ey Xolid, xo'p.",note:null},
{num:96,time:"00:10:23,759 --> 00:10:26,039",arabic:"بُشْرَى يَا أُمَّ خَالِدٍ",segs:null,full_uz:"Xushxabar, ey Xolidning onasi.",note:"بُشْرَى — xushxabar."},
{num:97,time:"00:10:26,039 --> 00:10:31,519",arabic:"لَا أَدْرِي مَا أَقُولُ لَكِ، وَلَكِنَّ ابْنِي خَالِدًا أَخْبَرَنِي",segs:[{ar:"لَا أَدْرِي مَا أَقُولُ لَكِ",uz:"senga nima deyishni bilmayman"},{ar:"وَلَكِنَّ ابْنِي خَالِدًا أَخْبَرَنِي",uz:"lekin o'g'lim Xolid menga aytdiki"}],full_uz:"Senga nima deyishni bilmayman, lekin o'g'lim Xolid menga aytdiki...",note:null},
{num:98,time:"00:10:31,519 --> 00:10:36,559",arabic:"أَنَّ صَانِعَ السَّجَّادِ لَا يَحْتَاجُ الْآنَ لِمَنْ يَحِيكُ السَّجَّادَ",segs:[{ar:"أَنَّ صَانِعَ السَّجَّادِ لَا يَحْتَاجُ الْآنَ",uz:"gilamchi hozir ehtiyoj sezmayapti"},{ar:"لِمَنْ يَحِيكُ السَّجَّادَ",uz:"gilam to'qiydigan kishiga"}],full_uz:"Gilamchi hozir gilam to'qiydigan kishiga ehtiyoj sezmayapti.",note:null},
{num:99,time:"00:10:38,759 --> 00:10:42,720",arabic:"تَحَلَّي بِالصَّبْرِ يَا أُمَّ أَحْمَدَ مَا بَعْدَ الضِّيقِ إِلَّا الْفَرَجُ",segs:[{ar:"تَحَلَّي بِالصَّبْرِ يَا أُمَّ أَحْمَدَ",uz:"sabrli bo'l, ey Ahmadning onasi"},{ar:"مَا بَعْدَ الضِّيقِ إِلَّا الْفَرَجُ",uz:"qiyinchilikdan keyin yengillik keladi"}],full_uz:"Sabrli bo'l, ey Ahmadning onasi. Qiyinchilikdan keyin faqat yengillik keladi.",note:null},
{num:100,time:"00:10:42,720 --> 00:10:46,379",arabic:"لَا أَدْرِي مَا أَقُولُ لَكِ يَا أُمَّ خَالِدٍ",segs:null,full_uz:"Senga nima deyishni bilmayman, ey Xolidning onasi.",note:null},
{num:101,time:"00:10:46,379 --> 00:10:50,120",arabic:"إِنَّمَا بُؤْسِي وَحُزْنِي عَلَى وَلَدِي أَحْمَدَ",segs:[{ar:"إِنَّمَا بُؤْسِي وَحُزْنِي",uz:"mening qayg'u va g'amim"},{ar:"عَلَى وَلَدِي أَحْمَدَ",uz:"o'g'lim Ahmad uchundir"}],full_uz:"Mening qayg'u va g'amim o'g'lim Ahmad uchundir.",note:"بُؤْسٌ — mashaqqat, qayg'u."},
{num:102,time:"00:10:50,120 --> 00:10:56,080",arabic:"فَإِنْ بَقِينَا عَلَى هَذِهِ الْحَالِ أَخْشَى أَنْ يَفُوتَهُ الْعِلْمُ لِانْشِغَالِهِ بِطَلَبِ الرِّزْقِ",segs:[{ar:"فَإِنْ بَقِينَا عَلَى هَذِهِ الْحَالِ",uz:"agar shu holatda davom etsak"},{ar:"أَخْشَى أَنْ يَفُوتَهُ الْعِلْمُ",uz:"ilm olishdan qolib ketishidan qo'rqaman"},{ar:"لِانْشِغَالِهِ بِطَلَبِ الرِّزْقِ",uz:"chunki u rizq topish bilan band bo'lib qoladi"}],full_uz:"Agar shu holatda davom etsak, ilm olishdan qolib ketishidan qo'rqaman, chunki u rizq topish bilan band bo'lib qoladi.",note:null},
{num:103,time:"00:10:56,080 --> 00:10:59,720",arabic:"وَأَنَا قَدْ نَذَرْتُهُ لِطَلَبِ الْعِلْمِ وَالِاشْتِغَالِ بِهِ",segs:[{ar:"وَأَنَا قَدْ نَذَرْتُهُ لِطَلَبِ الْعِلْمِ",uz:"men esa uni ilm talab qilishga bag'ishlaganman"},{ar:"وَالِاشْتِغَالِ بِهِ",uz:"va u bilan mashg'ul bo'lishga"}],full_uz:"Men esa uni ilm talab qilishga va u bilan mashg'ul bo'lishga bag'ishlaganman.",note:"نَذَرَ — bag'ishlamoq, nazr qilmoq."},
{num:104,time:"00:10:59,720 --> 00:11:06,679",arabic:"لَا بُدَّ أَنَّ أَحْمَدَ أَدْعُو اللَّهَ أَنْ يَكُونَ قَدْ وَجَدَ مُكْتَرِيًا لِلدُّكَّانِ",segs:[{ar:"لَا بُدَّ أَنَّ أَحْمَدَ",uz:"albatta Ahmad..."},{ar:"أَدْعُو اللَّهَ أَنْ يَكُونَ قَدْ وَجَدَ مُكْتَرِيًا لِلدُّكَّانِ",uz:"Allohdan do'konga ijarachi topgan bo'lishini so'rayman"}],full_uz:"Albatta Ahmad... Allohdan do'konga ijarachi topgan bo'lishini so'rayman.",note:"مُكْتَرٍ — ijarachi."},
{num:105,time:"00:11:08,759 --> 00:11:15,299",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Sizlarga salom bo'lsin.",note:null},
{num:106,time:"00:11:15,299 --> 00:11:17,539",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:null,full_uz:"Sizlarga ham salom va Allohning rahmati bo'lsin.",note:null},
{num:107,time:"00:11:17,539 --> 00:11:19,720",arabic:"أَنْتِ أُمُّ أَحْمَدَ؟",segs:null,full_uz:"Siz Ahmadning onasisizmi?",note:null},
{num:108,time:"00:11:21,799 --> 00:11:27,279",arabic:"لِي حَاجَةٌ عِنْدَكِ إِذَنْ",segs:null,full_uz:"Unda, sizdan bir iltimosim bor.",note:null},
{num:109,time:"00:11:27,279 --> 00:11:29,279",arabic:"مَاذَا تَقُولُ؟",segs:null,full_uz:"Nima deyapsiz?",note:null},
{num:110,time:"00:11:29,279 --> 00:11:32,659",arabic:"هَذَا مَا حَدَثَ يَا سَيِّدِي",segs:[{ar:"هَذَا مَا حَدَثَ",uz:"bo'lgan voqea shu"},{ar:"يَا سَيِّدِي",uz:"ey janob"}],full_uz:"Bo'lgan voqea shu, ey janob.",note:null},
{num:111,time:"00:11:32,659 --> 00:11:34,620",arabic:"الْوَيْلُ لَكَ إِنْ كَانَ هَذَا صَحِيحًا",segs:null,full_uz:"Agar bu rost bo'lsa, holingga voy.",note:"الْوَيْلُ لَكَ — holingga voy, senga halokat."},
{num:112,time:"00:11:34,620 --> 00:11:37,179",arabic:"بَلْ قُلِ الْوَيْلُ لَنَا جَمِيعًا",segs:null,full_uz:"Yo'q, hammamizning holimizga voy, degin.",note:null},
{num:113,time:"00:11:37,179 --> 00:11:40,779",arabic:"إِنْ وَصَلَتِ الرِّسَالَةُ لِيَدِ هَارُونَ الرَّشِيدِ",segs:null,full_uz:"Agar xat Horun ar-Rashidning qo'liga tushsa.",note:null},
{num:114,time:"00:11:40,779 --> 00:11:43,459",arabic:"اذْهَبْ وَائْتِنِي بِذَلِكَ الْفَتَى الَّذِي اخْتَلَسَ الْحَمَامَةَ",segs:[{ar:"اذْهَبْ وَائْتِنِي بِذَلِكَ الْفَتَى",uz:"borib o'sha bolani menga olib kel"},{ar:"الَّذِي اخْتَلَسَ الْحَمَامَةَ",uz:"u kaptarni o'g'irlab olgan"}],full_uz:"Borib, kaptarni o'g'irlab olgan o'sha bolani menga olib kel.",note:"اخْتَلَسَ — yashirincha olib qolmoq, o'g'irlab olmoq."},
{num:115,time:"00:11:43,459 --> 00:11:46,699",arabic:"لَا تَعُدْ إِلَّا وَهُوَ فِي قَبْضَتِكَ",segs:null,full_uz:"Uni qo'lga olmasdan qaytma.",note:"فِي قَبْضَتِكَ — sening qo'lingda, qo'lga olingan holda."},
{num:116,time:"00:11:46,699 --> 00:11:51,899",arabic:"أَرْسَلْتُ الْحَارِسَةَ لِلْبَحْثِ عَنْهُ",segs:null,full_uz:"Uni qidirish uchun qo'riqchini yubordim.",note:null},
{num:117,time:"00:11:51,899 --> 00:11:54,659",arabic:"لَا يَكْفِي أُرِيدُكَ أَنْ تَذْهَبَ بِنَفْسِكَ لِلْبَحْثِ عَنْهُ",segs:[{ar:"لَا يَكْفِي",uz:"bu yetarli emas"},{ar:"أُرِيدُكَ أَنْ تَذْهَبَ بِنَفْسِكَ لِلْبَحْثِ عَنْهُ",uz:"o'zing borib uni qidirishingni istayman"}],full_uz:"Bu yetarli emas. O'zing borib uni qidirishingni istayman.",note:null},
{num:118,time:"00:11:54,659 --> 00:11:58,099",arabic:"إِنَّ مُصِيرًا رَهْنٌ بِتَذَكُّرِ رِسَالَتِي يَا مَسْعُودُ",segs:[{ar:"إِنَّ مُصِيرًا رَهْنٌ بِتَذَكُّرِ رِسَالَتِي",uz:"bir taqdir mening xatimning saqlanib qolishiga bog'liq"},{ar:"يَا مَسْعُودُ",uz:"ey Mas'ud"}],full_uz:"Bir taqdir mening xatimning saqlanib qolishiga bog'liq, ey Mas'ud.",note:null},
{num:119,time:"00:11:58,099 --> 00:11:59,799",arabic:"لَا يَنْبَغِي لِمَخْلُوقٍ أَنْ يَعْلَمَ بِمَحْتَوَاهَا أَفَهِمْتَ؟",segs:[{ar:"لَا يَنْبَغِي لِمَخْلُوقٍ أَنْ يَعْلَمَ بِمَحْتَوَاهَا",uz:"biror kimsa uning mazmunini bilmasligi kerak"},{ar:"أَفَهِمْتَ؟",uz:"tushundingmi?"}],full_uz:"Biror kimsa uning mazmunini bilmasligi kerak. Tushundingmi?",note:"مُحْتَوًى — mazmun."},
{num:120,time:"00:11:59,799 --> 00:12:01,279",arabic:"هَيَّا اذْهَبْ",segs:null,full_uz:"Qani, bor.",note:null},
{num:121,time:"00:12:01,279 --> 00:12:06,939",arabic:"أَيُّ شَيْءٍ مِنْ هَذَا",segs:null,full_uz:"Bu nima degani?",note:null},
{num:122,time:"00:12:06,939 --> 00:12:10,899",arabic:"إِنْ وَقَعَتْ رِسَالَةٌ بِيَدِ أَحَدِ رِجَالَاتِ الْقَصْرِ",segs:null,full_uz:"Agar xat saroy odamlaridan birining qo'liga tushsa.",note:null},
{num:123,time:"00:12:10,899 --> 00:12:13,879",arabic:"ضُرِبَتْ أَعْنَاقُنَا",segs:null,full_uz:"Bo'yinlarimiz kesiladi.",note:"ضُرِبَتْ أَعْنَاقُنَا — boshlarimiz kesiladi, qatl qilinamiz."},
{num:124,time:"00:12:13,879 --> 00:12:24,379",arabic:"أَحْمَدُ أَحْمَدُ",segs:null,full_uz:"Ahmad, Ahmad.",note:null},
{num:125,time:"00:12:24,379 --> 00:12:26,799",arabic:"السَّلَامُ عَلَيْكُمْ يَا عَمِّي",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"sizga salom bo'lsin"},{ar:"يَا عَمِّي",uz:"ey amaki"}],full_uz:"Sizga salom bo'lsin, ey amaki.",note:null},
{num:126,time:"00:12:26,799 --> 00:12:28,199",arabic:"وَعَلَيْكَ السَّلَامُ إِلَى أَيْنَ؟",segs:[{ar:"وَعَلَيْكَ السَّلَامُ",uz:"senga ham salom"},{ar:"إِلَى أَيْنَ؟",uz:"qayerga?"}],full_uz:"Senga ham salom. Qayerga?",note:null},
{num:127,time:"00:12:28,199 --> 00:12:29,480",arabic:"إِلَى حَلَقَةِ شَيْخِي",segs:null,full_uz:"Shayximning dars halqasiga.",note:"حَلَقَةُ الشَّيْخِ — shayxning dars halqasi."},
{num:128,time:"00:12:29,480 --> 00:12:34,120",arabic:"آهْ مَادُمْتَ تَذْهَبُ إِلَى حَلَقَةِ شَيْخِكَ إِذَنْ لَا بُدَّ أَنَّكَ وَجَدْتَ مُكْتَرِيًا لِلدُّكَّانِ",segs:[{ar:"مَا دُمْتَ تَذْهَبُ إِلَى حَلَقَةِ شَيْخِكَ",uz:"shayxingning dars halqasiga borayotgan ekansan"},{ar:"إِذَنْ لَا بُدَّ أَنَّكَ وَجَدْتَ مُكْتَرِيًا لِلدُّكَّانِ",uz:"demak, albatta do'konga ijarachi topgansan"}],full_uz:"Shayxingning dars halqasiga borayotgan ekansan, demak, albatta do'konga ijarachi topgansan.",note:null},
{num:129,time:"00:12:34,120 --> 00:12:36,440",arabic:"عَجَلْ وَالْحَمْدُ لِلَّهِ أَسْتَوْدِعُكَ اللَّهَ",segs:[{ar:"عَجَلْ وَالْحَمْدُ لِلَّهِ",uz:"ha, alhamdulillah"},{ar:"أَسْتَوْدِعُكَ اللَّهَ",uz:"seni Allohga topshirdim"}],full_uz:"Ha, alhamdulillah. Seni Allohga topshirdim.",note:null},
{num:130,time:"00:12:36,440 --> 00:12:38,759",arabic:"فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا",segs:[{ar:"فَلْيَضْحَكُوا قَلِيلًا",uz:"ular oz kulsinlar"},{ar:"وَلْيَبْكُوا كَثِيرًا",uz:"va ko'p yig'lasinlar"}],full_uz:"Ular oz kulsinlar va ko'p yig'lasinlar.",note:null},
{num:131,time:"00:12:46,759 --> 00:12:50,519",arabic:"السَّلَامُ عَلَى مَوْصُولِ الْجَاهِ بْنِ الْأَيْهَمِ",segs:null,full_uz:"Mansabdor ibn al-Ayhamga salom.",note:null},
{num:132,time:"00:12:50,519 --> 00:12:54,399",arabic:"اسْقِ وَرْدَةَ الْبَيْتِ الشَّرِيفَةِ",segs:null,full_uz:"Sharafli xonadon gulini sug'or.",note:null},
{num:133,time:"00:12:54,399 --> 00:12:58,240",arabic:"وَدَعِ الْأَمَانَةَ مُرْسَلَةً فِي مَاءِ دِجْلَةَ",segs:[{ar:"وَدَعِ الْأَمَانَةَ مُرْسَلَةً",uz:"omonatni oqizib yubor"},{ar:"فِي مَاءِ دِجْلَةَ",uz:"Dajla suvida"}],full_uz:"Omonatni Dajla suvida oqizib yubor.",note:null},
{num:134,time:"00:12:58,240 --> 00:13:03,460",arabic:"الْعَيْنُ الْبَاكِيَةُ تَنْتَظِرُ رُؤْيَةَ وَرْدَتِهَا فِي الْبَصْرَةِ",segs:[{ar:"الْعَيْنُ الْبَاكِيَةُ تَنْتَظِرُ",uz:"yig'layotgan ko'z kutmoqda"},{ar:"رُؤْيَةَ وَرْدَتِهَا فِي الْبَصْرَةِ",uz:"Basrada o'z gulini ko'rishni"}],full_uz:"Yig'layotgan ko'z Basrada o'z gulini ko'rishni kutmoqda.",note:null},
{num:135,time:"00:13:03,460 --> 00:13:07,019",arabic:"شَمْسٌ تَذْهَبُ وَأُخْرَى",segs:null,full_uz:"Bir quyosh botadi, boshqasi...",note:null},
{num:136,time:"00:13:07,019 --> 00:13:09,919",arabic:"ثُمَّ أَطْلِقْ لِلْوَرْدَةِ الْهَوَاءَ",segs:null,full_uz:"So'ng gulga havoni qo'yib yubor.",note:null},
{num:137,time:"00:13:09,919 --> 00:13:14,740",arabic:"وَارْحَلْ إِلَى مَيَّافَارِقِينَ عَلَى الْفَوْرِ وَالْعَجَلِ",segs:[{ar:"وَارْحَلْ إِلَى مَيَّافَارِقِينَ",uz:"Mayyafariqinga jo'nab ket"},{ar:"عَلَى الْفَوْرِ وَالْعَجَلِ",uz:"darhol va shoshilinch ravishda"}],full_uz:"Mayyafariqinga darhol va shoshilinch ravishda jo'nab ket.",note:"مَيَّافَارِقِينَ — Mayyafariqin shahri."},
{num:138,time:"00:13:14,740 --> 00:13:18,320",arabic:"صَدِيقُكُمْ ثَوْبَةُ",segs:null,full_uz:"Do'stingiz Savba.",note:null},
{num:139,time:"00:13:18,320 --> 00:13:23,200",arabic:"إِنَّهَا قَصِيدَةٌ رَائِعَةٌ",segs:null,full_uz:"Bu ajoyib she'r.",note:"قَصِيدَةٌ — she'r, qasida."},
{num:140,time:"00:13:23,200 --> 00:13:28,019",arabic:"أَهَذِهِ رُقْيَةُ سَاحِرٍ أَمْ زَجَلُ شَاعِرٍ يَا بَهْلُولُ؟",segs:[{ar:"أَهَذِهِ رُقْيَةُ سَاحِرٍ أَمْ زَجَلُ شَاعِرٍ",uz:"bu sehrgarning afsuni yoki shoirning she'rimi"},{ar:"يَا بَهْلُولُ؟",uz:"ey Bahlul?"}],full_uz:"Bu sehrgarning afsuni yoki shoirning she'rimi, ey Bahlul?",note:"رُقْيَةٌ — afsun, duo. زَجَلٌ — she'r, ashula."},
{num:141,time:"00:13:31,940 --> 00:13:43,039",arabic:"وَمَاذَا تَتَوَقَّعُونَ مِنَ الْمَجَانِينِ غَيْرَ الْهَذَيَانِ",segs:null,full_uz:"Jinnilardan safsatadan boshqa nimani kutasizlar?",note:"الْهَذَيَانُ — safsata, behuda gap."},
{num:142,time:"00:13:43,039 --> 00:13:44,919",arabic:"لَعَلَّهُ لَيْسَ هَذَيَانًا",segs:null,full_uz:"Balki bu safsata emasdir.",note:null},
{num:143,time:"00:13:44,919 --> 00:13:47,700",arabic:"وَإِنْ لَمْ يَكُنْ هَذَيَانًا فَمَاذَا يَكُونُ إِذَنْ؟",segs:[{ar:"وَإِنْ لَمْ يَكُنْ هَذَيَانًا",uz:"agar bu safsata bo'lmasa"},{ar:"فَمَاذَا يَكُونُ إِذَنْ؟",uz:"unda bu nima bo'ladi?"}],full_uz:"Agar bu safsata bo'lmasa, unda bu nima bo'ladi?",note:null},
{num:144,time:"00:14:15,740 --> 00:14:18,780",arabic:"وَمَا تَعْبِيرُكَ لَهُ يَا ابْنَ أَخِي؟",segs:[{ar:"وَمَا تَعْبِيرُكَ لَهُ",uz:"uning ta'biring qanday"},{ar:"يَا ابْنَ أَخِي؟",uz:"ey jiyanim?"}],full_uz:"Ey jiyanim, seningcha bu nimani anglatadi?",note:"تَعْبِيرٌ — ta'bir, talqin."},
{num:145,time:"00:14:18,780 --> 00:14:22,560",arabic:"يَبْدُو أَنَّ شَخْصًا مُهِمًّا سَيَهْرُبُ مِنَ الْقَصْرِ مِنْ خِلَالِ نَهْرِ دِجْلَةَ",segs:[{ar:"يَبْدُو أَنَّ شَخْصًا مُهِمًّا سَيَهْرُبُ مِنَ الْقَصْرِ",uz:"muhim bir kishi saroydan qochadiganga o'xshaydi"},{ar:"مِنْ خِلَالِ نَهْرِ دِجْلَةَ",uz:"Dajla daryosi orqali"}],full_uz:"Muhim bir kishi Dajla daryosi orqali saroydan qochadiganga o'xshaydi.",note:null},
{num:146,time:"00:14:22,560 --> 00:14:26,460",arabic:"وَهُنَاكَ مَنْ يَنْتَظِرُهُ فِي الْبَصْرَةِ",segs:null,full_uz:"U yerda uni Basrada kutayotgan kishi bor.",note:null},
{num:147,time:"00:14:26,460 --> 00:14:28,960",arabic:"وَبَعْدَ يَوْمٍ وَلَيْلَةٍ سَيُطْلِقُ",segs:null,full_uz:"Bir kun-u bir kechadan keyin ozod qiladi.",note:null},
{num:148,time:"00:14:28,960 --> 00:14:33,480",arabic:"وَعَلَى مَنْ يَتَوَلَّى ذَلِكَ أَنْ يَهْرُبَ إِلَى مَدِينَةِ مَيَّافَارِقِينَ",segs:[{ar:"وَعَلَى مَنْ يَتَوَلَّى ذَلِكَ",uz:"buni amalga oshiradigan kishi"},{ar:"أَنْ يَهْرُبَ إِلَى مَدِينَةِ مَيَّافَارِقِينَ",uz:"Mayyafariqin shahriga qochishi kerak"}],full_uz:"Buni amalga oshiradigan kishi Mayyafariqin shahriga qochishi kerak.",note:null},
{num:149,time:"00:14:33,480 --> 00:14:36,560",arabic:"أَحَقًّا تَتَكَلَّمُ يَا أَحْمَدُ أَمْ تَمْزَحُ؟",segs:[{ar:"أَحَقًّا تَتَكَلَّمُ يَا أَحْمَدُ",uz:"rostdan gapiryapsanmi, ey Ahmad"},{ar:"أَمْ تَمْزَحُ؟",uz:"yoki hazillashyapsanmi?"}],full_uz:"Rostdan gapiryapsanmi, ey Ahmad, yoki hazillashyapsanmi?",note:null},
{num:150,time:"00:14:36,560 --> 00:14:39,120",arabic:"وَمُنْذُ مَتَى عَهِدْتَنِي أَلْغُو يَا عَمِّي",segs:[{ar:"وَمُنْذُ مَتَى عَهِدْتَنِي أَلْغُو",uz:"qachondan beri meni behuda gapiradigan deb bilasan"},{ar:"يَا عَمِّي",uz:"ey amaki"}],full_uz:"Qachondan beri meni behuda gapiradigan deb bilasan, ey amaki?",note:"لَغَا — behuda gapirmoq."},
{num:151,time:"00:14:39,120 --> 00:14:42,900",arabic:"إِنْ كَانَ تَأْوِيلُكَ لِلرِّسَالَةِ صَحِيحًا",segs:null,full_uz:"Agar xat haqidagi talqining to'g'ri bo'lsa.",note:"تَأْوِيلٌ — talqin, sharh."},
{num:152,time:"00:14:42,900 --> 00:14:46,120",arabic:"فَثَمَّ خَطَرٌ يُوشِكُ أَنْ يُضِرَّ الرَّعِيَّةَ وَالرَّعِيَّةَ",segs:[{ar:"فَثَمَّ خَطَرٌ",uz:"unda xavf bor"},{ar:"يُوشِكُ أَنْ يُضِرَّ الرَّعِيَّةَ",uz:"u fuqarolarga zarar yetkazishi mumkin"}],full_uz:"Unda fuqarolarga zarar yetkazishi mumkin bo'lgan xavf bor.",note:null},
{num:153,time:"00:14:46,120 --> 00:14:48,900",arabic:"وَيَجِبُ أَنْ يَنْتَبِهَ إِلَيْهِ وُلَاةُ أُمُورِنَا",segs:[{ar:"وَيَجِبُ أَنْ يَنْتَبِهَ إِلَيْهِ",uz:"unga e'tibor berishlari kerak"},{ar:"وُلَاةُ أُمُورِنَا",uz:"rahbarlarimiz"}],full_uz:"Rahbarlarimiz bunga e'tibor berishlari kerak.",note:null},
{num:154,time:"00:14:48,900 --> 00:14:51,720",arabic:"وَمَنْ يَسْتَطِيعُ ذَلِكَ؟",segs:null,full_uz:"Buni kim qila oladi?",note:null},
{num:155,time:"00:14:51,720 --> 00:14:55,420",arabic:"أَنَا أَعْرِفُ شَخْصًا بِاسْتِطَاعَتِهِ أَنْ يُوصِلَنَا إِلَى الْقَصْرِ",segs:[{ar:"أَنَا أَعْرِفُ شَخْصًا",uz:"men bir kishini bilaman"},{ar:"بِاسْتِطَاعَتِهِ أَنْ يُوصِلَنَا إِلَى الْقَصْرِ",uz:"u bizni saroyga olib borishi mumkin"}],full_uz:"Men bizni saroyga olib bora oladigan bir kishini bilaman.",note:null},
{num:156,time:"00:15:55,419 --> 00:16:02,419",arabic:"إِلَى مَتَى سَنَظَلُّ هَكَذَا يَا أُمِّي؟",segs:[{ar:"إِلَى مَتَى سَنَظَلُّ هَكَذَا",uz:"qachongacha shunday yashaymiz"},{ar:"يَا أُمِّي؟",uz:"ey onajon?"}],full_uz:"Qachongacha shunday yashaymiz, ey onajon?",note:null},
{num:157,time:"00:16:02,419 --> 00:16:04,579",arabic:"مَلِلْتُ هَذِهِ الْحَيَاةَ",segs:null,full_uz:"Bu hayotdan zerikdim.",note:"مَلَّ — zerikmoq, bezmoq."},
{num:158,time:"00:16:04,579 --> 00:16:08,199",arabic:"مَنْ بِعُمْرِي تَزَوَّجَ وَأَصْبَحُوا آبَاءً",segs:[{ar:"مَنْ بِعُمْرِي تَزَوَّجَ",uz:"mening tengdoshlarim uylanishdi"},{ar:"وَأَصْبَحُوا آبَاءً",uz:"va ota bo'lishdi"}],full_uz:"Mening tengdoshlarim uylanishdi va ota bo'lishdi.",note:null},
{num:159,time:"00:16:08,199 --> 00:16:12,319",arabic:"كَبِرْتَ وَأَصْبَحْتَ تُفَكِّرُ بِالزَّوَاجِ أَيْضًا",segs:[{ar:"كَبِرْتَ",uz:"ulg'ayding"},{ar:"وَأَصْبَحْتَ تُفَكِّرُ بِالزَّوَاجِ أَيْضًا",uz:"va endi sen ham uylanish haqida o'ylayapsan"}],full_uz:"Ulg'ayding va endi sen ham uylanish haqida o'ylayapsan.",note:null},
{num:160,time:"00:16:12,319 --> 00:16:15,559",arabic:"لَوْ أَنَّنِي وَجَدْتُ مِنْ عَمَلٍ أَقْتَاتُ مِنْهُ",segs:null,full_uz:"Qornimni to'ydiradigan biror ish topsam edi.",note:"اِقْتَاتَ — oziqlanmoq, tirikchilik qilmoq."},
{num:161,time:"00:16:15,559 --> 00:16:20,219",arabic:"أَلَيْسَ أَفْضَلَ مِنْ حَيَاةِ اللُّصُوصِ هَذِهِ؟",segs:null,full_uz:"Bu o'g'rilar hayotidan yaxshiroq emasmi?",note:null},
{num:162,time:"00:16:20,219 --> 00:16:23,980",arabic:"وَمَاذَا تَعْرِفُ غَيْرَ السَّرِقَةِ؟ أَمْ أَنَّكَ خَجِلْتَ مِنْ صَنْعَةِ أَبِيكَ؟",segs:[{ar:"وَمَاذَا تَعْرِفُ غَيْرَ السَّرِقَةِ؟",uz:"o'g'rilikdan boshqa nimani bilasan?"},{ar:"أَمْ أَنَّكَ خَجِلْتَ مِنْ صَنْعَةِ أَبِيكَ؟",uz:"yoki otangning hunaridan uyalasanmi?"}],full_uz:"O'g'rilikdan boshqa nimani bilasan? Yoki otangning hunaridan uyalasanmi?",note:"صَنْعَةٌ — hunar, kasb."},
{num:163,time:"00:16:23,980 --> 00:16:27,480",arabic:"أُمَّهْ السَّرِقَةُ لَيْسَتْ صَنْعَةً، لَيْسَتْ صَنْعَةً",segs:[{ar:"السَّرِقَةُ لَيْسَتْ صَنْعَةً",uz:"o'g'rilik hunar emas"},{ar:"لَيْسَتْ صَنْعَةً",uz:"hunar emas"}],full_uz:"O'g'rilik hunar emas, hunar emas.",note:null},
{num:164,time:"00:16:27,480 --> 00:16:30,879",arabic:"وَهَذَا الْمَكَانُ لَيْسَ لِي",segs:null,full_uz:"Bu joy ham meniki emas.",note:null},
{num:165,time:"00:16:30,879 --> 00:16:35,800",arabic:"أَجَلْ، مَكَانُكَ عَلَى يَمِينِ هَارُونَ الرَّشِيدِ",segs:[{ar:"أَجَلْ، مَكَانُكَ عَلَى يَمِينِ هَارُونَ الرَّشِيدِ",uz:"ha, sening joying Horun ar-Rashidning o'ng tomonida"}],full_uz:"Ha, sening joying Horun ar-Rashidning o'ng tomonida.",note:null},
{num:166,time:"00:16:35,800 --> 00:16:37,980",arabic:"وَهَلْ تَجِدُ شَيْئًا غَيْرَ السَّرِقَةِ؟",segs:null,full_uz:"O'g'rilikdan boshqa biror narsa topasanmi?",note:null},
{num:167,time:"00:16:38,980 --> 00:16:40,200",arabic:"وَلَيْتَكَ تَفْرَحُ فِيهَا",segs:null,full_uz:"Qaniydi, bundan xursand bo'lsang.",note:null},
{num:168,time:"00:16:40,200 --> 00:16:43,320",arabic:"إِنَّكَ لَا تَسْرِقُ إِلَّا مَا لَا يُسْمِنُ وَلَا يُغْنِي مِنْ جُوعٍ",segs:[{ar:"إِنَّكَ لَا تَسْرِقُ إِلَّا مَا لَا يُسْمِنُ",uz:"sen faqat semirtirmaydigan narsalarni o'g'irlaysan"},{ar:"وَلَا يُغْنِي مِنْ جُوعٍ",uz:"ochlikdan qutqarmaydigan narsalarni"}],full_uz:"Sen faqat semirtirmaydigan va ochlikdan qutqarmaydigan narsalarni o'g'irlaysan.",note:"أَسْمَنَ — semirtirmoq. أَغْنَى عَنْ — xalos qilmoq, kifoya qilmoq."},
{num:169,time:"00:16:43,320 --> 00:16:44,980",arabic:"إِنَّكَ عَارٌ حَتَّى عَلَى اللُّصُوصِ",segs:[{ar:"إِنَّكَ عَارٌ",uz:"sen uyat-san"},{ar:"حَتَّى عَلَى اللُّصُوصِ",uz:"hatto o'g'rilar uchun ham"}],full_uz:"Sen hatto o'g'rilar uchun ham uyatsan.",note:null},
{num:170,time:"00:16:45,580 --> 00:16:48,399",arabic:"ذَلِكَ لِأَنَّنِي لَسْتُ مِنْهُمْ",segs:null,full_uz:"Chunki men ulardan emasman.",note:null},
{num:171,time:"00:16:48,399 --> 00:16:49,980",arabic:"لَسْتُ مِنْهُمْ",segs:null,full_uz:"Men ulardan emasman.",note:null},
{num:172,time:"00:16:50,700 --> 00:16:53,360",arabic:"لَعَلَّ اللَّهَ لَمْ يَكْتُبْ لِي أَنْ أَكُونَ لِصًّا",segs:[{ar:"لَعَلَّ اللَّهَ لَمْ يَكْتُبْ لِي",uz:"balki Alloh men uchun yozmagandir"},{ar:"أَنْ أَكُونَ لِصًّا",uz:"o'g'ri bo'lishni"}],full_uz:"Balki Alloh men uchun o'g'ri bo'lishni yozmagandir.",note:null},
{num:173,time:"00:16:53,980 --> 00:17:00,539",arabic:"لَعَلَّ مَا قُدِّرَ لِي أَكْثَرُ مِمَّا أَقْتَرِفُهُ مِنْ سَرِقَةٍ تُنْقِصُ الْمُرُوءَةَ وَتُغْضِبُ الرَّبَّ وَتَقْطَعُ الرِّزْقَ",segs:[{ar:"لَعَلَّ مَا قُدِّرَ لِي أَكْثَرُ مِمَّا أَقْتَرِفُهُ مِنْ سَرِقَةٍ",uz:"balki mening taqdirimda o'g'irlik bilan qilayotganimdan ko'ra kattaroq narsa bordir"},{ar:"تُنْقِصُ الْمُرُوءَةَ وَتُغْضِبُ الرَّبَّ وَتَقْطَعُ الرِّزْقَ",uz:"u o'g'irlik esa mardlikni kamaytiradi, Robbini g'azablantiradi va rizqni to'sadi"}],full_uz:"Balki mening taqdirimda o'g'irlik bilan qilayotganimdan ko'ra kattaroq narsa bordir. O'g'irlik esa mardlikni kamaytiradi, Robbini g'azablantiradi va rizqni to'sadi.",note:"الْمُرُوءَةُ — mardlik, olijanoblik."},
{num:174,time:"00:17:00,539 --> 00:17:04,720",arabic:"لَا أَرَى أَنَّ الدُّنْيَا تُخَبِّئُ لَكَ إِلَّا مَزِيدًا مِنَ الْحَمَاقَاتِ",segs:[{ar:"لَا أَرَى أَنَّ الدُّنْيَا تُخَبِّئُ لَكَ",uz:"menimcha, dunyo senga tayyorlayotgani"},{ar:"إِلَّا مَزِيدًا مِنَ الْحَمَاقَاتِ",uz:"yanada ko'proq ahmoqliklardir"}],full_uz:"Menimcha, dunyo senga yanada ko'proq ahmoqliklardan boshqa narsa tayyorlamayapti.",note:"الْحَمَاقَاتُ — ahmoqliklar."},
{num:175,time:"00:17:04,720 --> 00:17:06,740",arabic:"وَلِي مَزِيدٌ مِنَ التَّعَاسِي",segs:null,full_uz:"Menga esa yanada ko'proq baxtsizliklar.",note:"التَّعَاسَةُ — baxtsizlik, ayanchli holat."},
{num:176,time:"00:17:06,740 --> 00:17:09,839",arabic:"اغْرُبْ عَنْ وَجْهِي فَقَدْ ذَهَبَ الشَّبَعُ بِعَقْلِكَ",segs:[{ar:"اغْرُبْ عَنْ وَجْهِي",uz:"ko'zimdan yo'qol"},{ar:"فَقَدْ ذَهَبَ الشَّبَعُ بِعَقْلِكَ",uz:"to'yish miyangni olib qo'yibdi"}],full_uz:"Ko'zimdan yo'qol, to'yish miyangni olib qo'yibdi.",note:null},
{num:177,time:"00:17:09,839 --> 00:17:17,000",arabic:"سَتَرَيْنَ أَنَّنِي أَهَمُّ مِمَّا تَتَوَسَّمِينَهُ فِيَّ يَا أُمَّ الْفَرَاشِ",segs:[{ar:"سَتَرَيْنَ أَنَّنِي أَهَمُّ مِمَّا تَتَوَسَّمِينَهُ فِيَّ",uz:"men sen o'ylagandan ham muhimroq ekanimni ko'rasan"},{ar:"يَا أُمَّ الْفَرَاشِ",uz:"ey Um al-Farosh"}],full_uz:"Men sen o'ylagandan ham muhimroq ekanimni ko'rasan, ey Um al-Farosh.",note:null},
{num:178,time:"00:17:17,000 --> 00:17:23,720",arabic:"يَا فَرَاشُ",segs:null,full_uz:"Ey Farosh.",note:null},
{num:179,time:"00:17:23,720 --> 00:17:25,000",arabic:"يَا فَرَاشُ",segs:null,full_uz:"Ey Farosh.",note:null},
{num:180,time:"00:17:25,000 --> 00:17:30,319",arabic:"يَا ابْنَ نُوحٍ",segs:null,full_uz:"Ey Nuhning o'g'li.",note:null},
{num:181,time:"00:17:30,319 --> 00:17:33,660",arabic:"هَلِ انْتَهَيْتُمْ مِنَ الدَّرْسِ؟",segs:null,full_uz:"Darsni tugatdingizmi?",note:null},
{num:182,time:"00:17:33,660 --> 00:17:35,240",arabic:"نَعَمْ لَقَدِ انْتَهَيْنَا أَيْنَ كُنْتَ؟",segs:[{ar:"نَعَمْ لَقَدِ انْتَهَيْنَا",uz:"ha, tugatdik"},{ar:"أَيْنَ كُنْتَ؟",uz:"qayerda eding?"}],full_uz:"Ha, tugatdik. Qayerda eding?",note:null},
{num:183,time:"00:17:35,240 --> 00:17:36,200",arabic:"تَعَلَّمُوا أَيْنَ كُنْتَ",segs:null,full_uz:"Bilib qo'ying, qayerda eding?",note:null},
{num:184,time:"00:17:36,200 --> 00:17:38,279",arabic:"مَا قَدْ تَكَرَّرَ غِيَابُكَ يَا أَحْمَدُ",segs:null,full_uz:"Ahmad, yo'qliging tez-tez takrorlanmoqda.",note:null},
{num:185,time:"00:17:38,279 --> 00:17:41,259",arabic:"يَا ابْنَ نُوحٍ تَعَلَّمْ أَنَّهُ لَا حِيلَةَ لِي بِذَلِكَ",segs:[{ar:"تَعَلَّمْ أَنَّهُ لَا حِيلَةَ لِي بِذَلِكَ",uz:"bilginki, bunga mening choram yo'q"}],full_uz:"Bilginki, bunga mening choram yo'q.",note:"لَا حِيلَةَ لِي — mening choram yo'q."},
{num:186,time:"00:17:41,259 --> 00:17:43,200",arabic:"أَخْشَى أَنَّ الشَّيْخَ حَانِقٌ عَلَيْكَ",segs:null,full_uz:"Shayx sendan jahli chiqishidan qo'rqaman.",note:"حَانِقٌ — g'azablangan, jahli chiqqan."},
{num:187,time:"00:17:43,799 --> 00:17:46,200",arabic:"أَتَحْسَبُ أَنَّ الشَّيْخَ سَيَطْرُدُنِي جَرَّاءَ ذَلِكَ؟",segs:[{ar:"أَتَحْسَبُ أَنَّ الشَّيْخَ سَيَطْرُدُنِي",uz:"shayx meni haydab yuboradi deb o'ylaysanmi"},{ar:"جَرَّاءَ ذَلِكَ؟",uz:"shu sababli?"}],full_uz:"Shayx meni shu sababli haydab yuboradi deb o'ylaysanmi?",note:"جَرَّاءَ — sababli, tufayli."},
{num:188,time:"00:17:47,000 --> 00:17:49,240",arabic:"لَا لَا أَظُنُّ أَنَّ الْأُمُورَ سَتَصِلُ إِلَى هَذَا الْحَدِّ",segs:[{ar:"لَا لَا أَظُنُّ أَنَّ الْأُمُورَ سَتَصِلُ إِلَى هَذَا الْحَدِّ",uz:"yo'q, ishlar bu darajaga boradi deb o'ylamayman"}],full_uz:"Yo'q, ishlar bu darajaga boradi deb o'ylamayman.",note:null},
{num:189,time:"00:17:49,240 --> 00:17:51,319",arabic:"فَأَنْتَ أَفْضَلُ طُلَّابِهِ وَالْأَثِيرُ عِنْدَهُ",segs:[{ar:"فَأَنْتَ أَفْضَلُ طُلَّابِهِ",uz:"sen uning eng yaxshi talabasisan"},{ar:"وَالْأَثِيرُ عِنْدَهُ",uz:"va uning sevimlisisan"}],full_uz:"Sen uning eng yaxshi talabasisan va uning sevimlisisan.",note:"الْأَثِيرُ — sevimli, e'zozli."},
{num:190,time:"00:17:51,319 --> 00:17:53,799",arabic:"لَكِنْ أَخْشَى إِنْ تَكَرَّرَ غِيَابُكَ أَنْ يَفْعَلَهَا",segs:[{ar:"لَكِنْ أَخْشَى إِنْ تَكَرَّرَ غِيَابُكَ",uz:"lekin yo'qliging yana takrorlansa qo'rqaman"},{ar:"أَنْ يَفْعَلَهَا",uz:"u buni qilishidan"}],full_uz:"Lekin yo'qliging yana takrorlansa, u buni qilishidan qo'rqaman.",note:null},
{num:191,time:"00:17:53,799 --> 00:17:56,140",arabic:"لَنْ يَتَكَرَّرَ غِيَابِي بَعْدَ ذَلِكَ إِنْ شَاءَ اللَّهُ",segs:[{ar:"لَنْ يَتَكَرَّرَ غِيَابِي بَعْدَ ذَلِكَ",uz:"bundan keyin yo'qligim takrorlanmaydi"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"inshaalloh"}],full_uz:"Bundan keyin yo'qligim takrorlanmaydi, inshaalloh.",note:null},
{num:192,time:"00:17:56,140 --> 00:17:58,619",arabic:"فَقَدْ فَرَغْتُ مِمَّا كَانَ يُشْغِلُنِي مِنَ الدُّكَّانِ",segs:null,full_uz:"Do'kon bilan bog'liq meni band qilgan ishlarni tugatdim.",note:null},
{num:193,time:"00:17:58,619 --> 00:18:00,480",arabic:"هَلْ وَجَدْتَ لَهَا مُكْتَرِيًا؟",segs:null,full_uz:"Unga ijarachi topdingmi?",note:null},
{num:194,time:"00:18:00,480 --> 00:18:01,019",arabic:"إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Inshaalloh.",note:null},
{num:195,time:"00:18:01,019 --> 00:18:02,940",arabic:"وَإِنْ تَمَّتِ الْأُمُورُ عَلَى خَيْرٍ",segs:null,full_uz:"Agar ishlar yaxshi yakunlansa.",note:null},
{num:196,time:"00:18:02,940 --> 00:18:05,019",arabic:"لَنْ أَتَأَخَّرَ بَعْدَ ذَلِكَ إِنْ شَاءَ اللَّهُ",segs:[{ar:"لَنْ أَتَأَخَّرَ بَعْدَ ذَلِكَ",uz:"bundan keyin kechikmayman"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"inshaalloh"}],full_uz:"Bundan keyin kechikmayman, inshaalloh.",note:null},
{num:197,time:"00:18:05,019 --> 00:18:05,720",arabic:"إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Inshaalloh.",note:null},
{num:198,time:"00:18:05,720 --> 00:18:05,940",arabic:"هَيَّا",segs:null,full_uz:"Qani.",note:null},
{num:199,time:"00:18:05,940 --> 00:18:10,359",arabic:"اُنْظُرْ مَنْ جَاءَ",segs:null,full_uz:"Qara, kim keldi.",note:null},
{num:200,time:"00:18:10,359 --> 00:18:12,720",arabic:"السَّيِّدُ الْمُتَأَخِّرُ كَالْعَادَةِ",segs:null,full_uz:"Har doimgidek kechikkan janob.",note:null},
{num:201,time:"00:18:12,720 --> 00:18:15,460",arabic:"أَمْسِكْ عَلَيْكَ لِسَانَكَ يَا صُهَيْبُ",segs:[{ar:"أَمْسِكْ عَلَيْكَ لِسَانَكَ",uz:"tilingni tiy"},{ar:"يَا صُهَيْبُ",uz:"ey Suhayb"}],full_uz:"Tilingni tiy, ey Suhayb.",note:"أَمْسَكَ عَلَى لِسَانِهِ — tilini tiymoq."},
{num:202,time:"00:18:15,460 --> 00:18:17,079",arabic:"وَاهْتَمَّ بِأَمْرِكَ",segs:null,full_uz:"O'z ishing bilan shug'ullan.",note:null},
{num:203,time:"00:18:17,079 --> 00:18:20,059",arabic:"أَنَا مُهْتَمٌّ بِأَمْرِي",segs:null,full_uz:"Men o'z ishim bilan shug'ullanyapman.",note:null},
{num:204,time:"00:18:20,059 --> 00:18:23,340",arabic:"وَلَا أَنْقَطِعُ عَنْ حَلَقَاتِ الدَّرْسِ كَالْآخَرِينَ",segs:[{ar:"وَلَا أَنْقَطِعُ عَنْ حَلَقَاتِ الدَّرْسِ",uz:"dars halqalarini tark etmayman"},{ar:"كَالْآخَرِينَ",uz:"boshqalar kabi"}],full_uz:"Boshqalar kabi dars halqalarini tark etmayman.",note:"اِنْقَطَعَ عَنْ — tark etmoq."},
{num:205,time:"00:18:23,340 --> 00:18:27,039",arabic:"عُدْ إِلَى حَانُوتِكَ وَاجْدُ لِنَفْسِكَ لُقْمَةً تَأْكُلُهَا",segs:[{ar:"عُدْ إِلَى حَانُوتِكَ",uz:"do'koningga qayt"},{ar:"وَاجْدُ لِنَفْسِكَ لُقْمَةً تَأْكُلُهَا",uz:"o'zingga yeyishga bir luqma top"}],full_uz:"Do'koningga qayt va o'zingga yeyishga bir luqma top.",note:"حَانُوتٌ — do'kon, savdo rastasi."},
{num:206,time:"00:18:27,039 --> 00:18:30,620",arabic:"هَلْ تَحْسَبُ أَنَّ السَّمَاءَ سَتُمْطِرُ عَلَيْكَ خُبْزَةً؟",segs:[{ar:"هَلْ تَحْسَبُ أَنَّ السَّمَاءَ سَتُمْطِرُ عَلَيْكَ",uz:"osmon senga yog'diradi deb o'ylaysanmi"},{ar:"خُبْزَةً؟",uz:"bir nonni?"}],full_uz:"Osmon senga non yog'diradi deb o'ylaysanmi?",note:null},
{num:207,time:"00:18:30,620 --> 00:18:32,140",arabic:"هَيَّا يَا ابْنَ حَنْبَلٍ هَيَّا دُمْ",segs:[{ar:"هَيَّا يَا ابْنَ حَنْبَلٍ",uz:"qani, ey Ibn Hanbal"},{ar:"هَيَّا دُمْ",uz:"qani, yur"}],full_uz:"Qani, ey Ibn Hanbal, yur.",note:null},
{num:208,time:"00:18:32,140 --> 00:18:34,059",arabic:"تَعَالَ نَذْهَبْ هَيَّا",segs:null,full_uz:"Kel, ketamiz, qani.",note:null},
{num:209,time:"00:18:34,059 --> 00:18:35,799",arabic:"هَيَّا تَعَالَ نَذْهَبْ",segs:null,full_uz:"Qani, kel, ketamiz.",note:null},
{num:210,time:"00:18:35,799 --> 00:18:40,660",arabic:"مَا رَأْيُكَ أَنْ تُؤَجِّرَنِي نَفْسَكَ وَدَعِ الْعِلْمَ لِأَهْلِهِ؟",segs:[{ar:"مَا رَأْيُكَ أَنْ تُؤَجِّرَنِي نَفْسَكَ",uz:"o'zingni menga xizmatga yollashingga nima deysan"},{ar:"وَدَعِ الْعِلْمَ لِأَهْلِهِ؟",uz:"ilmni esa uning ahliga qo'yib berasan?"}],full_uz:"O'zingni menga xizmatga yollashingga nima deysan? Ilmni esa uning ahliga qo'yib ber.",note:null},
{num:211,time:"00:18:45,460 --> 00:18:50,900",arabic:"لَنْ تَجِدَ فِي خُرَاسَانَ كُلِّهَا وَلَا فِي بَاقِي الْأَمْصَارِ مَنْ يَأْتِيكَ بِبِضَاعَةٍ كَهَذِهِ",segs:[{ar:"لَنْ تَجِدَ فِي خُرَاسَانَ كُلِّهَا",uz:"butun Xurosonda topolmaysan"},{ar:"وَلَا فِي بَاقِي الْأَمْصَارِ مَنْ يَأْتِيكَ بِبِضَاعَةٍ كَهَذِهِ",uz:"na boshqa shaharlarda ham senga bunday mol olib keladigan kishini"}],full_uz:"Butun Xurosonda va boshqa shaharlarda ham senga bunday mol olib keladigan kishini topolmaysan.",note:null},
{num:212,time:"00:18:50,900 --> 00:18:57,680",arabic:"إِنَّهَا جَمِيلَةٌ حَقًّا",segs:null,full_uz:"U haqiqatan ham chiroyli.",note:null},
{num:213,time:"00:18:57,680 --> 00:19:00,460",arabic:"مَا رَأْيُكَ أَنْ آخُذَ كُلَّ بِضَاعَتِكَ؟",segs:null,full_uz:"Barcha molingni olishimga nima deysan?",note:null},
{num:214,time:"00:19:01,079 --> 00:19:04,220",arabic:"كُنْتُ أَتَمَنَّى أَلَّا أَرُدَّ لَكَ طَلَبًا يَا أَبَا جَعْفَرٍ",segs:[{ar:"كُنْتُ أَتَمَنَّى أَلَّا أَرُدَّ لَكَ طَلَبًا",uz:"sendan kelgan iltimosni rad etmaslikni istardim"},{ar:"يَا أَبَا جَعْفَرٍ",uz:"ey Abu Ja'far"}],full_uz:"Sendan kelgan iltimosni rad etmaslikni istardim, ey Abu Ja'far.",note:null},
{num:215,time:"00:19:04,220 --> 00:19:06,779",arabic:"وَلَكِنَّ أَبَا جَعْفَرٍ أَوْصَانِي عَلَيْهَا",segs:null,full_uz:"Lekin Abu Ja'far uni menga ishonib topshirgan.",note:"أَوْصَى بِـ — ishonib topshirmoq, tayinlamoq."},
{num:216,time:"00:19:06,779 --> 00:19:11,500",arabic:"يَبْدُو أَنَّ أَبَاكَ لَنْ يَنْتَهِيَ مِنَ الْعَمَلِ الْيَوْمَ",segs:null,full_uz:"Ko'rinishidan, otang bugun ishini tugatmaydi.",note:null},
{num:217,time:"00:19:11,500 --> 00:19:16,059",arabic:"وَأَنَا أَيْضًا يَبْدُو أَنَّنِي لَنْ أَنْتَهِيَ مِنْ إِلْحَاحِكِ",segs:null,full_uz:"Men ham, shekilli, sening iltimosingdan qutulmayman.",note:"إِلْحَاحٌ — qat'iy talab qilish, qayta-qayta iltimos qilish."},
{num:218,time:"00:19:16,059 --> 00:19:23,880",arabic:"فَوْزُ مَا رَأْيُكَ أَنْ نَذْهَبَ إِلَى السُّوقِ وَحْدَنَا وَنَشْتَرِيَ مَا نُرِيدُ أَرْجُوكَ",segs:[{ar:"مَا رَأْيُكَ أَنْ نَذْهَبَ إِلَى السُّوقِ وَحْدَنَا",uz:"bozorga o'zimiz borishimizga nima deysan"},{ar:"وَنَشْتَرِيَ مَا نُرِيدُ أَرْجُوكَ",uz:"va xohlaganimizni sotib olamiz, iltimos"}],full_uz:"Bozorga o'zimiz borib, xohlaganimizni sotib olishimizga nima deysan? Iltimos.",note:null},
{num:219,time:"00:19:23,880 --> 00:19:27,940",arabic:"حَسَنًا حَسَنًا",segs:null,full_uz:"Xo'p, xo'p.",note:null},
{num:220,time:"00:19:27,940 --> 00:19:36,779",arabic:"أَبِي مَا رَأْيُكَ أَنْ نَذْهَبَ أَنَا وَأُخْتِي لِنَشْتَرِيَ الْأَقْمِشَةَ الَّتِي وَعَدْتُهَا بِهَا",segs:[{ar:"أَبِي مَا رَأْيُكَ أَنْ نَذْهَبَ أَنَا وَأُخْتِي",uz:"otajon, men va singlim borishimizga nima deysiz"},{ar:"لِنَشْتَرِيَ الْأَقْمِشَةَ الَّتِي وَعَدْتُهَا بِهَا",uz:"unga va'da qilgan matolarni sotib olish uchun"}],full_uz:"Otajon, men va singlim unga va'da qilgan matolarni sotib olish uchun borishimizga nima deysiz?",note:null},
{num:221,time:"00:19:36,779 --> 00:19:40,160",arabic:"فَهِيَ لَنْ تَتَوَقَّفَ عَنْ إِلْحَاحِهَا حَتَّى تَحْصُلَ عَلَى مَا تُرِيدُ",segs:[{ar:"فَهِيَ لَنْ تَتَوَقَّفَ عَنْ إِلْحَاحِهَا",uz:"u o'z iltimosini to'xtatmaydi"},{ar:"حَتَّى تَحْصُلَ عَلَى مَا تُرِيدُ",uz:"xohlagan narsasini olmaguncha"}],full_uz:"U xohlagan narsasini olmaguncha iltimos qilishdan to'xtamaydi.",note:null},
{num:222,time:"00:19:40,160 --> 00:19:45,600",arabic:"وَكَيْفَ أَتْرُكُكُمَا تَذْهَبَانِ لِوَحْدِكُمَا فِي مَدِينَةِ الْجَهْشَةِ؟",segs:[{ar:"وَكَيْفَ أَتْرُكُكُمَا تَذْهَبَانِ لِوَحْدِكُمَا",uz:"ikkovingizni qanday qilib yolg'iz yuboraman"},{ar:"فِي مَدِينَةِ الْجَهْشَةِ؟",uz:"Al-Jahsha shahrida?"}],full_uz:"Ikkovingizni Al-Jahsha shahrida qanday qilib yolg'iz yuboraman?",note:null},
{num:223,time:"00:19:45,600 --> 00:19:48,800",arabic:"وَهَلْ نَحْنُ صَغِيرَتَانِ يَا أَبِي حَتَّى تَخَافَ عَلَيْنَا؟",segs:[{ar:"وَهَلْ نَحْنُ صَغِيرَتَانِ يَا أَبِي",uz:"otajon, biz kichkina qizlarmizmi"},{ar:"حَتَّى تَخَافَ عَلَيْنَا؟",uz:"bizdan xavotir oladigan darajada?"}],full_uz:"Otajon, biz kichkina qizlarmizmi, bizdan xavotir oladigan darajada?",note:null},
{num:224,time:"00:19:48,800 --> 00:19:50,960",arabic:"نَشْتَرِي مَا نُرِيدُ وَنَلْتَقِي عِنْدَ الْقَافِلَةِ",segs:[{ar:"نَشْتَرِي مَا نُرِيدُ",uz:"xohlaganimizni sotib olamiz"},{ar:"وَنَلْتَقِي عِنْدَ الْقَافِلَةِ",uz:"va karvon yonida uchrashamiz"}],full_uz:"Xohlaganimizni sotib olamiz va karvon yonida uchrashamiz.",note:null},
{num:225,time:"00:19:50,960 --> 00:19:55,279",arabic:"حَسَنًا حَسَنًا كَمَا تُرِيدَانِ وَلَكِنْ لَا تَتَأَخَّرَا",segs:[{ar:"كَمَا تُرِيدَانِ",uz:"xohlaganingizdek"},{ar:"وَلَكِنْ لَا تَتَأَخَّرَا",uz:"lekin kechikmanglar"}],full_uz:"Xohlaganingizdek, lekin kechikmanglar.",note:null},
{num:226,time:"00:19:55,279 --> 00:19:57,740",arabic:"شُكْرًا لَكَ يَا أَبِي",segs:null,full_uz:"Rahmat, otajon.",note:null},
{num:227,time:"00:19:57,740 --> 00:20:03,240",arabic:"انْتَظِرِي انْتَظِرِي",segs:null,full_uz:"Kut, kut.",note:null},
{num:228,time:"00:20:03,240 --> 00:20:09,620",arabic:"إِنَّهُ يَعْنِي أَنَّ هُنَاكَ شَخْصًا مُهِمًّا مِنْ بَيْتٍ شَرِيفٍ",segs:[{ar:"إِنَّهُ يَعْنِي أَنَّ هُنَاكَ شَخْصًا مُهِمًّا",uz:"bu shuni anglatadiki, muhim bir kishi bor"},{ar:"مِنْ بَيْتٍ شَرِيفٍ",uz:"sharafli xonadondan"}],full_uz:"Bu shuni anglatadiki, sharafli xonadondan muhim bir kishi bor.",note:null},
{num:229,time:"00:20:09,619 --> 00:20:13,119",arabic:"سَيَهْرُبُ مِنَ الْقَصْرِ مِنْ خِلَالِ نَهْرِ دِجْلَةَ",segs:null,full_uz:"U Dajla daryosi orqali saroydan qochadi.",note:null},
{num:230,time:"00:20:13,119 --> 00:20:15,479",arabic:"وَثَمَّ مَنْ يَنْتَظِرُهُ فِي الْبَصْرَةِ",segs:null,full_uz:"Va Basrada uni kutayotgan kishi bor.",note:null},
{num:231,time:"00:20:15,479 --> 00:20:18,099",arabic:"وَبَعْدَ يَوْمٍ وَلَيْلَةٍ سَيُطْلَقُ",segs:null,full_uz:"Bir kun-u bir kechadan keyin ozod qilinadi.",note:null},
{num:232,time:"00:20:18,099 --> 00:20:23,139",arabic:"وَعَلَى مَنْ يَتَوَلَّى ذَلِكَ أَنْ يَهْرُبَ إِلَى مَدِينَةِ مَيَّافَارِقِينَ",segs:[{ar:"وَعَلَى مَنْ يَتَوَلَّى ذَلِكَ",uz:"buni amalga oshiradigan kishi"},{ar:"أَنْ يَهْرُبَ إِلَى مَدِينَةِ مَيَّافَارِقِينَ",uz:"Mayyafariqin shahriga qochishi kerak"}],full_uz:"Buni amalga oshiradigan kishi Mayyafariqin shahriga qochishi kerak.",note:null},
{num:233,time:"00:20:23,139 --> 00:20:32,699",arabic:"إِنْ كَانَ مَا تَقُولُهُ صَحِيحًا",segs:null,full_uz:"Agar aytayotganing to'g'ri bo'lsa.",note:null},
{num:234,time:"00:20:32,699 --> 00:20:38,479",arabic:"فَهَذَا يَعْنِي أَنَّ هُنَاكَ مُؤَامَرَةً تُحَاكُ بِلَيْلٍ فِي قَصْرِ الْخِلَافَةِ",segs:[{ar:"فَهَذَا يَعْنِي أَنَّ هُنَاكَ مُؤَامَرَةً تُحَاكُ بِلَيْلٍ",uz:"bu kechasi to'qilayotgan fitna borligini anglatadi"},{ar:"فِي قَصْرِ الْخِلَافَةِ",uz:"xalifalik saroyida"}],full_uz:"Bu xalifalik saroyida kechasi to'qilayotgan fitna borligini anglatadi.",note:"مُؤَامَرَةٌ تُحَاكُ — fitna rejalashtirilmoqda, fitna to'qilmoqda."},
{num:235,time:"00:20:38,480 --> 00:20:46,059",arabic:"وَأَظُنُّ أَنَّ الَّذِي سَيَهْرُبُ هُوَ مِنَ الطَّالِبِيِّينَ",segs:[{ar:"وَأَظُنُّ أَنَّ الَّذِي سَيَهْرُبُ",uz:"menimcha, qochadigan kishi"},{ar:"هُوَ مِنَ الطَّالِبِيِّينَ",uz:"Tolibiylardan bo'ladi"}],full_uz:"Menimcha, qochadigan kishi Tolibiylardan bo'ladi.",note:"الطَّالِبِيُّونَ — Tolibiylar sulolasi vakillari."},
{num:236,time:"00:20:46,059 --> 00:20:54,360",arabic:"وَلَيْسَ هُنَاكَ غَيْرُ عَمَارَةَ بْنِ الْأَيْهَمِ مَنْ قَامَ بِحَبْكِ مِثْلِ هَذِهِ الْمُؤَامَرَةِ",segs:[{ar:"وَلَيْسَ هُنَاكَ غَيْرُ عَمَارَةَ بْنِ الْأَيْهَمِ",uz:"bunday ishni qila oladigan Amora ibn al-Ayhamdan boshqa hech kim yo'q"},{ar:"مَنْ قَامَ بِحَبْكِ مِثْلِ هَذِهِ الْمُؤَامَرَةِ",uz:"bunday fitnani to'qigan"}],full_uz:"Bunday fitnani to'qiy oladigan Amora ibn al-Ayhamdan boshqa hech kim yo'q.",note:null},
{num:237,time:"00:20:54,360 --> 00:20:56,880",arabic:"مَوْلَايَ أَدْرَى",segs:null,full_uz:"Janobim biladi.",note:null},
{num:238,time:"00:20:56,880 --> 00:20:59,960",arabic:"لَكِنْ قُلْ لِي",segs:null,full_uz:"Lekin menga ayt.",note:null},
{num:239,time:"00:20:59,960 --> 00:21:04,500",arabic:"كَيْفَ اسْتَطَعْتَ فَكَّ طَلَاسِمِ هَذِهِ الرِّسَالَةِ؟",segs:null,full_uz:"Bu xatning jumboqlarini qanday yecha olding?",note:"طَلَاسِمُ — jumboqlar, sirli belgilar."},
{num:240,time:"00:21:04,500 --> 00:21:09,039",arabic:"أَنَا لَا عِلْمَ لِي بِفَنِّ الرَّسَائِلِ وَلَا بِفَكِّ طَلَاسِمِهَا يَا مَوْلَايَ",segs:[{ar:"أَنَا لَا عِلْمَ لِي بِفَنِّ الرَّسَائِلِ",uz:"men xatlar san'atini bilmayman"},{ar:"وَلَا بِفَكِّ طَلَاسِمِهَا يَا مَوْلَايَ",uz:"ularning jumboqlarini yechishni ham bilmayman, janobim"}],full_uz:"Men xatlar san'atini ham, ularning jumboqlarini yechishni ham bilmayman, janobim.",note:null},
{num:241,time:"00:21:09,039 --> 00:21:11,900",arabic:"إِنَّمَا هُوَ ابْنُ أَخِي أَحْمَدُ بْنُ حَنْبَلٍ",segs:[{ar:"إِنَّمَا هُوَ",uz:"buni qilgan kishi"},{ar:"ابْنُ أَخِي أَحْمَدُ بْنُ حَنْبَلٍ",uz:"jiyanim Ahmad ibn Hanbaldir"}],full_uz:"Buni qilgan kishi jiyanim Ahmad ibn Hanbaldir.",note:null},
{num:242,time:"00:21:11,900 --> 00:21:20,079",arabic:"ابْنُ أَخِيكَ هَذَا يَسْتَحِقُّ مُكَافَأَةً كَبِيرَةً عَلَى ذَكَائِهِ وَنَبَاهَتِهِ",segs:[{ar:"ابْنُ أَخِيكَ هَذَا يَسْتَحِقُّ مُكَافَأَةً كَبِيرَةً",uz:"bu jiyaning katta mukofotga loyiq"},{ar:"عَلَى ذَكَائِهِ وَنَبَاهَتِهِ",uz:"o'zining zakovati va zehnliligi uchun"}],full_uz:"Bu jiyaning zakovati va zehnliligi uchun katta mukofotga loyiq.",note:"نَبَاهَةٌ — zehnlilik, ziyraklik."},
{num:243,time:"00:21:20,079 --> 00:21:24,799",arabic:"ابْنُ أَخِي يَتِيمٌ وَوَهَبَهُ اللَّهُ حُسْنَ الْخَطِّ فَهُوَ يَصْلُحُ لِنَسْخِ الْكُتُبِ",segs:[{ar:"ابْنُ أَخِي يَتِيمٌ",uz:"jiyanim yetim"},{ar:"وَوَهَبَهُ اللَّهُ حُسْنَ الْخَطِّ",uz:"Alloh unga chiroyli xat yozish qobiliyatini bergan"},{ar:"فَهُوَ يَصْلُحُ لِنَسْخِ الْكُتُبِ",uz:"shuning uchun u kitoblarni ko'chirishga mos"}],full_uz:"Jiyanim yetim. Alloh unga chiroyli xat yozish qobiliyatini bergan, shuning uchun u kitoblarni ko'chirishga mos.",note:"نَسْخُ الْكُتُبِ — kitoblarni qo'lda ko'chirib yozish."},
{num:244,time:"00:21:24,799 --> 00:21:29,039",arabic:"فَهَلْ يَأْمُرُ مَوْلَايَ بِعَمَلٍ لَهُ فِي بَيْتِ الْحِكْمَةِ؟",segs:[{ar:"فَهَلْ يَأْمُرُ مَوْلَايَ بِعَمَلٍ لَهُ",uz:"janobim unga biror ish berishni buyuradimi"},{ar:"فِي بَيْتِ الْحِكْمَةِ؟",uz:"Bayt ul-Hikmada?"}],full_uz:"Janobim unga Bayt ul-Hikmada biror ish berishni buyuradimi?",note:"بَيْتُ الْحِكْمَةِ — Bayt ul-Hikma, ilmiy markaz."},
{num:245,time:"00:21:29,039 --> 00:21:34,200",arabic:"لَهُ ذَلِكَ وَلَكَ أَيْضًا جَزَاءُ مَا فَعَلْتَ",segs:[{ar:"لَهُ ذَلِكَ",uz:"u bunga loyiq"},{ar:"وَلَكَ أَيْضًا جَزَاءُ مَا فَعَلْتَ",uz:"senga ham qilgan ishing uchun mukofot bor"}],full_uz:"U bunga loyiq, senga ham qilgan ishing uchun mukofot bor.",note:null},
{num:246,time:"00:21:34,200 --> 00:21:36,819",arabic:"شَكَرَ اللَّهُ صَنِيعَكَ يَا مَوْلَايَ",segs:[{ar:"شَكَرَ اللَّهُ صَنِيعَكَ",uz:"Alloh qilgan yaxshiliging uchun seni mukofotlasin"},{ar:"يَا مَوْلَايَ",uz:"ey janobim"}],full_uz:"Alloh qilgan yaxshiliging uchun seni mukofotlasin, ey janobim.",note:null},
{num:247,time:"00:21:36,819 --> 00:21:40,400",arabic:"الْحَمْدُ لِلَّهِ قَدْ وَهَبَنِيَ اللَّهُ حَتَّى كَفَانِي",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo'lsin"},{ar:"قَدْ وَهَبَنِيَ اللَّهُ حَتَّى كَفَانِي",uz:"Alloh menga kifoya qiladigan ne'matlarni bergan"}],full_uz:"Allohga hamd bo'lsin, Alloh menga kifoya qiladigan ne'matlarni bergan.",note:null},
{num:248,time:"00:21:40,400 --> 00:21:47,580",arabic:"وَمَا فَعَلْتُ ذَلِكَ إِلَّا حِرْصًا عَلَى أُمَّتِي وَخَشْيَةً مِنْ فِتَنٍ قَدْ تَضُرُّ دِيَارَ الْإِسْلَامِ وَأَهْلَهَا",segs:[{ar:"وَمَا فَعَلْتُ ذَلِكَ إِلَّا حِرْصًا عَلَى أُمَّتِي",uz:"men buni faqat ummatim uchun qayg'urganim sababli qildim"},{ar:"وَخَشْيَةً مِنْ فِتَنٍ قَدْ تَضُرُّ دِيَارَ الْإِسْلَامِ وَأَهْلَهَا",uz:"islom yurtlari va uning ahliga zarar yetkazishi mumkin bo'lgan fitnalardan qo'rqib"}],full_uz:"Men buni faqat ummatim uchun qayg'urganim va islom yurtlari hamda uning ahliga zarar yetkazishi mumkin bo'lgan fitnalardan qo'rqqanim sababli qildim.",note:"حِرْصٌ — qattiq qayg'urish, ehtiyotkorlik. خَشْيَةٌ — qo'rquv, xavfsirash."},
{num:249,time:"00:21:47,580 --> 00:21:53,340",arabic:"لَيْتَ النَّاسَ كُلَّهُمْ فِي مِثْلِ حِرْصِكَ عَلَى دِينِكَ وَأُمَّتِكَ",segs:[{ar:"لَيْتَ النَّاسَ كُلَّهُمْ",uz:"qaniydi barcha odamlar"},{ar:"فِي مِثْلِ حِرْصِكَ عَلَى دِينِكَ وَأُمَّتِكَ",uz:"dining va ummatingga sen kabi g'amxo'r bo'lsalar"}],full_uz:"Qaniydi barcha odamlar dining va ummatingga sen kabi g'amxo'r bo'lsalar.",note:null},
{num:250,time:"00:21:53,340 --> 00:21:58,319",arabic:"أَبْوَابُنَا مَفْتُوحَةٌ لَكَ دَائِمًا يَا إِسْحَاقُ",segs:[{ar:"أَبْوَابُنَا مَفْتُوحَةٌ لَكَ دَائِمًا",uz:"eshiklarimiz senga doimo ochiq"},{ar:"يَا إِسْحَاقُ",uz:"ey Ishoq"}],full_uz:"Eshiklarimiz senga doimo ochiq, ey Ishoq.",note:null},
{num:251,time:"00:21:58,319 --> 00:22:02,900",arabic:"أَدَامَ اللَّهُ الْأَمْنَ وَالْأَمَانَ عَلَى أُمَّةِ الْإِسْلَامِ",segs:[{ar:"أَدَامَ اللَّهُ الْأَمْنَ وَالْأَمَانَ",uz:"Alloh tinchlik va osoyishtalikni davomli qilsin"},{ar:"عَلَى أُمَّةِ الْإِسْلَامِ",uz:"Islom ummati ustida"}],full_uz:"Alloh Islom ummati ustidagi tinchlik va osoyishtalikni davomli qilsin.",note:"الْأَمْنُ وَالْأَمَانُ — xavfsizlik va osoyishtalik."},
{num:252,time:"00:22:02,900 --> 00:22:07,540",arabic:"وَحَفِظَهَا مِنْ كُلِّ الْفِتَنِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ يَا مَوْلَايَ",segs:[{ar:"وَحَفِظَهَا مِنْ كُلِّ الْفِتَنِ",uz:"va uni barcha fitnalardan asrasin"},{ar:"مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ يَا مَوْلَايَ",uz:"ularning oshkorasi va yashirinidan, ey janobim"}],full_uz:"Va uni barcha fitnalarning oshkorasi va yashirinidan asrasin, ey janobim.",note:null},
{num:253,time:"00:22:07,540 --> 00:22:12,380",arabic:"بَارَكَ اللَّهُ فِيكَ يَا ابْنَ حَنْبَلٍ",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh seni barakali qilsin"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Alloh seni barakali qilsin, ey Ibn Hanbal.",note:null},
{num:254,time:"00:22:12,380 --> 00:22:14,220",arabic:"بَارَكَ اللَّهُ",segs:null,full_uz:"Alloh baraka bersin.",note:null},
{num:255,time:"00:22:14,220 --> 00:22:16,420",arabic:"أَيَأْذَنُ مَوْلَايَ لِي بِالانْصِرَافِ؟",segs:[{ar:"أَيَأْذَنُ مَوْلَايَ لِي بِالانْصِرَافِ؟",uz:"janobim ketishimga ijozat beradimi?"}],full_uz:"Janobim ketishimga ijozat beradimi?",note:"الانْصِرَافُ — ketish, chiqib ketish."},
{num:256,time:"00:22:16,420 --> 00:22:18,300",arabic:"رَافَقَتْكَ السَّلَامَةُ",segs:null,full_uz:"Salomatlik senga hamroh bo'lsin.",note:"رَافَقَتْكَ السَّلَامَةُ — omonlik hamrohing bo'lsin."},
{num:257,time:"00:22:18,300 --> 00:22:19,960",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Sizga salom bo'lsin.",note:null},
{num:258,time:"00:22:19,960 --> 00:22:24,560",arabic:"وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:[{ar:"وَعَلَيْكَ السَّلَامُ",uz:"senga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"Allohning rahmati va barakotlari bo'lsin"}],full_uz:"Senga ham salom, Allohning rahmati va barakotlari bo'lsin.",note:null},
{num:259,time:"00:24:02,900 --> 00:24:10,800",arabic:"كَيْفَ لَمْ تَأْتِيَا إِلَى الْآنِ؟",segs:null,full_uz:"Qanday qilib hali ham kelmadingizlar?",note:null},
{num:260,time:"00:24:10,800 --> 00:24:12,420",arabic:"وَمَا أَدْرَانِي أَنَا يَا أَبَا فَوْزٍ؟",segs:[{ar:"وَمَا أَدْرَانِي أَنَا",uz:"men qayerdan bilay"},{ar:"يَا أَبَا فَوْزٍ؟",uz:"ey Abu Fawz?"}],full_uz:"Men qayerdan bilay, ey Abu Fawz?",note:null},
{num:261,time:"00:24:12,420 --> 00:24:14,180",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o'zga kuch va quvvat yo'q.",note:null},
{num:262,time:"00:24:14,180 --> 00:24:15,540",arabic:"أَيْنَ اخْتَفَتَا؟",segs:null,full_uz:"Ular qayerga g'oyib bo'lishdi?",note:"اخْتَفَى — g'oyib bo'lmoq, yashirinmoq."},
{num:263,time:"00:24:15,540 --> 00:24:17,840",arabic:"مَا كَانَ عَلَيْكَ تَرْكُهُمَا وَحِيدَتَيْنِ؟",segs:[{ar:"مَا كَانَ عَلَيْكَ",uz:"senga to'g'ri kelmasdi"},{ar:"تَرْكُهُمَا وَحِيدَتَيْنِ؟",uz:"ikkovini yolg'iz qoldirish"}],full_uz:"Ikkovini yolg'iz qoldirish senga to'g'ri kelmasdi-ku?",note:null},
{num:264,time:"00:24:17,840 --> 00:24:19,460",arabic:"لِمَ أَتْرُكُهُمَا يَا أَبَا رُسْتُمَ؟",segs:[{ar:"لِمَ أَتْرُكُهُمَا",uz:"nega ularni qoldirarkanman"},{ar:"يَا أَبَا رُسْتُمَ؟",uz:"ey Abu Rustum?"}],full_uz:"Nega ularni qoldirarkanman, ey Abu Rustum?",note:null},
{num:265,time:"00:24:19,460 --> 00:24:20,880",arabic:"لَقَدْ وَعَدْتُهُمَا هُنَا",segs:null,full_uz:"Men ular bilan shu yerda uchrashishga va'dalashganman.",note:null},
{num:266,time:"00:24:20,880 --> 00:24:22,200",arabic:"سَأَبْحَثُ عَنْهُمَا",segs:null,full_uz:"Ularni qidiraman.",note:null},
{num:267,time:"00:24:22,200 --> 00:24:23,160",arabic:"هَيَّا هَيَّا بِسُرْعَةٍ",segs:null,full_uz:"Qani, qani, tezroq.",note:null},
{num:268,time:"00:24:32,900 --> 00:24:43,340",arabic:"إِذَنْ فَقَدْ بَدَأَتِ الْأَفْعَى الرَّقْطَاءُ تَخْرُجُ مِنْ جُحُورِهَا",segs:[{ar:"إِذَنْ فَقَدْ بَدَأَتِ الْأَفْعَى الرَّقْطَاءُ",uz:"demak, ola ilon"},{ar:"تَخْرُجُ مِنْ جُحُورِهَا",uz:"inlaridan chiqa boshladi"}],full_uz:"Demak, ola ilonlar inlaridan chiqa boshladi.",note:"الْأَفْعَى الرَّقْطَاءُ — chipor ilon, ola ilon."},
{num:269,time:"00:24:43,340 --> 00:24:49,900",arabic:"أَيَحْسَبُونَ أَنَّ هَارُونَ الرَّشِيدَ غَافِلٌ عَنْ دَسَائِسِهِمْ وَمَكَائِدِهِمْ؟",segs:[{ar:"أَيَحْسَبُونَ أَنَّ هَارُونَ الرَّشِيدَ غَافِلٌ",uz:"ular Horun ar-Rashid bexabar deb o'ylashyaptimi"},{ar:"عَنْ دَسَائِسِهِمْ وَمَكَائِدِهِمْ؟",uz:"ularning hiyla va makrlaridan?"}],full_uz:"Ular Horun ar-Rashid ularning hiyla va makrlaridan bexabar deb o'ylashyaptimi?",note:"دَسَائِسُ — yashirin hiylalar. مَكَائِدُ — makrlar, hiylalar."},
{num:270,time:"00:24:50,900 --> 00:24:55,220",arabic:"وَالَّذِي نَفْسِي بِيَدِهِ لَأَجْعَلَنَّهُمْ عِبْرَةً لِمَنْ يَعْتَبِرُ",segs:[{ar:"وَالَّذِي نَفْسِي بِيَدِهِ",uz:"jonim qo'lida bo'lgan Zotga qasam"},{ar:"لَأَجْعَلَنَّهُمْ عِبْرَةً لِمَنْ يَعْتَبِرُ",uz:"ularni ibrat oluvchilar uchun ibrat qilaman"}],full_uz:"Jonim qo'lida bo'lgan Zotga qasamki, ularni ibrat oluvchilar uchun ibrat qilaman.",note:null},
{num:271,time:"00:24:55,220 --> 00:24:59,600",arabic:"هَوِّنْ عَلَيْكَ يَا مَوْلَايَ فَهُمْ أَعْجَزُ مِنْ قَرَادَةٍ",segs:[{ar:"هَوِّنْ عَلَيْكَ يَا مَوْلَايَ",uz:"o'zingizni boshingizga oling, ey janobim"},{ar:"فَهُمْ أَعْجَزُ مِنْ قَرَادَةٍ",uz:"ular kanadan ham ojizroq"}],full_uz:"O'zingizni bosing, ey janobim. Ular kanadan ham ojizroq.",note:"هَوَّنَ عَلَيْهِ — taskin bermoq, yengil qilmoq. قَرَادَةٌ — kana."},
{num:272,time:"00:24:59,599 --> 00:25:02,579",arabic:"وَسَيَلْقَوْنَ جَزَاءَ مَا يَمْكُرُونَ",segs:null,full_uz:"Ular qilgan makrlarining jazosini oladilar.",note:null},
{num:273,time:"00:25:02,579 --> 00:25:05,379",arabic:"إِنَّهُمْ لَا يَسْتَحِقُّونَ مِنْكَ كُلَّ هَذَا الْغَضَبِ",segs:[{ar:"إِنَّهُمْ لَا يَسْتَحِقُّونَ مِنْكَ",uz:"ular sendan bunga loyiq emaslar"},{ar:"كُلَّ هَذَا الْغَضَبِ",uz:"bunchalik g'azabga"}],full_uz:"Ular sendan bunchalik g'azabga loyiq emaslar.",note:null},
{num:274,time:"00:25:05,379 --> 00:25:08,839",arabic:"كَيْفَ لَا يَسْتَحِقُّونَ كُلَّ هَذَا الْغَضَبِ يَا يَعْقُوبُ؟",segs:[{ar:"كَيْفَ لَا يَسْتَحِقُّونَ كُلَّ هَذَا الْغَضَبِ",uz:"qanday qilib ular bunchalik g'azabga loyiq bo'lmasinlar"},{ar:"يَا يَعْقُوبُ؟",uz:"ey Ya'qub?"}],full_uz:"Qanday qilib ular bunchalik g'azabga loyiq bo'lmasinlar, ey Ya'qub?",note:null},
{num:275,time:"00:25:09,879 --> 00:25:13,859",arabic:"وَهُمْ لَا يَكُفُّونَ عَنْ غَيِّهِمْ وَفَسَادِهِمْ وَإِفْسَادِهِمْ فِي الْأَرْضِ",segs:[{ar:"وَهُمْ لَا يَكُفُّونَ عَنْ غَيِّهِمْ",uz:"ular o'z zalolatlaridan to'xtamayaptilar"},{ar:"وَفَسَادِهِمْ وَإِفْسَادِهِمْ فِي الْأَرْضِ",uz:"yer yuzidagi buzg'unchiliklari va fasodlaridan"}],full_uz:"Ular o'z zalolatlari, fasodlari va yer yuzidagi buzg'unchiliklaridan to'xtamayaptilar.",note:"غَيٌّ — zalolat, adashish. إِفْسَادٌ — buzg'unchilik."},
{num:276,time:"00:25:13,859 --> 00:25:18,759",arabic:"وَكُلَّمَا غَفَرْنَا لِأَحَدِهِمْ جَازَوْا إِحْسَانَنَا جُحُودًا وَنُكْرَانًا",segs:[{ar:"وَكُلَّمَا غَفَرْنَا لِأَحَدِهِمْ",uz:"har safar ulardan birini kechirganimizda"},{ar:"جَازَوْا إِحْسَانَنَا جُحُودًا وَنُكْرَانًا",uz:"yaxshiligimizga noshukrlik va inkor bilan javob berishdi"}],full_uz:"Har safar ulardan birini kechirganimizda, yaxshiligimizga noshukrlik va inkor bilan javob berishdi.",note:"جُحُودٌ — inkor, noshukrlik. نُكْرَانٌ — tan olmaslik, noshukrlik."},
{num:277,time:"00:25:18,759 --> 00:25:20,279",arabic:"وَهَا هُوَ الطَّالِبِيُّ",segs:null,full_uz:"Mana Tolibiy.",note:null},
{num:278,time:"00:25:20,279 --> 00:25:23,719",arabic:"هَا هُوَ الطَّالِبِيُّ يُدَبِّرُ الدَّسَائِسَ مِنْ سِجْنِهِ",segs:[{ar:"هَا هُوَ الطَّالِبِيُّ",uz:"mana Tolibiy"},{ar:"يُدَبِّرُ الدَّسَائِسَ مِنْ سِجْنِهِ",uz:"u qamoqxonasidan turib hiylalarni rejalashtirmoqda"}],full_uz:"Mana Tolibiy, u qamoqxonasidan turib hiylalarni rejalashtirmoqda.",note:null},
{num:279,time:"00:25:23,719 --> 00:25:26,779",arabic:"سَيَنَالُونَ جَزَاءَ مَا يَمْكُرُونَ بِعَوْنِ اللَّهِ",segs:[{ar:"سَيَنَالُونَ جَزَاءَ مَا يَمْكُرُونَ",uz:"ular qilgan makrlarining jazosini oladilar"},{ar:"بِعَوْنِ اللَّهِ",uz:"Allohning yordami bilan"}],full_uz:"Ular qilgan makrlarining jazosini Allohning yordami bilan oladilar.",note:null},
{num:280,time:"00:25:26,779 --> 00:25:33,259",arabic:"أُرِيدُكَ أَنْ تَأْدَ هَذِهِ الْمُؤَامَرَةَ فِي مَهْدِهَا قَبْلَ أَنْ يَتَّسِعَ الْخَرْقُ عَلَى الرَّاقِعِ",segs:[{ar:"أُرِيدُكَ أَنْ تَئِدَ هَذِهِ الْمُؤَامَرَةَ فِي مَهْدِهَا",uz:"bu fitnani hali boshidanoq bo'g'ib tashlashingni istayman"},{ar:"قَبْلَ أَنْ يَتَّسِعَ الْخَرْقُ عَلَى الرَّاقِعِ",uz:"vaziyat tuzatib bo'lmaydigan darajaga yetishidan oldin"}],full_uz:"Bu fitnani vaziyat tuzatib bo'lmaydigan darajaga yetishidan oldin hali boshidanoq bo'g'ib tashlashingni istayman.",note:"وَأَدَ — tiriklay ko'mmoq; bu yerda fitnani boshidanoq bostirmoq. الْخَرْقُ عَلَى الرَّاقِعِ — yirtiqni yamovchi uchun yirtiqning kattalashib ketishi, ya'ni vaziyatning og'irlashishi."},
{num:281,time:"00:25:33,259 --> 00:25:38,920",arabic:"كُنْ عَلَى ثِقَةٍ يَا مَوْلَايَ بِأَنَّ عَمَارَةَ بْنَ الْأَيْهَمِ وَكُلَّ مَنْ شَايَعَهُ وَتَبِعَهُ",segs:[{ar:"كُنْ عَلَى ثِقَةٍ يَا مَوْلَايَ",uz:"ishonchingiz komil bo'lsin, ey janobim"},{ar:"بِأَنَّ عَمَارَةَ بْنَ الْأَيْهَمِ وَكُلَّ مَنْ شَايَعَهُ وَتَبِعَهُ",uz:"Amora ibn al-Ayham va unga ergashganlarning barchasi"}],full_uz:"Ishonchingiz komil bo'lsin, ey janobim: Amora ibn al-Ayham va unga ergashganlarning barchasi...",note:"شَايَعَ — qo'llab-quvvatlamoq, tarafdor bo'lmoq."},
{num:282,time:"00:25:38,920 --> 00:25:42,920",arabic:"سَيَنَالُونَ الْجَزَاءَ الَّذِي يَرْدَعُهُمْ وَيَرْدَعُ أَمْثَالَهُمْ",segs:[{ar:"سَيَنَالُونَ الْجَزَاءَ",uz:"jazoga duchor bo'ladilar"},{ar:"الَّذِي يَرْدَعُهُمْ وَيَرْدَعُ أَمْثَالَهُمْ",uz:"u jazo ularni va ularga o'xshaganlarni tiyadi"}],full_uz:"Ular o'zlarini va ularga o'xshaganlarni tiyadigan jazoga duchor bo'ladilar.",note:"رَدَعَ — tiyib qo'ymoq, qaytarmoq."},
{num:283,time:"00:25:42,920 --> 00:25:45,920",arabic:"مِمَّا يَعِيثُونَ فَسَادًا فِي دِيَارِ الْمُسْلِمِينَ",segs:null,full_uz:"Musulmonlar yurtlarida fasod tarqatishlaridan.",note:"عَاثَ فَسَادًا — fasod tarqatmoq, buzg'unchilik qilmoq."},
{num:284,time:"00:25:45,920 --> 00:25:50,920",arabic:"اشْدُدْ يَدَكَ عَلَى ابْنِ الْأَيْهَمِ حَتَّى يَعْتَرِفَ بِأَسْمَاءِ جَمِيعِ الْخَوَنَةِ",segs:[{ar:"اشْدُدْ يَدَكَ عَلَى ابْنِ الْأَيْهَمِ",uz:"Ibn al-Ayhamga qattiq choralar ko'r"},{ar:"حَتَّى يَعْتَرِفَ بِأَسْمَاءِ جَمِيعِ الْخَوَنَةِ",uz:"barcha xoinlarning nomlarini tan olguncha"}],full_uz:"Ibn al-Ayhamga barcha xoinlarning nomlarini tan olguncha qattiq choralar ko'r.",note:"شَدَّ يَدَهُ عَلَى — qattiq chora ko'rmoq. الْخَوَنَةُ — xoinlar."},
{num:285,time:"00:25:50,920 --> 00:25:53,299",arabic:"جِئْنِي بِهَذَا الْمُجْرِمِ السَّاعَةَ",segs:null,full_uz:"Bu jinoyatchini darhol oldimga keltir.",note:"السَّاعَةَ — darhol, hoziroq."},
{num:286,time:"00:25:53,299 --> 00:25:56,440",arabic:"أَمْرُكَ يَا مَوْلَايَ",segs:null,full_uz:"Buyrug'ingiz, ey janobim.",note:null},
{num:287,time:"00:26:10,879 --> 00:26:14,519",arabic:"أَنَا الرَّجُلُ الضَّرْبُ الَّذِي تَعْرِفُونَهُ",segs:[{ar:"أَنَا الرَّجُلُ الضَّرْبُ",uz:"men siz biladigan uddaburon kishiman"},{ar:"الَّذِي تَعْرِفُونَهُ",uz:"siz tanigan"}],full_uz:"Men siz tanigan uddaburon kishiman.",note:"ضَرْبٌ — bu yerda chaqqon, uddaburon ma'nosida."},
{num:288,time:"00:26:10,879 --> 00:26:14,519",arabic:"خِشَاشٌ كَرَأْسِ الْحَيَّةِ الْمُتَوَقِّدِ",segs:null,full_uz:"O'tkir va chaqqon, xuddi ilonning boshidek.",note:"خِشَاشٌ — o'tkir, chaqqon. الْمُتَوَقِّدُ — chaqnab turgan, o'tkir."},
{num:289,time:"00:26:18,519 --> 00:26:19,519",arabic:"أَحْمَدُ",segs:null,full_uz:"Ahmad.",note:null},
{num:290,time:"00:26:19,519 --> 00:26:24,920",arabic:"أَنْتَ تَعْلَمُ أَنَّ صُهَيْبًا لَمْ يَقُلْ مَا قَالَ إِلَّا لِأَنَّهُ يَحْسُدُكَ لِمَكَانَتِكَ عِنْدَ الشَّيْخِ",segs:[{ar:"أَنْتَ تَعْلَمُ أَنَّ صُهَيْبًا لَمْ يَقُلْ مَا قَالَ",uz:"Suhayb aytgan gapini shunchaki aytmaganini bilasan"},{ar:"إِلَّا لِأَنَّهُ يَحْسُدُكَ لِمَكَانَتِكَ عِنْدَ الشَّيْخِ",uz:"u faqat shayx huzuridagi mavqeingga hasad qilgani uchun"}],full_uz:"Suhayb aytgan gapini faqat shayx huzuridagi mavqeingga hasad qilgani uchun aytganini bilasan.",note:null},
{num:291,time:"00:26:24,920 --> 00:26:27,099",arabic:"وَبَرَاعَتِكَ الَّتِي لَا يَمْلِكُ مِعْشَارَهَا",segs:null,full_uz:"Va u sening o'ndan biriga ham ega bo'lmagan mahoratingga.",note:"مِعْشَارٌ — o'ndan bir qism."},
{num:292,time:"00:26:27,099 --> 00:26:28,740",arabic:"أَخِي مُحَمَّدُ",segs:null,full_uz:"Akam Muhammad.",note:null},
{num:293,time:"00:26:28,740 --> 00:26:32,400",arabic:"يَجِبُ أَلَّا نَذْكُرَ أَحَدًا بِسُوءٍ فِي غِيَابِهِ",segs:[{ar:"يَجِبُ أَلَّا نَذْكُرَ أَحَدًا بِسُوءٍ",uz:"biror kishini yomonlab gapirmasligimiz kerak"},{ar:"فِي غِيَابِهِ",uz:"u yo'qligida"}],full_uz:"Biror kishini u yo'qligida yomonlab gapirmasligimiz kerak.",note:null},
{num:294,time:"00:26:32,400 --> 00:26:33,440",arabic:"هَذَا أَوَّلًا",segs:null,full_uz:"Bu birinchidan.",note:null},
{num:295,time:"00:26:33,440 --> 00:26:35,799",arabic:"أَمَّا ثَانِيًا",segs:null,full_uz:"Ikkinchidan.",note:null},
{num:296,time:"00:26:35,799 --> 00:26:39,420",arabic:"إِنْ فَكَّرْتَ فِي كَلَامِ صُهَيْبٍ وَجَدْتَهُ صَحِيحًا",segs:[{ar:"إِنْ فَكَّرْتَ فِي كَلَامِ صُهَيْبٍ",uz:"Suhaybning gaplari haqida o'ylab ko'rsang"},{ar:"وَجَدْتَهُ صَحِيحًا",uz:"uni to'g'ri deb topasan"}],full_uz:"Suhaybning gaplari haqida o'ylab ko'rsang, uni to'g'ri deb topasan.",note:null},
{num:297,time:"00:26:49,519 --> 00:26:55,559",arabic:"لَعَلَّ أَمْثَالِي مِنَ الْأَفْضَلِ لَهُمْ",segs:null,full_uz:"Balki men kabi odamlar uchun yaxshiroqdir.",note:null},
{num:298,time:"00:26:55,559 --> 00:26:59,839",arabic:"أَنْ يَنْشَغِلُوا بِقُوتِ يَوْمِهِمْ",segs:null,full_uz:"Kunlik rizqi bilan shug'ullanishlari.",note:"قُوتُ الْيَوْمِ — kunlik rizq, tirikchilik."},
{num:299,time:"00:26:59,839 --> 00:27:02,279",arabic:"وَنَقْمَةِ عَيْشِهِ",segs:null,full_uz:"Va tirikchiligining og'irligi bilan.",note:"نَقْمَةٌ — nafrat, qiyinchilik; bu yerda matn noaniq."},
{num:300,time:"00:27:02,279 --> 00:27:07,139",arabic:"كَيْفَ تَقُولُ ذَلِكَ يَا أَحْمَدُ؟",segs:null,full_uz:"Qanday qilib bunday deysan, ey Ahmad?",note:null},
{num:301,time:"00:27:07,139 --> 00:27:12,180",arabic:"لَعَلَّهُ تَرَفٌ مِنِّي أَنْ أَسْعَى إِلَى طَلَبِ الْعِلْمِ",segs:[{ar:"لَعَلَّهُ تَرَفٌ مِنِّي",uz:"balki bu men tomondan ortiqcha istakdir"},{ar:"أَنْ أَسْعَى إِلَى طَلَبِ الْعِلْمِ",uz:"ilm talab qilishga intilishim"}],full_uz:"Balki ilm talab qilishga intilishim men tomondan ortiqcha istakdir.",note:"تَرَفٌ — farovonlik, dabdaba; bu yerda ortiqcha istak ma'nosida."},
{num:302,time:"00:27:12,180 --> 00:27:15,299",arabic:"وَأَنَا أَرَى الْفَاقَةَ الَّتِي نَحْنُ فِيهَا",segs:null,full_uz:"Holbuki, men biz yashayotgan faqirlikni ko'rib turibman.",note:"الْفَاقَةُ — qashshoqlik, muhtojlik."},
{num:303,time:"00:27:15,299 --> 00:27:18,180",arabic:"وَالْعَوَزَ الَّذِي يَقُضُّ مَضْجَعَهُمْ",segs:null,full_uz:"Va ularning oromini buzayotgan muhtojlikni.",note:"الْعَوَزُ — muhtojlik. يَقُضُّ مَضْجَعَهُ — oromini buzmoq, bezovta qilmoq."},
{num:304,time:"00:27:18,180 --> 00:27:22,000",arabic:"حَقِيقٌ بِي أَنْ لَا أُفَكِّرَ فِي نَفْسِي فَقَطْ",segs:[{ar:"حَقِيقٌ بِي",uz:"men uchun to'g'ri bo'ladiki"},{ar:"أَنْ لَا أُفَكِّرَ فِي نَفْسِي فَقَطْ",uz:"faqat o'zim haqida o'ylamay"}],full_uz:"Men faqat o'zim haqida o'ylamasligim kerak.",note:"حَقِيقٌ بِي — men uchun lozim, menga to'g'ri keladi."},
{num:305,time:"00:27:22,000 --> 00:27:28,740",arabic:"أَحْمَدُ، الْفَقْرُ لَيْسَ عَيْبًا وَلَيْسَ عَقَبَةً أَمَامَ طَلَبِ الْعِلْمِ",segs:[{ar:"الْفَقْرُ لَيْسَ عَيْبًا",uz:"qashshoqlik ayb emas"},{ar:"وَلَيْسَ عَقَبَةً أَمَامَ طَلَبِ الْعِلْمِ",uz:"va ilm talab qilishga to'siq emas"}],full_uz:"Ahmad, qashshoqlik ayb emas va ilm talab qilishga to'siq emas.",note:null},
{num:306,time:"00:27:28,740 --> 00:27:33,380",arabic:"الْفَقْرُ لَيْسَ عَيْبًا أَجَلْ",segs:null,full_uz:"Qashshoqlik ayb emas, ha.",note:null},
{num:307,time:"00:27:33,380 --> 00:27:36,640",arabic:"بَلْ هُوَ مَسْلَبَةٌ لِلْعَقْلِ وَالْمُرُوءَةِ",segs:[{ar:"بَلْ هُوَ مَسْلَبَةٌ لِلْعَقْلِ وَالْمُرُوءَةِ",uz:"aksincha, u aql va mardlikni tortib oladi"}],full_uz:"Aksincha, u aql va mardlikni tortib oladi.",note:"مَسْلَبَةٌ — tortib oluvchi, yo'qotishga sabab bo'luvchi."},
{num:308,time:"00:27:36,640 --> 00:27:38,740",arabic:"وَمُذْهِبَةٌ لِلْعِلْمِ وَالْأَدَبِ",segs:null,full_uz:"Va ilm hamda odobni ketkazadi.",note:"مُذْهِبَةٌ — yo'qotuvchi, ketkazuvchi."},
{num:309,time:"00:27:38,740 --> 00:27:42,340",arabic:"الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ",segs:null,full_uz:"Har qanday holatda ham Allohga hamd bo'lsin.",note:null},
{num:310,time:"00:27:42,340 --> 00:27:45,019",arabic:"فَأَنَا رَاضٍ بِقَضَاءِ اللَّهِ عَلَيَّ",segs:null,full_uz:"Men Allohning menga bergan taqdiriga roziman.",note:"قَضَاءُ اللَّهِ — Allohning taqdiri, hukmi."},
{num:311,time:"00:27:45,019 --> 00:27:52,019",arabic:"وَلَكِنَّنِي أَخْشَى أَنْ يَكُونَ انْصِرَافِي إِلَى الْعِلْمِ يَبْخَسُ حَقَّ أُمِّي",segs:[{ar:"وَلَكِنَّنِي أَخْشَى",uz:"lekin qo'rqaman"},{ar:"أَنْ يَكُونَ انْصِرَافِي إِلَى الْعِلْمِ",uz:"ilmga yuzlanishim"},{ar:"يَبْخَسُ حَقَّ أُمِّي",uz:"onamning haqqini poymol qilishidan"}],full_uz:"Lekin ilmga yuzlanishim onamning haqqini poymol qilishidan qo'rqaman.",note:"بَخَسَ حَقَّهُ — haqqini kamaytirmoq, haqqini poymol qilmoq."},
{num:312,time:"00:27:52,019 --> 00:27:58,160",arabic:"لَا يَا رَجُلُ لَا يَا رَجُلُ وَاللَّهِ إِنَّ طَلَبَكَ الْعِلْمَ أَحَبُّ إِلَى أُمِّكَ مِنْ مَالِ الدُّنْيَا جَمِيعًا",segs:[{ar:"لَا يَا رَجُلُ لَا يَا رَجُلُ",uz:"yo'q, ey odam, yo'q, ey odam"},{ar:"وَاللَّهِ إِنَّ طَلَبَكَ الْعِلْمَ أَحَبُّ إِلَى أُمِّكَ",uz:"Allohga qasamki, sening ilm talab qilishing onang uchun sevimliroq"},{ar:"مِنْ مَالِ الدُّنْيَا جَمِيعًا",uz:"butun dunyo molidan ham"}],full_uz:"Yo'q, ey odam, yo'q, ey odam. Allohga qasamki, sening ilm talab qilishing onang uchun butun dunyo molidan ham sevimliroq.",note:null},
{num:313,time:"00:27:58,160 --> 00:28:00,240",arabic:"لَيْتَ الْأَمْرَ كَمَا تَقُولُ",segs:null,full_uz:"Qaniydi, ish sen aytgandek bo'lsa.",note:null},
{num:314,time:"00:28:00,240 --> 00:28:05,119",arabic:"لَيْتَ الْأَمْرَ كَمَا تَقُولُ يَا ابْنَ نُوحٍ",segs:[{ar:"لَيْتَ الْأَمْرَ كَمَا تَقُولُ",uz:"qaniydi, ish sen aytgandek bo'lsa"},{ar:"يَا ابْنَ نُوحٍ",uz:"ey Nuhning o'g'li"}],full_uz:"Qaniydi, ish sen aytgandek bo'lsa, ey Nuhning o'g'li.",note:null},
{num:315,time:"00:28:15,019 --> 00:28:31,279",arabic:"السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ",segs:null,full_uz:"Mo'minlar amiriga salom bo'lsin.",note:null},
{num:316,time:"00:28:31,279 --> 00:28:32,460",arabic:"عَلَيْكَ السَّلَامُ",segs:null,full_uz:"Senga ham salom.",note:null},
{num:317,time:"00:28:32,460 --> 00:28:35,779",arabic:"الرَّحْمَةَ الرَّحْمَةَ يَا مَوْلَايَ الرَّحْمَةَ",segs:[{ar:"الرَّحْمَةَ الرَّحْمَةَ",uz:"rahm qiling, rahm qiling"},{ar:"يَا مَوْلَايَ الرَّحْمَةَ",uz:"ey janobim, rahm qiling"}],full_uz:"Rahm qiling, rahm qiling, ey janobim, rahm qiling.",note:null},
{num:318,time:"00:28:37,200 --> 00:28:40,039",arabic:"الْآنَ تَطْلُبُ الرَّحْمَةَ أَيُّهَا الْخَائِنُ",segs:[{ar:"الْآنَ تَطْلُبُ الرَّحْمَةَ",uz:"endi rahm so'rayapsanmi"},{ar:"أَيُّهَا الْخَائِنُ",uz:"ey xoin"}],full_uz:"Endi rahm so'rayapsanmi, ey xoin?",note:null},
{num:319,time:"00:28:40,039 --> 00:28:41,700",arabic:"إِنْ يَكُنْ ذَنْبِي كَبِيرًا",segs:null,full_uz:"Agar mening gunohim katta bo'lsa...",note:null},
{num:320,time:"00:28:41,700 --> 00:28:44,339",arabic:"فَإِنَّ عَفْوَكَ أَعْظَمُ يَا مَوْلَايَ",segs:[{ar:"فَإِنَّ عَفْوَكَ أَعْظَمُ",uz:"albatta, sizning afvingiz undan buyukroq"},{ar:"يَا مَوْلَايَ",uz:"ey janobim"}],full_uz:"Albatta, sizning afvingiz undan buyukroq, ey janobim.",note:null},
{num:321,time:"00:28:44,339 --> 00:28:52,500",arabic:"قَسَمًا بِاللَّهِ",segs:null,full_uz:"Allohga qasam.",note:null},
{num:322,time:"00:28:52,500 --> 00:28:59,240",arabic:"لَأَجْعَلَنَّكَ عِبْرَةً لِمَنْ تُسَوِّلُ لَهُ نَفْسُهُ نَقْضَ الْعَهْدِ وَخِيَانَةَ الْأُمَّةِ",segs:[{ar:"لَأَجْعَلَنَّكَ عِبْرَةً",uz:"seni ibrat qilaman"},{ar:"لِمَنْ تُسَوِّلُ لَهُ نَفْسُهُ نَقْضَ الْعَهْدِ وَخِيَانَةَ الْأُمَّةِ",uz:"ahdni buzish va ummatga xiyonat qilishni ko'ngliga tugadigan kishilar uchun"}],full_uz:"Seni ahdni buzish va ummatga xiyonat qilishni ko'ngliga tugadigan kishilar uchun ibrat qilaman.",note:"تُسَوِّلُ لَهُ نَفْسُهُ — ko'ngliga solmoq, vasvasa qilmoq."},
{num:323,time:"00:28:59,240 --> 00:29:05,980",arabic:"فِي الْمَرَّةِ الْمَاضِيَةِ سَبَقَتْ رَحْمَتِي غَضَبِي حِينَ عَفَوْتُ عَنْ يَحْيَى الطَّالِبِيِّ",segs:[{ar:"فِي الْمَرَّةِ الْمَاضِيَةِ سَبَقَتْ رَحْمَتِي غَضَبِي",uz:"o'tgan safar rahmatim g'azabimdan ustun keldi"},{ar:"حِينَ عَفَوْتُ عَنْ يَحْيَى الطَّالِبِيِّ",uz:"Yahyo at-Tolibiyni afv qilganimda"}],full_uz:"O'tgan safar Yahyo at-Tolibiyni afv qilganimda, rahmatim g'azabimdan ustun keldi.",note:null},
{num:324,time:"00:29:05,980 --> 00:29:10,099",arabic:"إِجْلَالًا لِنَسَبِهِ وَدَرْءًا لِلْفِتَنِ بَيْنَ الْمُسْلِمِينَ",segs:[{ar:"إِجْلَالًا لِنَسَبِهِ",uz:"nasabini hurmat qilgan holda"},{ar:"وَدَرْءًا لِلْفِتَنِ بَيْنَ الْمُسْلِمِينَ",uz:"musulmonlar o'rtasidagi fitnalarning oldini olish uchun"}],full_uz:"Nasabini hurmat qilgan holda va musulmonlar o'rtasidagi fitnalarning oldini olish uchun.",note:"إِجْلَالٌ — ulug'lash, hurmat qilish. دَرْءٌ — daf etish, oldini olish."},
{num:325,time:"00:29:10,099 --> 00:29:17,939",arabic:"أَمَّا هَذِهِ الْمَرَّةَ وَاللَّهِ وَاللَّهِ لَأَجْعَلَنَّكَ عِبْرَةً لِمَنْ يَعْتَبِرُ",segs:[{ar:"أَمَّا هَذِهِ الْمَرَّةَ",uz:"ammo bu safar"},{ar:"وَاللَّهِ وَاللَّهِ لَأَجْعَلَنَّكَ عِبْرَةً",uz:"Allohga qasamki, seni albatta ibrat qilaman"},{ar:"لِمَنْ يَعْتَبِرُ",uz:"ibrat oluvchilar uchun"}],full_uz:"Ammo bu safar, Allohga qasamki, seni ibrat oluvchilar uchun albatta ibrat qilaman.",note:null},
{num:326,time:"00:29:17,939 --> 00:29:23,299",arabic:"خُذُوهُ إِلَى الْقَاضِي أَبِي يُوسُفَ لِيَحْكُمَ فِيهِ حُكْمَ اللَّهِ فِي الْخَائِنِينَ",segs:[{ar:"خُذُوهُ إِلَى الْقَاضِي أَبِي يُوسُفَ",uz:"uni qozilarning qozisi Abu Yusufning oldiga olib boring"},{ar:"لِيَحْكُمَ فِيهِ حُكْمَ اللَّهِ فِي الْخَائِنِينَ",uz:"xoinlar haqida Allohning hukmi bilan hukm qilsin"}],full_uz:"Uni qozilarning qozisi Abu Yusufning oldiga olib boring, xoinlar haqida Allohning hukmi bilan hukm qilsin.",note:null},
{num:327,time:"00:29:23,299 --> 00:29:24,339",arabic:"خُذُوهُ",segs:null,full_uz:"Uni olib boring.",note:null},
{num:328,time:"00:29:28,559 --> 00:29:30,219",arabic:"يَا أَمِيرَ الْمُؤْمِنِينَ",segs:null,full_uz:"Ey mo'minlar amiri.",note:null},
{num:329,time:"00:29:39,279 --> 00:29:40,940",arabic:"أَتَشَفَّعُ لَكَ بِقَرَابَتِكَ بِالرَّسُولِ اللَّهِ أَنْ تُسَامِحَنِي يَا مَوْلَايَ",segs:[{ar:"أَتَشَفَّعُ لَكَ بِقَرَابَتِكَ بِالرَّسُولِ اللَّهِ",uz:"Rasululloh bilan qarindoshligingni vosita qilib"},{ar:"أَنْ تُسَامِحَنِي يَا مَوْلَايَ",uz:"meni kechirishingizni so'rayman, ey janobim"}],full_uz:"Rasululloh bilan qarindoshligingni vosita qilib, meni kechirishingizni so'rayman, ey janobim.",note:"شَفَاعَةٌ — shafoat, vositachilik."},
{num:330,time:"00:29:40,940 --> 00:29:53,220",arabic:"أَتَشَفَّعُ إِلَيْكَ بِابْنِ عَمِّكَ أَبِي الْقَاسِمِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:[{ar:"أَتَشَفَّعُ إِلَيْكَ بِابْنِ عَمِّكَ أَبِي الْقَاسِمِ مُحَمَّدٍ",uz:"amakivachchang Abu al-Qosim Muhammadni vositachi qilib sendan shafoat so'rayman"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo'llasin"}],full_uz:"Amakivachchang Abu al-Qosim Muhammadni vositachi qilib sendan shafoat so'rayman. Alloh u zotga salovot va salom yo'llasin.",note:null},
{num:331,time:"00:30:09,279 --> 00:30:19,339",arabic:"أَيْنَ أَنْتَ يَا فَوْزُ",segs:null,full_uz:"Qayerdasan, ey Fawz?",note:null},
{num:332,time:"00:30:19,339 --> 00:30:22,720",arabic:"أَيْنَ أَنْتَ يَا شَهْنَازُ",segs:null,full_uz:"Qayerdasan, ey Shahnaz?",note:null},
{num:333,time:"00:30:22,720 --> 00:30:25,579",arabic:"كَيْفَ اخْتَفَيْتُمَا يَا ابْنَتَيَّ",segs:[{ar:"كَيْفَ اخْتَفَيْتُمَا",uz:"qanday qilib g'oyib bo'ldingizlar"},{ar:"يَا ابْنَتَيَّ",uz:"ey qizlarim"}],full_uz:"Qanday qilib g'oyib bo'ldingizlar, ey qizlarim?",note:null},
{num:334,time:"00:30:25,579 --> 00:30:29,639",arabic:"سَأَبْحَثُ عَنْكُمَا فِي بَغْدَادَ كُلِّهَا",segs:[{ar:"سَأَبْحَثُ عَنْكُمَا",uz:"ikkovingizni qidiraman"},{ar:"فِي بَغْدَادَ كُلِّهَا",uz:"butun Bag'dod bo'ylab"}],full_uz:"Ikkovingizni butun Bag'dod bo'ylab qidiraman.",note:null},
{num:335,time:"00:30:29,639 --> 00:30:31,279",arabic:"حَتَّى أَجِدَكُمَا",segs:null,full_uz:"Toki ikkovingizni topgunimcha.",note:null},
{num:336,time:"00:31:39,279 --> 00:31:52,779",arabic:"الْحَمْدُ لِلَّهِ أَنَّنِي نَجَوْتُ",segs:null,full_uz:"Allohga hamd bo'lsin, qutulib qoldim.",note:"نَجَا — qutulmoq, omon qolmoq."},
{num:337,time:"00:31:52,779 --> 00:31:59,319",arabic:"الْقَتْلُ قَلِيلٌ عَلَى أَمْثَالِهِ مِنَ الْخَوَنَةِ يَا مَوْلَايَ",segs:[{ar:"الْقَتْلُ قَلِيلٌ عَلَى أَمْثَالِهِ مِنَ الْخَوَنَةِ",uz:"uning kabi xoinlar uchun o'lim ham kamlik qiladi"},{ar:"يَا مَوْلَايَ",uz:"ey janobim"}],full_uz:"Uning kabi xoinlar uchun o'lim ham kamlik qiladi, ey janobim.",note:null},
{num:338,time:"00:31:59,319 --> 00:32:04,740",arabic:"لَقَدْ تَشَفَّعَ إِلَيَّ بِقَرَابَةٍ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",segs:[{ar:"لَقَدْ تَشَفَّعَ إِلَيَّ بِقَرَابَةٍ مِنْ رَسُولِ اللَّهِ",uz:"u mendan Rasululloh bilan qarindoshligini vosita qilib shafoat so'radi"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo'llasin"}],full_uz:"U mendan Rasululloh bilan qarindoshligini vosita qilib shafoat so'radi. Alloh u zotga salovot va salom yo'llasin.",note:null},
{num:339,time:"00:32:07,140 --> 00:32:12,740",arabic:"وَلَكِنْ لَا أَدْرِي كَيْفَ مَنَعْتُ نَفْسِي عَنْ تَمْزِيقِهِ بِأَظَافِرِي عَلَى خِيَانَتِهِ",segs:[{ar:"وَلَكِنْ لَا أَدْرِي كَيْفَ مَنَعْتُ نَفْسِي",uz:"lekin o'zimni qanday tiyganimni bilmayman"},{ar:"عَنْ تَمْزِيقِهِ بِأَظَافِرِي عَلَى خِيَانَتِهِ",uz:"uning xiyonati uchun uni tirnoqlarim bilan tilib tashlashdan"}],full_uz:"Lekin uning xiyonati uchun uni tirnoqlarim bilan tilib tashlashdan o'zimni qanday tiyganimni bilmayman.",note:"مَنَعَ نَفْسَهُ عَنْ — o'zini tiyib qolmoq. تَمْزِيقٌ — yirtish, tilish."},
{num:340,time:"00:32:15,900 --> 00:32:22,860",arabic:"بَقَاؤُهُ الْآنَ حَيًّا أَفْضَلُ لَنَا حَتَّى يَعْتَرِفَ بِأَسْمَاءِ شُرَكَائِهِ مِنَ الْخَائِنِينَ",segs:[{ar:"بَقَاؤُهُ الْآنَ حَيًّا أَفْضَلُ لَنَا",uz:"uning hozir tirik qolishi biz uchun yaxshiroq"},{ar:"حَتَّى يَعْتَرِفَ بِأَسْمَاءِ شُرَكَائِهِ مِنَ الْخَائِنِينَ",uz:"xoinlar orasidagi sheriklarining nomlarini tan olguncha"}],full_uz:"Uning hozir tirik qolishi biz uchun yaxshiroq, toki xoinlar orasidagi sheriklarining nomlarini tan olsin.",note:null},
{num:341,time:"00:32:22,860 --> 00:32:28,220",arabic:"هَذِهِ الْمُؤَامَرَةُ وَرَاءَهَا شَرٌّ عَظِيمٌ يَا يَحْيَى",segs:[{ar:"هَذِهِ الْمُؤَامَرَةُ وَرَاءَهَا شَرٌّ عَظِيمٌ",uz:"bu fitnaning ortida katta yomonlik bor"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Bu fitnaning ortida katta yomonlik bor, ey Yahyo.",note:null},
{num:342,time:"00:32:28,220 --> 00:32:31,960",arabic:"وَالسُّؤَالُ الَّذِي يَفْتِكُ بِرَأْسِهِ",segs:null,full_uz:"Va boshni qotirayotgan savol shu.",note:"يَفْتِكُ بِرَأْسِهِ — boshini band qilmoq, boshini qotirmoq."},
{num:343,time:"00:32:31,960 --> 00:32:38,420",arabic:"كَيْفَ اسْتَطَاعَ خَائِنٌ مِثْلُهُ أَنْ يَكُونَ رَئِيسَ الْحَرَسِ",segs:[{ar:"كَيْفَ اسْتَطَاعَ خَائِنٌ مِثْلُهُ",uz:"uning kabi xoin qanday qilib uddaladi"},{ar:"أَنْ يَكُونَ رَئِيسَ الْحَرَسِ",uz:"qo'riqchilar boshlig'i bo'lishni"}],full_uz:"Uning kabi xoin qanday qilib qo'riqchilar boshlig'i bo'la oldi?",note:null},
{num:344,time:"00:32:38,420 --> 00:32:43,360",arabic:"أَلَيْسَ هَذَا ذَنْبًا أَكْبَرَ مِنْ ذَنْبِهِ نَفْسِهِ؟",segs:[{ar:"أَلَيْسَ هَذَا ذَنْبًا أَكْبَرَ",uz:"bu bundan ham katta gunoh emasmi"},{ar:"مِنْ ذَنْبِهِ نَفْسِهِ؟",uz:"uning o'z gunohidan?"}],full_uz:"Bu uning o'z gunohidan ham kattaroq gunoh emasmi?",note:null},
{num:345,time:"00:32:43,360 --> 00:32:46,420",arabic:"لَمْ نَرَ مِنْهُ إِلَّا الْوَلَاءَ يَا مَوْلَايَ",segs:[{ar:"لَمْ نَرَ مِنْهُ إِلَّا الْوَلَاءَ",uz:"biz undan faqat sadoqatni ko'rdik"},{ar:"يَا مَوْلَايَ",uz:"ey janobim"}],full_uz:"Biz undan faqat sadoqatni ko'rdik, ey janobim.",note:"الْوَلَاءُ — sadoqat, vafodorlik."},
{num:346,time:"00:32:46,420 --> 00:32:51,160",arabic:"لَمْ تَرَ مِنْهُ إِلَّا الْوَلَاءَ",segs:null,full_uz:"Sen undan faqat sadoqatni ko'rding.",note:null},
{num:347,time:"00:32:51,160 --> 00:32:53,559",arabic:"لَمْ تَرَ مِنْهُ إِلَّا الْوَلَاءَ",segs:null,full_uz:"Sen undan faqat sadoqatni ko'rding.",note:null},
{num:348,time:"00:32:53,559 --> 00:32:57,759",arabic:"وَهُوَ يُبَيِّتُ لَنَا الشَّرَّ وَيُضْمِرُ لَنَا الْخَدِيعَةَ",segs:[{ar:"وَهُوَ يُبَيِّتُ لَنَا الشَّرَّ",uz:"holbuki u bizga yomonlikni kechasi rejalashtirayotgan edi"},{ar:"وَيُضْمِرُ لَنَا الْخَدِيعَةَ",uz:"va bizga qarshi xiyonatni yashirayotgan edi"}],full_uz:"Holbuki, u bizga yomonlikni rejalashtirib, bizga qarshi xiyonatni yashirayotgan edi.",note:"يُبَيِّتُ — kechasi rejalashtirmoq, yashirincha tayyorlamoq. يُضْمِرُ — ichida yashirmoq."},
{num:349,time:"00:32:57,759 --> 00:32:59,720",arabic:"كَيْفَ يَكُونُ ذَلِكَ يَا يَحْيَى؟",segs:[{ar:"كَيْفَ يَكُونُ ذَلِكَ",uz:"bu qanday bo'lishi mumkin"},{ar:"يَا يَحْيَى؟",uz:"ey Yahyo?"}],full_uz:"Bu qanday bo'lishi mumkin, ey Yahyo?",note:null},
{num:350,time:"00:32:59,720 --> 00:33:02,960",arabic:"لَا يَعْلَمُ الْخَبَايَا إِلَّا اللَّهُ يَا مَوْلَايَ",segs:[{ar:"لَا يَعْلَمُ الْخَبَايَا إِلَّا اللَّهُ",uz:"yashirin sirlarni faqat Alloh biladi"},{ar:"يَا مَوْلَايَ",uz:"ey janobim"}],full_uz:"Yashirin sirlarni faqat Alloh biladi, ey janobim.",note:"الْخَبَايَا — yashirin sirlar, pinhona narsalar."},
{num:351,time:"00:33:02,960 --> 00:33:06,519",arabic:"أَرْجُو أَنْ نَجِدَ الْكَثِيرَ مِنْ أَمْثَالِهِ",segs:[{ar:"أَرْجُو أَنْ نَجِدَ الْكَثِيرَ",uz:"ko'pchiligini topishimizdan xavotirdaman"},{ar:"مِنْ أَمْثَالِهِ",uz:"unga o'xshaganlardan"}],full_uz:"Unga o'xshaganlardan ko'pchiligini topishimizdan xavotirdaman.",note:null},
{num:352,time:"00:33:06,519 --> 00:33:09,720",arabic:"مِمَّنْ لَا يَظْهَرُونَ إِلَّا الْوَلَاءَ",segs:[{ar:"مِمَّنْ لَا يَظْهَرُونَ إِلَّا الْوَلَاءَ",uz:"faqat sadoqatini namoyon qiladiganlardan"}],full_uz:"Faqat sadoqatini namoyon qiladiganlardan.",note:null},
{num:353,time:"00:33:09,720 --> 00:33:12,640",arabic:"وَيُبَيِّتُونَ لَنَا الْخَدِيعَةَ",segs:null,full_uz:"Ammo bizga qarshi xiyonatni yashirincha rejalashtiradiganlardan.",note:"يُبَيِّتُ — yashirincha rejalashtirmoq, kechasi tayyorlamoq."},
{num:354,time:"00:33:12,640 --> 00:33:15,000",arabic:"كُنْ عَلَى ثِقَةٍ يَا مَوْلَايَ",segs:null,full_uz:"Ishonchingiz komil bo'lsin, ey janobim.",note:null},
{num:355,time:"00:33:15,000 --> 00:33:17,720",arabic:"بِأَنَّ مِثْلَ هَذَا لَنْ يَحْدُثَ مَرَّةً أُخْرَى",segs:[{ar:"بِأَنَّ مِثْلَ هَذَا",uz:"bunday narsa"},{ar:"لَنْ يَحْدُثَ مَرَّةً أُخْرَى",uz:"yana bir bor sodir bo'lmaydi"}],full_uz:"Bunday narsa yana bir bor sodir bo'lmaydi.",note:null},
{num:356,time:"00:33:19,120 --> 00:33:24,720",arabic:"لَقَدْ كُنْتُ عَلَى ثِقَةٍ مِنْ قَبْلُ يَا يَحْيَى",segs:[{ar:"لَقَدْ كُنْتُ عَلَى ثِقَةٍ مِنْ قَبْلُ",uz:"men ilgari ham ishongan edim"},{ar:"يَا يَحْيَى",uz:"ey Yahyo"}],full_uz:"Men ilgari ham ishongan edim, ey Yahyo.",note:null},
{num:357,time:"00:33:24,720 --> 00:33:27,440",arabic:"وَهَا هُوَ شَرٌّ",segs:null,full_uz:"Mana yana bir yomonlik.",note:null},
{num:358,time:"00:33:27,440 --> 00:33:32,480",arabic:"سَنَكُونُ أَشَدَّ حِرْصًا وَأَكْثَرَ تَثَبُّتًا بِعَوْنِ اللَّهِ يَا مَوْلَايَ",segs:[{ar:"سَنَكُونُ أَشَدَّ حِرْصًا",uz:"yanada ehtiyotkor bo'lamiz"},{ar:"وَأَكْثَرَ تَثَبُّتًا",uz:"va yanada sinchiklab tekshiramiz"},{ar:"بِعَوْنِ اللَّهِ يَا مَوْلَايَ",uz:"Allohning yordami bilan, ey janobim"}],full_uz:"Allohning yordami bilan yanada ehtiyotkor bo'lamiz va yanada sinchiklab tekshiramiz, ey janobim.",note:"تَثَبُّتٌ — tekshirish, aniqlik bilan ish ko'rish."},
{num:359,time:"00:33:32,480 --> 00:33:34,059",arabic:"سَنَرَى",segs:null,full_uz:"Ko'ramiz.",note:null},
{num:360,time:"00:33:34,059 --> 00:33:37,160",arabic:"سَنَرَى",segs:null,full_uz:"Ko'ramiz.",note:null},
{num:361,time:"00:33:52,880 --> 00:33:54,200",arabic:"السَّلَامُ عَلَيْكُمْ",segs:null,full_uz:"Sizga salom bo'lsin.",note:null},
{num:362,time:"00:33:54,200 --> 00:33:56,160",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"Allohning rahmati bo'lsin"}],full_uz:"Sizga ham salom, Allohning rahmati bo'lsin.",note:null},
{num:363,time:"00:33:56,160 --> 00:33:59,720",arabic:"كُنْتُ أَبْحَثُ عَنْ أَبِي الَّذِي كَانَ يَبِيعُكَ أَمْشَاطًا مِنَ الْفِضَّةِ",segs:[{ar:"كُنْتُ أَبْحَثُ عَنْ أَبِي",uz:"otamni izlayotgandim"},{ar:"الَّذِي كَانَ يَبِيعُكَ أَمْشَاطًا مِنَ الْفِضَّةِ",uz:"u sizga kumush taroqlar sotardi"}],full_uz:"Otamni izlayotgandim. U sizga kumush taroqlar sotardi.",note:null},
{num:364,time:"00:33:59,720 --> 00:34:01,820",arabic:"آهْ التَّاجِرُ أَبُو فَوْزٍ",segs:null,full_uz:"Ha, savdogar Abu Fawz.",note:null},
{num:365,time:"00:34:02,300 --> 00:34:03,660",arabic:"أَجَلْ",segs:null,full_uz:"Ha.",note:null},
{num:366,time:"00:34:03,660 --> 00:34:05,160",arabic:"لَقَدْ ذَهَبَ",segs:null,full_uz:"U ketdi.",note:null},
{num:367,time:"00:34:05,160 --> 00:34:05,740",arabic:"إِلَى أَيْنَ؟",segs:null,full_uz:"Qayerga?",note:null},
{num:368,time:"00:34:05,740 --> 00:34:23,500",arabic:"لَا أَدْرِي",segs:null,full_uz:"Bilmayman.",note:null},
{num:369,time:"00:34:05,740 --> 00:34:23,500",arabic:"لَقَدْ أُعْجِبَ الْأَمِيرُ يَحْيَى الْبَرْمَكِيُّ بِحِدَّةِ ذَكَائِكَ وَقُدْرَتِكَ عَلَى فَكِّ طَلَاسِمِ رِسَالَةٍ",segs:[{ar:"لَقَدْ أُعْجِبَ الْأَمِيرُ يَحْيَى الْبَرْمَكِيُّ بِحِدَّةِ ذَكَائِكَ",uz:"amir Yahyo al-Barmaqiy sening o'tkir zehningdan hayratda qoldi"},{ar:"وَقُدْرَتِكَ عَلَى فَكِّ طَلَاسِمِ رِسَالَةٍ",uz:"va bir xatning jumboqlarini yecha olishingdan"}],full_uz:"Amir Yahyo al-Barmaqiy sening o'tkir zehning va bir xatning jumboqlarini yecha olish qobiliyatingdan hayratda qoldi.",note:"حِدَّةُ الذَّكَاءِ — o'tkir zehn. طَلَاسِمُ — jumboqlar, sirli belgilar."},
{num:370,time:"00:34:23,500 --> 00:34:28,519",arabic:"وَمُكَافَأَةً لَكَ أَمَرَ بِتَعْيِينِكَ نَسَّاخًا لِلْكُتُبِ فِي دَارِ الْحِكْمَةِ",segs:[{ar:"وَمُكَافَأَةً لَكَ",uz:"seni mukofotlash uchun"},{ar:"أَمَرَ بِتَعْيِينِكَ نَسَّاخًا لِلْكُتُبِ",uz:"seni kitob ko'chiruvchi qilib tayinlashni buyurdi"},{ar:"فِي دَارِ الْحِكْمَةِ",uz:"Bayt ul-Hikmada"}],full_uz:"Seni mukofotlash uchun seni Bayt ul-Hikmada kitob ko'chiruvchi qilib tayinlashni buyurdi.",note:"نَسَّاخٌ — kitob ko'chiruvchi, nusxakash."},
{num:371,time:"00:34:28,519 --> 00:34:30,099",arabic:"مَا رَأْيُكَ؟",segs:null,full_uz:"Nima deb o'ylaysan?",note:null},
{num:372,time:"00:34:30,099 --> 00:34:33,260",arabic:"وَلَكِنْ كَيْفَ سَأُوَفِّقُ بَيْنَ هَذَا الْعَمَلِ وَطَلَبِ الْعِلْمِ؟",segs:[{ar:"كَيْفَ سَأُوَفِّقُ بَيْنَ هَذَا الْعَمَلِ وَطَلَبِ الْعِلْمِ؟",uz:"bu ish bilan ilm talab qilishni qanday uyg'unlashtiraman?"}],full_uz:"Lekin bu ish bilan ilm talab qilishni qanday uyg'unlashtiraman?",note:"وَفَّقَ بَيْنَ — uyg'unlashtirmoq, muvofiqlashtirmoq."},
{num:373,time:"00:34:33,260 --> 00:34:36,420",arabic:"تَعْرِفُ أَنِّي حَرِيصٌ عَلَى طَلَبِ الْعِلْمِ حِرْصِي عَلَيْكَ",segs:[{ar:"تَعْرِفُ أَنِّي حَرِيصٌ عَلَى طَلَبِ الْعِلْمِ",uz:"ilm talab qilishingga juda g'amxo'r ekanimni bilasan"},{ar:"حِرْصِي عَلَيْكَ",uz:"senga bo'lgan g'amxo'rligim kabi"}],full_uz:"Senga bo'lgan g'amxo'rligim kabi, ilm talab qilishingga ham juda g'amxo'r ekanimni bilasan.",note:null},
{num:374,time:"00:34:36,420 --> 00:34:40,119",arabic:"لَا تَقْلَقْ سَنَجِدُ حَلًّا تُوَفِّقُ فِيهِ بَيْنَ طَلَبِ الْعِلْمِ وَالْعَمَلِ",segs:[{ar:"لَا تَقْلَقْ",uz:"xavotir olma"},{ar:"سَنَجِدُ حَلًّا",uz:"yechim topamiz"},{ar:"تُوَفِّقُ فِيهِ بَيْنَ طَلَبِ الْعِلْمِ وَالْعَمَلِ",uz:"unda ilm talab qilish bilan ishni uyg'unlashtirasan"}],full_uz:"Xavotir olma, ilm talab qilish bilan ishni uyg'unlashtiradigan yechim topamiz.",note:null},
{num:375,time:"00:34:40,119 --> 00:34:44,460",arabic:"حَسَنًا يَا عَمِّي وَلَكِنْ لَمْ أَكُنْ قَاطِعًا أَمْرًا حَتَّى أَشْهَدَ أُمِّي",segs:[{ar:"حَسَنًا يَا عَمِّي",uz:"xo'p, amaki"},{ar:"وَلَكِنْ لَمْ أَكُنْ قَاطِعًا أَمْرًا",uz:"lekin bir qarorga kelmayman"},{ar:"حَتَّى أَشْهَدَ أُمِّي",uz:"onam bilan maslahatlashmagunimcha"}],full_uz:"Xo'p, amaki. Lekin onam bilan maslahatlashmagunimcha bir qarorga kelmayman.",note:"قَطَعَ أَمْرًا — qarorga kelmoq."},
{num:376,time:"00:34:44,460 --> 00:34:45,599",arabic:"مَعَكَ كُلُّ الْحَقِّ",segs:null,full_uz:"Sen mutlaqo haqlisan.",note:null},
{num:377,time:"00:34:45,599 --> 00:34:52,000",arabic:"رَأْيُ أُمِّكَ بَرَكَةٌ لَكَ لَكِنْ فَلْتَعْلَمْ فُرَصُ الْحَيَاةِ كَالطَّيْرِ لَيْسَ لَهَا قَرَارٌ",segs:[{ar:"رَأْيُ أُمِّكَ بَرَكَةٌ لَكَ",uz:"onangning fikri sen uchun barakadir"},{ar:"لَكِنْ فَلْتَعْلَمْ",uz:"lekin bilib qo'y"},{ar:"فُرَصُ الْحَيَاةِ كَالطَّيْرِ لَيْسَ لَهَا قَرَارٌ",uz:"hayot imkoniyatlari qush kabi, bir joyda turmaydi"}],full_uz:"Onangning fikri sen uchun barakadir. Lekin bilib qo'y: hayot imkoniyatlari qush kabi, bir joyda turmaydi.",note:"قَرَارٌ — qaror topish, bir joyda qolish; bu yerda 'turg'unlik' ma'nosida."},
{num:378,time:"00:34:52,000 --> 00:34:54,460",arabic:"أَفْعَلُهُ إِنْ شَاءَ اللَّهُ",segs:null,full_uz:"Buni qilaman, inshaalloh.",note:null},
{num:379,time:"00:34:54,460 --> 00:35:15,440",arabic:"السَّلَامُ عَلَيْكِ يَا خَالَةُ",segs:[{ar:"السَّلَامُ عَلَيْكِ",uz:"sizga salom bo'lsin"},{ar:"يَا خَالَةُ",uz:"ey xola"}],full_uz:"Sizga salom bo'lsin, ey xola.",note:null},
{num:380,time:"00:35:15,440 --> 00:35:19,320",arabic:"وَعَلَيْكِ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",segs:[{ar:"وَعَلَيْكِ السَّلَامُ",uz:"sizga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"Allohning rahmati va barakotlari bo'lsin"}],full_uz:"Sizga ham salom, Allohning rahmati va barakotlari bo'lsin.",note:null},
{num:381,time:"00:35:19,320 --> 00:35:21,679",arabic:"أُرِيدُ أَنْ أَسْأَلَكِ عَنْ أَمْرِي إِنْ أَذِنْتِ",segs:[{ar:"أُرِيدُ أَنْ أَسْأَلَكِ عَنْ أَمْرِي",uz:"sizdan bir ishim haqida so'ramoqchiman"},{ar:"إِنْ أَذِنْتِ",uz:"ijozat bersangiz"}],full_uz:"Ijozat bersangiz, sizdan bir ishim haqida so'ramoqchiman.",note:null},
{num:382,time:"00:35:21,679 --> 00:35:24,279",arabic:"تَفَضَّلِي إِنِّي مُنْصِتَةٌ",segs:[{ar:"تَفَضَّلِي",uz:"marhamat"},{ar:"إِنِّي مُنْصِتَةٌ",uz:"men tinglayapman"}],full_uz:"Marhamat, sizni tinglayapman.",note:"مُنْصِتٌ — diqqat bilan tinglovchi."},
{num:383,time:"00:35:24,279 --> 00:35:27,179",arabic:"هَلْ رَأَيْتِ رَجُلًا خُرَاسَانِيًّا وَمَعَهُ فَتَاةٌ فِي مِثْلِ عُمْرِي",segs:[{ar:"هَلْ رَأَيْتِ رَجُلًا خُرَاسَانِيًّا وَمَعَهُ فَتَاةٌ",uz:"xurosonlik bir erkakni va u bilan bir qizni ko'rdingizmi"},{ar:"فِي مِثْلِ عُمْرِي",uz:"mening yoshimdagi"}],full_uz:"Xurosonlik bir erkakni va u bilan mening yoshimdagi bir qizni ko'rdingizmi?",note:null},
{num:384,time:"00:35:27,179 --> 00:35:28,819",arabic:"يَسْأَلَانِنِي عَنْ فَتَاةٍ ضَائِعَةٍ",segs:null,full_uz:"Ular mendan yo'qolgan bir qiz haqida so'rashdi.",note:null},
{num:385,time:"00:35:28,819 --> 00:35:33,419",arabic:"مَا رَأَيْتُ وَلَا سَمِعْتُ قَطُّ عَنْ رَجُلٍ أَضَاعَ فَتَاةً",segs:[{ar:"مَا رَأَيْتُ وَلَا سَمِعْتُ قَطُّ",uz:"men hech qachon ko'rmaganman ham, eshitmaganman ham"},{ar:"عَنْ رَجُلٍ أَضَاعَ فَتَاةً",uz:"biror erkak qizni yo'qotgani haqida"}],full_uz:"Men hech qachon biror erkak qizni yo'qotgani haqida ko'rmaganman ham, eshitmaganman ham.",note:null},
{num:386,time:"00:35:33,419 --> 00:35:35,019",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o'zga kuch va quvvat yo'q.",note:null},
{num:387,time:"00:35:35,019 --> 00:35:40,359",arabic:"لِمَاذَا كُلُّ هَذَا الْخَوْفِ وَالْقَلَقِ فِي عَيْنَيْكِ",segs:[{ar:"لِمَاذَا كُلُّ هَذَا الْخَوْفِ وَالْقَلَقِ",uz:"nega bunchalik qo'rquv va xavotir"},{ar:"فِي عَيْنَيْكِ",uz:"ko'zlaringizda?"}],full_uz:"Nega ko'zlaringizda bunchalik qo'rquv va xavotir bor?",note:null},
{num:388,time:"00:35:40,359 --> 00:35:41,500",arabic:"مَا قِصَّتُكِ؟",segs:null,full_uz:"Hikoyangiz nima?",note:null},
{num:389,time:"00:35:41,500 --> 00:35:43,719",arabic:"لَقَدْ أَضَعْتُ أَبِي وَأُخْتِي فِي سُوقِ بَغْدَادَ",segs:[{ar:"لَقَدْ أَضَعْتُ أَبِي وَأُخْتِي",uz:"otam va singlimni yo'qotib qo'ydim"},{ar:"فِي سُوقِ بَغْدَادَ",uz:"Bag'dod bozorida"}],full_uz:"Otam va singlimni Bag'dod bozorida yo'qotib qo'ydim.",note:null},
{num:390,time:"00:35:43,719 --> 00:35:45,399",arabic:"وَأَنَا غَرِيبَةُ الدَّارِ",segs:null,full_uz:"Men bu yerda begonaman.",note:"غَرِيبَةُ الدَّارِ — bu joyda begona, musofir."},
{num:391,time:"00:35:45,399 --> 00:35:47,659",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:null,full_uz:"Allohdan o'zga kuch va quvvat yo'q.",note:null},
{num:392,time:"00:35:47,659 --> 00:35:50,779",arabic:"كُلُّنَا أَهْلُكِ يَا أُخْتِي تَفَضَّلِي",segs:[{ar:"كُلُّنَا أَهْلُكِ يَا أُخْتِي",uz:"barchamiz sening yaqinlaringmiz, ey singlim"},{ar:"تَفَضَّلِي",uz:"marhamat"}],full_uz:"Barchamiz sening yaqinlaringmiz, ey singlim. Marhamat.",note:null},
{num:393,time:"00:35:50,780 --> 00:35:53,460",arabic:"لَا وَجَزَاكَ اللَّهُ خَيْرًا",segs:null,full_uz:"Yo'q, Alloh sizni yaxshilik bilan mukofotlasin.",note:null},
{num:394,time:"00:35:53,460 --> 00:35:56,120",arabic:"يَجِبُ عَلَيَّ أَنْ أَذْهَبَ",segs:null,full_uz:"Men ketishim kerak.",note:null},
{num:395,time:"00:35:56,120 --> 00:35:59,880",arabic:"إِلَى أَيْنَ وَقَدِ اقْتَرَبَ اللَّيْلُ",segs:[{ar:"إِلَى أَيْنَ",uz:"qayerga?"},{ar:"وَقَدِ اقْتَرَبَ اللَّيْلُ",uz:"tun yaqinlashib qoldi-ku"}],full_uz:"Qayerga? Tun yaqinlashib qoldi-ku.",note:null},
{num:396,time:"00:35:59,880 --> 00:36:01,840",arabic:"أَلَمْ تَقُلْ إِنَّكِ غَرِيبَةٌ؟",segs:[{ar:"أَلَمْ تَقُلْ",uz:"aytmaganmidingiz"},{ar:"إِنَّكِ غَرِيبَةٌ؟",uz:"begona ekaningizni?"}],full_uz:"Begona ekaningizni aytmaganmidingiz?",note:null},
{num:397,time:"00:36:01,840 --> 00:36:03,660",arabic:"تَفَضَّلِي تَقْضِينَ اللَّيْلَةَ عِنْدِي",segs:[{ar:"تَفَضَّلِي",uz:"marhamat"},{ar:"تَقْضِينَ اللَّيْلَةَ عِنْدِي",uz:"bu tunni menikida o'tkazing"}],full_uz:"Marhamat, bu tunni menikida o'tkazing.",note:null},
{num:398,time:"00:36:03,660 --> 00:36:05,600",arabic:"وَفِي الصَّبَاحِ تُعَاوِدِينَ الْبَحْثَ",segs:[{ar:"وَفِي الصَّبَاحِ",uz:"ertalab"},{ar:"تُعَاوِدِينَ الْبَحْثَ",uz:"qidirishni davom ettirasiz"}],full_uz:"Ertalab qidirishni davom ettirasiz.",note:null},
{num:399,time:"00:36:05,600 --> 00:36:08,780",arabic:"أَحْسَنَ اللَّهُ لَكِ وَلَكِنْ يَجِبُ عَلَيَّ أَنْ أَذْهَبَ",segs:[{ar:"أَحْسَنَ اللَّهُ لَكِ",uz:"Alloh sizni yaxshilik bilan mukofotlasin"},{ar:"وَلَكِنْ يَجِبُ عَلَيَّ أَنْ أَذْهَبَ",uz:"lekin men ketishim kerak"}],full_uz:"Alloh sizni yaxshilik bilan mukofotlasin, lekin men ketishim kerak.",note:null},
{num:400,time:"00:36:08,780 --> 00:36:11,720",arabic:"لَعَلَّنِي أَجِدُهُمَا فِي أَحَدِ النُّزُلِ أَوْ حَيْثُ تَرَكْنَا الْقَافِلَةَ",segs:[{ar:"لَعَلَّنِي أَجِدُهُمَا فِي أَحَدِ النُّزُلِ",uz:"balki ularni mehmonxonalardan biridan toparman"},{ar:"أَوْ حَيْثُ تَرَكْنَا الْقَافِلَةَ",uz:"yoki karvonni qoldirgan joyimizdan"}],full_uz:"Balki ularni mehmonxonalardan biridan yoki karvonni qoldirgan joyimizdan toparman.",note:"النُّزُلُ — mehmonxonalar, tunash joylari."},
{num:401,time:"00:36:11,720 --> 00:36:15,200",arabic:"كَمَا تُرِيدِينَ وَلَكِنْ أَنَا وَزَوْجِي رَهْنُ أَمْرِكِ",segs:[{ar:"كَمَا تُرِيدِينَ",uz:"xohlaganingizdek"},{ar:"وَلَكِنْ أَنَا وَزَوْجِي رَهْنُ أَمْرِكِ",uz:"lekin men va erim sizning ixtiyoringizdamiz"}],full_uz:"Xohlaganingizdek. Lekin men va erim sizning ixtiyoringizdamiz.",note:"رَهْنُ أَمْرِكِ — sizning ixtiyoringizda, buyrug'ingizga tayyor."},
{num:402,time:"00:36:15,200 --> 00:36:18,080",arabic:"زَوْجِي يَعْرِفُ كُلَّ نُزُلِ بَغْدَادَ",segs:[{ar:"زَوْجِي يَعْرِفُ",uz:"erim biladi"},{ar:"كُلَّ نُزُلِ بَغْدَادَ",uz:"Bag'doddagi barcha mehmonxonalarni"}],full_uz:"Erim Bag'doddagi barcha mehmonxonalarni biladi.",note:null},
{num:403,time:"00:36:18,080 --> 00:36:19,880",arabic:"وَإِنْ لَمْ نَجِدْهُمَا فِي النُّزُلِ",segs:null,full_uz:"Agar ularni mehmonxonalardan topmasak.",note:null},
{num:404,time:"00:36:19,880 --> 00:36:22,320",arabic:"أَذْهَبُ بِكِ إِلَى حَيْثُ تَقِفُ قَافِلَتُكُمْ",segs:[{ar:"أَذْهَبُ بِكِ",uz:"sizni olib boraman"},{ar:"إِلَى حَيْثُ تَقِفُ قَافِلَتُكُمْ",uz:"karvoningiz turgan joyga"}],full_uz:"Sizni karvoningiz turgan joyga olib boraman.",note:null},
{num:405,time:"00:36:22,320 --> 00:36:24,119",arabic:"أَكُونُ لَكُمْ مِنَ الشَّاكِرِينَ",segs:null,full_uz:"Sizdan juda minnatdor bo'laman.",note:"مِنَ الشَّاكِرِينَ — minnatdor bo'lganlardan."},
{num:406,time:"00:36:24,119 --> 00:36:26,740",arabic:"لَا دَاعِيَ لِلشُّكْرِ هَذَا وَاجِبُنَا",segs:[{ar:"لَا دَاعِيَ لِلشُّكْرِ",uz:"minnatdorchilikka hojat yo'q"},{ar:"هَذَا وَاجِبُنَا",uz:"bu bizning vazifamiz"}],full_uz:"Minnatdorchilikka hojat yo'q, bu bizning vazifamiz.",note:null},
{num:407,time:"00:36:26,740 --> 00:36:31,079",arabic:"تَفَضَّلِي تَفَضَّلِي إِلَى أَنْ يَتَجَهَّزَ زَوْجِي لِلْخُرُوجِ تَفَضَّلِي",segs:[{ar:"تَفَضَّلِي تَفَضَّلِي",uz:"marhamat, marhamat"},{ar:"إِلَى أَنْ يَتَجَهَّزَ زَوْجِي لِلْخُرُوجِ",uz:"erim chiqishga tayyorlanguncha"},{ar:"تَفَضَّلِي",uz:"marhamat"}],full_uz:"Marhamat, marhamat. Erim chiqishga tayyorlanguncha, marhamat.",note:null},
{num:408,time:"00:36:31,079 --> 00:36:35,460",arabic:"أَهْلًا وَمَرْحَبًا أَهْلًا وَسَهْلًا أَهْلًا وَسَهْلًا تَفَضَّلِي",segs:[{ar:"أَهْلًا وَمَرْحَبًا",uz:"xush kelibsiz"},{ar:"أَهْلًا وَسَهْلًا",uz:"xush kelibsiz"},{ar:"أَهْلًا وَسَهْلًا",uz:"xush kelibsiz"},{ar:"تَفَضَّلِي",uz:"marhamat"}],full_uz:"Xush kelibsiz, xush kelibsiz, xush kelibsiz. Marhamat.",note:null},
{num:409,time:"00:36:35,460 --> 00:36:42,360",arabic:"تَفَضَّلِي إِلَى الدَّاخِلِ لِسْتُ مَا أَطْلُبُ مِنْ زَوْجِي أَنْ يَتَأَهَّبَ لِلْخُرُوجِ",segs:[{ar:"تَفَضَّلِي إِلَى الدَّاخِلِ",uz:"ichkariga marhamat"},{ar:"أَلَيْسَ مَا أَطْلُبُ مِنْ زَوْجِي أَنْ يَتَأَهَّبَ لِلْخُرُوجِ؟",uz:"erimdan chiqishga tayyorlanishini so'ramayapmanmi?"}],full_uz:"Ichkariga marhamat. Axir erimdan chiqishga tayyorlanishini so'ramayapmanmi?",note:null},
{num:410,time:"00:37:22,460 --> 00:37:22,460",arabic:"لَمْ أُغْلِقْ دِيمَا بِيَا سَيِّدَتِي",segs:null,full_uz:"Men, xonim, Dima bilan eshikni yopmadim.",note:null},
{num:411,time:"00:38:10,220 --> 00:38:13,119",arabic:"السَّلَامُ عَلَيْكُمْ يَا أَخِي",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"sizga salom bo'lsin"},{ar:"يَا أَخِي",uz:"ey birodar"}],full_uz:"Sizga salom bo'lsin, ey birodar.",note:null},
{num:412,time:"00:38:13,119 --> 00:38:15,140",arabic:"وَعَلَيْكُمُ السَّلَامُ",segs:null,full_uz:"Sizga ham salom.",note:null},
{num:413,time:"00:38:15,140 --> 00:38:18,840",arabic:"خَيْرًا يَا أُخْتَاهُ مَا خَطْبُكِ",segs:[{ar:"خَيْرًا يَا أُخْتَاهُ",uz:"yaxshi, ey singlim"},{ar:"مَا خَطْبُكِ",uz:"sizga nima bo'ldi?"}],full_uz:"Yaxshi, ey singlim. Sizga nima bo'ldi?",note:"مَا خَطْبُكِ — sizga nima bo'ldi?, muammoingiz nima?"},

{num:414,time:"00:38:18,840 --> 00:38:21,880",arabic:"أَنَا غَرِيبَةٌ عَنْ بَغْدَادَ",segs:null,full_uz:"Men Bag'dodda begonaman.",note:null},
{num:415,time:"00:38:21,880 --> 00:38:24,880",arabic:"وَقَدْ أَضَعْتُ أَبِي وَأُخْتِي",segs:null,full_uz:"Men otam va singlimni yo'qotib qo'ydim.",note:null},
{num:416,time:"00:38:24,880 --> 00:38:32,880",arabic:"لَا أَدْرِي نَسِيتُ نَفْسِي فَلَمْ أَجِدْنِي إِلَّا بَعِيدَةً عَنْهُمْ تَائِهَةً فِي السُّوقِ",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"نَسِيتُ نَفْسِي",uz:"o'zimni unutib qo'ydim"},{ar:"فَلَمْ أَجِدْنِي إِلَّا بَعِيدَةً عَنْهُمْ",uz:"o'zimni ulardan uzoqda topdim"},{ar:"تَائِهَةً فِي السُّوقِ",uz:"bozorda sarson bo'lib"}],full_uz:"Bilmayman. O'zimni unutib qo'yibman, o'zimni ulardan uzoqda, bozorda sarson bo'lib yurgan holda topdim.",note:null},
{num:417,time:"00:38:32,880 --> 00:38:34,880",arabic:"مِنْ أَيِّ الْبِلَادِ أَنْتِ؟",segs:null,full_uz:"Qaysi yurtdansiz?",note:null},
{num:418,time:"00:38:34,880 --> 00:38:36,880",arabic:"خُرَاسَانُ",segs:null,full_uz:"Xuroson.",note:null},
{num:419,time:"00:38:36,880 --> 00:38:40,880",arabic:"خُرَاسَانُ؟ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",segs:[{ar:"خُرَاسَانُ؟",uz:"Xuroson?"},{ar:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",uz:"Allohdan o'zga kuch va quvvat yo'q"}],full_uz:"Xuroson? Allohdan o'zga kuch va quvvat yo'q.",note:null},
{num:420,time:"00:38:40,880 --> 00:38:47,820",arabic:"هَلْ لَا سَاعَدْتَنِي فِي الْبَحْثِ عَنْهُمَا؟",segs:null,full_uz:"Ularni izlashimga yordam bermaysizmi?",note:null},
{num:421,time:"00:38:47,820 --> 00:38:49,900",arabic:"لَقَدْ ضَلَلْتُ الطَّرِيقَ هُنَا",segs:null,full_uz:"Bu yerda yo'ldan adashib qoldim.",note:"ضَلَّ الطَّرِيقَ — yo'ldan adashmoq."},
{num:422,time:"00:38:49,900 --> 00:38:51,780",arabic:"كَرَامَةٌ وَمُرُوءَةٌ يَا أَخِي",segs:[{ar:"كَرَامَةٌ وَمُرُوءَةٌ",uz:"bu sharaf va mardlik"},{ar:"يَا أَخِي",uz:"ey birodar"}],full_uz:"Bu sharaf va mardlik, ey birodar.",note:"مُرُوءَةٌ — mardlik, olijanoblik."},
{num:423,time:"00:38:51,780 --> 00:38:56,400",arabic:"وَلَكِنْ هَا أَنْتِ تَرَيْنَ أَنَّ الْمَسَاءَ قَدْ حَلَّ",segs:[{ar:"وَلَكِنْ هَا أَنْتِ تَرَيْنَ",uz:"lekin o'zingiz ko'rib turibsiz"},{ar:"أَنَّ الْمَسَاءَ قَدْ حَلَّ",uz:"kech kirganini"}],full_uz:"Lekin o'zingiz ko'rib turibsiz, kech kirgan.",note:null},
{num:424,time:"00:38:56,400 --> 00:38:59,420",arabic:"وَالسُّوقُ قَدْ أُغْلِقَ إِلَّا مِنْ بَعْضِ أَهْلِهِ",segs:[{ar:"وَالسُّوقُ قَدْ أُغْلِقَ",uz:"bozor yopilgan"},{ar:"إِلَّا مِنْ بَعْضِ أَهْلِهِ",uz:"faqat ayrim savdogarlar qolgan"}],full_uz:"Bozor ham yopilgan, faqat ayrim savdogarlar qolgan.",note:null},
{num:425,time:"00:38:59,420 --> 00:39:01,820",arabic:"فَإِنْ نَبْحَثْ عَنْهُمْ",segs:null,full_uz:"Unda ularni izlasak...",note:null},
{num:426,time:"00:39:01,820 --> 00:39:05,280",arabic:"أَلَكِ قَرَابَةٌ هُنَا حَتَّى آخُذَكِ إِلَيْهِمْ",segs:[{ar:"أَلَكِ قَرَابَةٌ هُنَا",uz:"bu yerda qarindoshingiz bormi"},{ar:"حَتَّى آخُذَكِ إِلَيْهِمْ",uz:"sizni ularning oldiga olib borishim uchun"}],full_uz:"Sizni ularning oldiga olib borishim uchun bu yerda qarindoshingiz bormi?",note:null},
{num:427,time:"00:39:05,280 --> 00:39:07,099",arabic:"فَرُبَّمَا يَكُونُ أَهْلُكِ عِنْدَهُمْ",segs:[{ar:"فَرُبَّمَا يَكُونُ أَهْلُكِ عِنْدَهُمْ",uz:"balki oilangiz ularning oldidadir"}],full_uz:"Balki oilangiz ularning oldidadir.",note:null},
{num:428,time:"00:39:07,099 --> 00:39:09,220",arabic:"لَا",segs:null,full_uz:"Yo'q.",note:null},
{num:429,time:"00:39:09,219 --> 00:39:13,480",arabic:"لَيْسَ لِي فِي بَغْدَادَ قَرَابَةٌ",segs:null,full_uz:"Bag'dodda hech qanday qarindoshim yo'q.",note:null},
{num:430,time:"00:39:13,480 --> 00:39:16,279",arabic:"لَقَدْ أَضَعْتُ أَبِي",segs:null,full_uz:"Otamni yo'qotib qo'ydim.",note:null},
{num:431,time:"00:39:16,279 --> 00:39:20,299",arabic:"وَلَيْسَ لِي أَحَدٌ فِي هَذِهِ الْبِلَادِ",segs:[{ar:"وَلَيْسَ لِي أَحَدٌ",uz:"mening hech kimim yo'q"},{ar:"فِي هَذِهِ الْبِلَادِ",uz:"bu yurtda"}],full_uz:"Bu yurtda mening hech kimim yo'q.",note:null},
{num:432,time:"00:39:20,299 --> 00:39:21,639",arabic:"هَوِّنِي عَلَيْكِ يَا أُخْتِي",segs:[{ar:"هَوِّنِي عَلَيْكِ",uz:"o'zingizni boshing"},{ar:"يَا أُخْتِي",uz:"ey singlim"}],full_uz:"O'zingizni bosing, ey singlim.",note:"هَوِّنَ عَلَى — taskin bermoq, o'zini bosishga undamoq."},
{num:433,time:"00:39:21,639 --> 00:39:22,939",arabic:"هَوِّنِي عَلَيْكِ",segs:null,full_uz:"O'zingizni bosing.",note:null},
{num:434,time:"00:39:22,939 --> 00:39:24,279",arabic:"فَكُلُّ بَغْدَادَ أَهْلُكِ",segs:[{ar:"فَكُلُّ بَغْدَادَ",uz:"butun Bag'dod"},{ar:"أَهْلُكِ",uz:"sening yaqinlaring"}],full_uz:"Butun Bag'dod sening yaqinlaring.",note:null},
{num:435,time:"00:39:24,279 --> 00:39:25,500",arabic:"هَوِّنِي عَلَيْكِ",segs:null,full_uz:"O'zingizni bosing.",note:null},
{num:436,time:"00:39:35,500 --> 00:39:38,259",arabic:"مَا زِلْتُ مُنْتَظِرَةً كَلَامَكَ",segs:[{ar:"مَا زِلْتُ مُنْتَظِرَةً",uz:"hali ham kutyapman"},{ar:"كَلَامَكَ",uz:"gapirishingni"}],full_uz:"Hali ham gapirishingni kutyapman.",note:null},
{num:437,time:"00:39:38,260 --> 00:39:42,340",arabic:"كَرَامِي فِي مَاذَا؟",segs:null,full_uz:"Karami, nima haqida?",note:null},
{num:438,time:"00:39:42,340 --> 00:39:45,280",arabic:"فِيمَا يَشْغَلُ عَقْلَكَ وَيَمْلِكُ عَلَيْكَ لُبَّكَ",segs:[{ar:"فِيمَا يَشْغَلُ عَقْلَكَ",uz:"aqlingni band qilayotgan narsa haqida"},{ar:"وَيَمْلِكُ عَلَيْكَ لُبَّكَ",uz:"va butun fikringni egallagan narsa haqida"}],full_uz:"Aqlingni band qilayotgan va butun fikringni egallagan narsa haqida.",note:"لُبٌّ — aql, idrok, fikr."},
{num:439,time:"00:39:45,280 --> 00:39:47,240",arabic:"لَا شَيْءَ مُهِمٌّ",segs:null,full_uz:"Muhim hech narsa yo'q.",note:null},
{num:440,time:"00:39:47,240 --> 00:39:52,860",arabic:"أَخْبِرْ أُمَّكَ أَوَّلًا وَهِيَ مَنْ تُقَرِّرُ إِنْ كَانَ مُهِمًّا أَمْ لَا",segs:[{ar:"أَخْبِرْ أُمَّكَ أَوَّلًا",uz:"avval onangga ayt"},{ar:"وَهِيَ مَنْ تُقَرِّرُ",uz:"u qaror qiladi"},{ar:"إِنْ كَانَ مُهِمًّا أَمْ لَا",uz:"bu muhim yoki muhim emasligini"}],full_uz:"Avval onangga ayt, bu muhim yoki muhim emasligini u hal qiladi.",note:null},
{num:441,time:"00:39:52,860 --> 00:39:55,540",arabic:"لَا أُرِيدُ أَنْ أَشْغَلَكِ بِهِ",segs:[{ar:"لَا أُرِيدُ",uz:"istamayman"},{ar:"أَنْ أَشْغَلَكِ بِهِ",uz:"sizni bu bilan band qilishni"}],full_uz:"Sizni bu bilan band qilishni istamayman.",note:null},
{num:442,time:"00:39:55,540 --> 00:39:57,400",arabic:"أَحْمَدُ",segs:null,full_uz:"Ahmad.",note:null},
{num:443,time:"00:39:57,400 --> 00:40:02,380",arabic:"كَمَا تَشَاءِينَ يَا أُمَّ أَحْمَدَ",segs:[{ar:"كَمَا تَشَاءِينَ",uz:"xohlaganingizdek"},{ar:"يَا أُمَّ أَحْمَدَ",uz:"ey Ahmadning onasi"}],full_uz:"Xohlaganingizdek, ey Ahmadning onasi.",note:null},
{num:444,time:"00:40:03,640 --> 00:40:07,600",arabic:"قَدْ عَرَضَ عَلَيَّ عَمِّي الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ نَسَّاخًا لِلْكُتُبِ",segs:[{ar:"قَدْ عَرَضَ عَلَيَّ عَمِّي الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ",uz:"amaki menga Bayt ul-Hikmada ish taklif qildi"},{ar:"نَسَّاخًا لِلْكُتُبِ",uz:"kitoblarni ko'chiruvchi sifatida"}],full_uz:"Amaki menga Bayt ul-Hikmada kitoblarni ko'chiruvchi sifatida ishlashni taklif qildi.",note:null},
];

